        'info_body' => 'ഒരു പങ്കിട്ട ഇൻടേക്ക് മെയിൽബോക്സ്, അയച്ചയാളുടെ ഡൊമെയ്ൻ ഉടമസ്ഥതയുള്ള കമ്പനിയിലേക്ക് ഓരോ ഇമെയിലും റൂട്ട് ചെയ്യുന്നു. ഒരു കമ്പനിയുടെയും ഡൊമെയ്നുമായി പൊരുത്തപ്പെടാത്തത് ഇവിടെ വന്നുചേരും, അതിനാൽ അത് ഒരിക്കലും നഷ്ടപ്പെടില്ല. ഒരു കമ്പനിയുടെ സ്വന്തം ഡൊമെയ്നിൽ നിന്ന് ഒരു ടിക്കറ്റ് ഫയൽ ചെയ്യുമ്പോൾ നിങ്ങൾക്ക് <strong>ആ ഡൊമെയ്ൻ റൂട്ട് ചെയ്യാനും</strong> കഴിയും, അത് അതിന്റെ മറ്റ് ക്യൂവിലുള്ള മെയിലും നീക്കുകയും ഭാവി മെയിൽ സ്വയമേവ റൂട്ട് ചെയ്യുകയും ചെയ്യും. <strong>പൊതു പ്രൊവൈഡറുകളിലെ</strong> (Gmail, Outlook, Yahoo, iCloud, …) വിലാസങ്ങൾ <em>പൊതു ഇമെയിൽ</em> എന്ന് ടാഗ് ചെയ്യപ്പെടുന്നു — അവയുടെ മുഴുവൻ ഡൊമെയ്‌നും റൂട്ട് ചെയ്യാനാവില്ല (ബന്ധമില്ലാത്ത പലരും അത് പങ്കിടുന്നു), പക്ഷേ നിങ്ങൾക്ക് <strong>ഒരു വ്യക്തിഗത വിലാസം റൂട്ട് ചെയ്യാം</strong>, അങ്ങനെ ആ ഒരാളുടെ മെയിൽ ശരിയായ കമ്പനിയിലേക്ക് സ്വയമേവ എത്തും.',
