            'orig_html_help' => 'സന്ദേശങ്ങൾ അവയുടെ യഥാർത്ഥ ടിക്കറ്റുകളിൽ തന്നെ നിലനിൽക്കും, ലയിപ്പിച്ച ടിക്കറ്റിന് അറ്റാച്ച് ചെയ്ത കോപ്പികൾ മാത്രം ലഭിക്കും. ഏറ്റവും വൃത്തിയുള്ള ലയിപ്പിച്ച ടിക്കറ്റ്, പക്ഷേ തിരച്ചിൽ സന്ദേശങ്ങൾ വായിക്കുന്നതല്ലാതെ അറ്റാച്ച്മെന്റുകൾ വായിക്കാത്തതിനാൽ ലയിപ്പിച്ച സംഭാഷണങ്ങൾ ഇനി തിരച്ചിലിൽ കണ്ടെത്തില്ല.',
