            'opportunistic_help' => 'ആരെങ്കിലും ഇതിനകം FreeITSM ൽ പ്രവർത്തിക്കുമ്പോൾ കാത്തിരിക്കുന്ന കുറച്ച് പ്രമാണങ്ങൾ എടുക്കുന്നു. ഷെഡ്യൂൾ ചെയ്ത ടാസ്കുകളില്ലാത്ത ഒരു ഇൻസ്റ്റലേഷനിലും അറ്റാച്ച്മെന്റ് തിരച്ചിൽ തുടക്കം മുതൽ പ്രവർത്തിക്കും എന്നാണ് ഇതിനർത്ഥം. ബോധപൂർവ്വം ഒരു തവണ കുറച്ച് മാത്രമേ എടുക്കൂ, അതിനാൽ ആരും കാത്തിരിക്കേണ്ടി വരില്ല.',
