            'empty_warn_title' => 'മുന്നറിയിപ്പ് നൽകി രേഖപ്പെടുത്തുക',
            'empty_warn_desc' => 'അനലിസ്റ്റിനോട് സ്ഥിരീകരിക്കാൻ ചോദിക്കുകയും ചേർക്കൽ ഡയലോഗ് വാഗ്ദാനം ചെയ്യുകയും ചെയ്യും. എന്നാലും അടയ്ക്കുന്നത് ചെക്ക്‌ലിസ്റ്റ് ഇല്ലാതെ ടിക്കറ്റ് അടച്ചു എന്നും ആരാണ് അടച്ചതെന്നും പറയുന്ന ഒരു ഇന്റേണൽ കുറിപ്പ് എഴുതും.',
            'empty_block_title' => 'അടയ്ക്കൽ നിരസിക്കുക',
            'empty_block_desc' => 'കുറഞ്ഞത് ഒരു ചെക്ക്‌ലിസ്റ്റ് ചേർക്കുന്നതുവരെ ടിക്കറ്റിന് അടച്ച നിലയിൽ എത്താൻ കഴിയില്ല.',
            'always_recorded' => 'ഏത് വിധത്തിലായാലും, ബാക്കിയുള്ള ഘട്ടങ്ങളോടെ അടയ്ക്കുന്നത് ഒഴിവാക്കിയ ഘട്ടങ്ങൾ, ആരാണ് അടച്ചത്, ഏത് ഇന്റർഫേസ് വഴിയാണ് എന്ന് പേരെടുത്ത് ഒരു ഇന്റേണൽ കുറിപ്പ് എഴുതും. ഇത് അനുവദനീയമാണോ എന്നാണ് ഈ ക്രമീകരണങ്ങൾ തീരുമാനിക്കുന്നത്, ഇത് ലോഗ് ചെയ്യുമോ എന്നല്ല.',
        ],
        'mandatory' => [
            'when_heading' => 'ടിക് ചെയ്ത ഒരു ഫീൽഡ് ശൂന്യമായി ടിക്കറ്റ് അടയ്ക്കുമ്പോൾ',
            'warn_title' => 'മുന്നറിയിപ്പ് നൽകുക',
            'warn_desc' => 'ഏത് ഫീൽഡുകളാണ് ശൂന്യമെന്ന് അനലിസ്റ്റിനോട് പറയും, എന്നിട്ടും അടയ്ക്കാം.',
            'notify_title' => 'മുന്നറിയിപ്പ് നൽകുക, ആരെയെങ്കിലും ഇമെയിൽ ചെയ്യുക',
            'notify_desc' => 'അതേത്, കൂടാതെ താഴെയുള്ള ആളുകൾക്ക് ടിക്കറ്റ്, ശൂന്യമായ ഫീൽഡുകൾ, ആരാണ് അടച്ചത് എന്ന് പേരിട്ട ഒരു ഇമെയിൽ ലഭിക്കും - ഉദാഹരണത്തിന് ഒരു സർവീസ് ഡെലിവറി മാനേജർ.',
            'notify_label' => 'ഇമെയിൽ അയക്കേണ്ടത്',
            'notify_placeholder' => 'name@example.com, another@example.com',
            'block_title' => 'അടയ്ക്കൽ നിരസിക്കുക',
            'block_desc' => 'ടിക് ചെയ്ത എല്ലാ ഫീൽഡും പൂരിപ്പിക്കുന്നത് വരെ ടിക്കറ്റിന് ക്ലോസ്ഡ് നിലയിൽ എത്താനാകില്ല.',
            'record_title' => 'ടിക്കറ്റിൽ ഇത് രേഖപ്പെടുത്തുക',
            'record_desc' => 'ശൂന്യമായ ഫീൽഡുകൾ, ആരാണ് ടിക്കറ്റ് അടച്ചത്, എങ്ങനെ എന്ന് പേരിട്ട ഒരു ആന്തരിക കുറിപ്പ് എഴുതും. രണ്ട് മുന്നറിയിപ്പ് ഓപ്ഷനുകൾക്ക് മാത്രമേ ഇത് ബാധകമാകൂ - നിരസിച്ച ഒരു അടയ്ക്കൽ ഒന്നും മാറ്റുന്നില്ല, അതിനാൽ രേഖപ്പെടുത്താൻ ഒന്നുമില്ല.',
            'record_blocked' => 'അടയ്ക്കൽ നിരസിക്കുമ്പോൾ ഒന്നും രേഖപ്പെടുത്തില്ല, കാരണം ടിക്കറ്റ് അടയുന്നില്ല.',
            'fields_heading' => 'അടയ്ക്കുന്നതിന് മുമ്പ് പൂരിപ്പിക്കണം',
            'fields_hint' => 'ഒരു ടിക്കറ്റിന്റെ കമ്പനിക്ക് ഓഫ് ചെയ്തിട്ടുള്ള ഒരു ഫീൽഡ്, അല്ലെങ്കിൽ ടീമുകളില്ലാത്ത ഒരു ഇൻസ്റ്റലേഷനിലെ ടീം ഫീൽഡ്, ആ ടിക്കറ്റിന് ഒഴിവാക്കപ്പെടും - കാണാൻ കഴിയാത്ത എന്തെങ്കിലും പൂരിപ്പിക്കാൻ ആരോടും ആവശ്യപ്പെടില്ല. ടിക്കറ്റുകൾ ലയിപ്പിക്കുന്നത് ഇത് ഒരിക്കലും ട്രിഗ്ഗർ ചെയ്യില്ല.',
            'choose_mode' => 'ഫീൽഡുകൾ ശൂന്യമാകുമ്പോൾ എന്ത് സംഭവിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക.',
            'need_address' => 'ഇമെയിൽ ചെയ്യാൻ കുറഞ്ഞത് ഒരു വിലാസമെങ്കിലും ചേർക്കുക.',
