        'intros' => [
            'checklists' => 'ഒരു ചെക്ക്‌ലിസ്റ്റിന് ഘട്ടങ്ങൾ നിർബന്ധിതമായി അടയാളപ്പെടുത്താം. ആ ഘട്ടങ്ങൾ ടിക് ചെയ്യുന്നതിന് മുമ്പ് ആരെങ്കിലും ഒരു ടിക്കറ്റ് അടച്ചാൽ എന്ത് സംഭവിക്കും എന്ന് ഇത് തീരുമാനിക്കുന്നു.',
            'mandatory_fields' => 'ഒരു ടിക്കറ്റ് അടയ്ക്കുന്നതിന് മുമ്പ് ഏത് ടിക്കറ്റ് ഫീൽഡുകൾ പൂരിപ്പിക്കണം എന്നും, അവയിലേതെങ്കിലും ശൂന്യമായി ഒരാൾ ഒന്ന് അടച്ചാൽ എന്ത് സംഭവിക്കും എന്നും തിരഞ്ഞെടുക്കുക. ടിക്കറ്റ് സ്ക്രീൻ, ബൾക്ക് ആക്ഷനുകൾ, REST API, വർക്ക്ഫ്ലോകൾ എന്നിങ്ങനെ ഒരു ടിക്കറ്റ് അടയ്ക്കാവുന്ന എല്ലായിടത്തും ഈ നിയമം ബാധകമാണ്.',
            'departments' => 'വകുപ്പുകൾ ടിക്കറ്റുകളെ ഗ്രൂപ്പ് ചെയ്ത് നിങ്ങളുടെ ഓർഗനൈസേഷന്റെ ശരിയായ മേഖലയിലേക്ക് റൂട്ട് ചെയ്യുന്നു — നിങ്ങളുടെ സർവീസ് ഡെസ്ക് ജോലി വർഗ്ഗീകരിക്കാനും അസൈൻ ചെയ്യാനും ഉപയോഗിക്കുന്നവ സൃഷ്ടിക്കുക.',
            'teams' => 'അനലിസ്റ്റുകൾക്ക് ഏത് വകുപ്പുകൾ ആക്സസ് ചെയ്യാമെന്ന് ടീമുകൾ നിശ്ചയിക്കുന്നു. വകുപ്പുകളെ ടീമുകൾക്ക് അസൈൻ ചെയ്യുക, എന്നിട്ട് അവരുടെ ആക്സസ് നിയന്ത്രിക്കാൻ അനലിസ്റ്റുകളെ ടീമുകൾക്ക് അസൈൻ ചെയ്യുക.',
            'ticket_types' => 'ടിക്കറ്റ് തരങ്ങൾ ഒരു അഭ്യർത്ഥന എന്താണെന്ന് വർഗ്ഗീകരിക്കുന്നു (ഉദാ. Incident, Service Request) — അനലിസ്റ്റുകൾക്ക് ഒരു ടിക്കറ്റിൽ സെറ്റ് ചെയ്യാവുന്ന തരങ്ങൾ നിർവചിക്കുക.',
            'ticket_origins' => 'ടിക്കറ്റ് ഉറവിടങ്ങൾ ഒരു ടിക്കറ്റ് എങ്ങനെ വന്നു എന്ന് രേഖപ്പെടുത്തുന്നു (ഉദാ. Email, Phone, Portal) — അനലിസ്റ്റുകൾക്ക് തിരഞ്ഞെടുക്കാവുന്ന ഉറവിടങ്ങൾ നിർവചിക്കുക.',
            'mailboxes' => 'ഇൻകമിംഗ് സന്ദേശങ്ങൾ ടിക്കറ്റുകളാകാനും മറുപടികൾ തിരികെ പോകാനും മെയിൽബോക്സുകൾ FreeITSM നെ ഇമെയിൽ അക്കൗണ്ടുകളുമായി ബന്ധിപ്പിക്കുന്നു — നിങ്ങളുടെ സർവീസ് ഡെസ്ക് നിരീക്ഷിക്കുന്നവ ചേർത്ത് ഓതന്റിക്കേറ്റ് ചെയ്യുക.',
            'privacy' => 'ഒരു ടിക്കറ്റിൽ അത് ഉയർത്തിയ ആളുമായുള്ള നിങ്ങളുടെ സംഭാഷണം മാത്രമല്ല ഉള്ളത്. ഒരു വിതരണക്കാരന് ഫോർവേഡ് ചെയ്യുന്നതോ ഒരു സഹപ്രവർത്തകനെ കോപ്പി ചെയ്യുന്നതോ ആ സന്ദേശം അതേ ടിക്കറ്റിൽ ഇടുന്നു — അവരുടെ മറുപടിയും അവിടെ എത്തും. അതിൽ എത്രത്തോളം അഭ്യർത്ഥിച്ചയാൾ സെൽഫ്-സർവീസ് പോർട്ടലിൽ കാണും എന്ന് ഇത് തീരുമാനിക്കുന്നു.',
            'indexing' => 'അറ്റാച്ച്മെന്റുകൾക്കുള്ളിലെ ടെക്സ്റ്റ് തിരയാൻ കഴിയുന്നതിനായി വായിക്കുന്നു. Word, Excel, PowerPoint, പ്ലെയിൻ ടെക്സ്റ്റ് ഫയലുകൾ FreeITSM തന്നെ, അവ എത്തുന്ന നിമിഷം വായിക്കുന്നു. PDF-കൾ, പഴയ Office ഫയലുകൾ, സ്കാൻ ചെയ്ത പ്രമാണങ്ങൾ എന്നിവയ്ക്ക് വേറിട്ട ഒരു പ്രമാണം-വായന സേവനം വേണം — അത് <strong>System &rarr; Integrations &rarr; Apache Tika</strong> എന്നതിന് കീഴിൽ സെറ്റപ്പ് ചെയ്യുക — അവയ്ക്ക് വളരെയധികം സമയമെടുക്കുന്നതിനാൽ, അവ ബാക്ഗ്രൗണ്ടിൽ വായിക്കുന്നു. ഈ രണ്ട് സ്വിച്ചുകളും ആ ബാക്ഗ്രൗണ്ട് ജോലി എപ്പോൾ നടക്കും എന്ന് തീരുമാനിക്കുന്നു.',
            'merge_behaviour' => 'രണ്ട് ടിക്കറ്റുകൾ ഒരേ കാര്യമാണെന്ന് തെളിഞ്ഞാൽ, ഒരു അനലിസ്റ്റിന് അവയെ ലയിപ്പിക്കാം. നിങ്ങളുടെ അഭ്യർത്ഥിച്ചവരുടെ കൈയിലുള്ള ടിക്കറ്റ് റഫറൻസുകളെ അത് എന്ത് ചെയ്യുമെന്നും, സംഭാഷണങ്ങൾക്ക് എന്ത് സംഭവിക്കുമെന്നും ഈ ക്രമീകരണങ്ങൾ തീരുമാനിക്കുന്നു. ഇവ എല്ലാവർക്കും ബാധകമാണ് — ഒരു ലയനം ഉപഭോക്താവ് കാണുന്നത് മാറ്റുന്നു, അതിനാൽ ഒരേ മെയിൽബോക്സിലെ രണ്ട് അനലിസ്റ്റുകൾക്ക് ഇതിനെക്കുറിച്ച് വിയോജിക്കാൻ കഴിയരുത്.',
            'reply_templates' => 'വീണ്ടും ടൈപ്പ് ചെയ്യുന്നതിന് പകരം നിങ്ങളുടെ അനലിസ്റ്റുകൾക്ക് ഒരു മറുപടിയിലേക്ക് ഇടാവുന്ന തയ്യാറാക്കിയ മറുപടികൾ. മുഴുവൻ ടീമും കാണുന്ന പങ്കിട്ടവയാണ് ഇവ — ഒരു അനലിസ്റ്റിന്റെ സ്വന്തം സ്വകാര്യ ടെംപ്ലേറ്റുകൾ റിപ്ലൈ വിൻഡോയിൽ നിന്ന് സേവ് ചെയ്യുന്നു, ഇവിടെ ലിസ്റ്റ് ചെയ്യുന്നില്ല.',
            'rota_shifts' => 'ഷിഫ്റ്റുകൾ എന്നത് അനലിസ്റ്റുകൾക്ക് സ്റ്റാഫ് റോട്ടയിൽ അസൈൻ ചെയ്യുന്ന പ്രവൃത്തി-പാറ്റേൺ ടെംപ്ലേറ്റുകളാണ് (ഉദാ. Early, Late, On-call) — റോട്ട നിർമ്മിക്കുന്നതിന് മുമ്പ് ഇവിടെ അവ നിർവചിക്കുക.',
            'analysts' => 'ലോഗിൻ ചെയ്ത് ടിക്കറ്റുകൾ കൈകാര്യം ചെയ്യുന്ന സ്റ്റാഫാണ് അനലിസ്റ്റുകൾ — അവരെ ചേർക്കുക, പാസ്‌വേഡുകൾ റീസെറ്റ് ചെയ്യുക, അവരുടെ ആക്സസ് നിയന്ത്രിക്കാൻ ടീമുകൾക്ക് അസൈൻ ചെയ്യുക.',
            'general' => 'സർവീസ് ഡെസ്ക് പേര്, സ്ഥിരസ്ഥിതികൾ പോലുള്ള സിസ്റ്റം-വ്യാപകമായ ഓപ്ഷനുകൾ ജനറൽ ക്രമീകരണങ്ങൾ നിയന്ത്രിക്കുന്നു — നിങ്ങളുടെ ഓർഗനൈസേഷനുമായി പൊരുത്തപ്പെടുത്താൻ അവ ക്രമീകരിക്കുക.',
            'statuses' => 'ഒരു ടിക്കറ്റിന് ഉണ്ടാകാവുന്ന വർക്ക്ഫ്ലോ നിലകൾ. <em>Closed</em> എന്ന് ഫ്ലാഗ് ചെയ്ത നിലകൾ അന്തിമമായി കണക്കാക്കും — റിപ്പോർട്ടുകൾ, വാച്ച്‌ടവർ കൗണ്ടറുകൾ, അസൈൻ ചെയ്യുമ്പോൾ ഓട്ടോ-സെറ്റ് ചെയ്യുന്ന ക്ലോസ്ഡ്-ഡേറ്റ്ടൈം എന്നിവ ഇത് ഉപയോഗിക്കുന്നു. കൃത്യമായി ഒരു നില പുതിയ ടിക്കറ്റുകൾക്കുള്ള സ്ഥിരസ്ഥിതിയാണ്.',
            'priorities' => 'ടിക്കറ്റുകളിൽ കാണിക്കുന്ന മുൻഗണനാ ബാൻഡുകൾ. കൃത്യമായി ഒരു മുൻഗണന പുതിയ ടിക്കറ്റുകൾക്കുള്ള സ്ഥിരസ്ഥിതിയാണ്.',
            'rota_locations' => 'ഒരു നിശ്ചിത ദിവസം ഓരോ അനലിസ്റ്റും എവിടെയാണ് ജോലി ചെയ്യുന്നത് — സ്റ്റാഫ് റോട്ട ഇത് ഉപയോഗിക്കുന്നു, ഓരോ എൻട്രിയിലും ഒരു നിറമുള്ള ബാഡ്ജായി കാണിക്കും. കൃത്യമായി ഒരു ലൊക്കേഷൻ പുതിയ റോട്ട എൻട്രികൾക്കുള്ള സ്ഥിരസ്ഥിതിയാണ്.',
            'email_templates' => 'ടിക്കറ്റ് ഇവന്റുകൾ ട്രിഗ്ഗർ ചെയ്യുന്ന ഓട്ടോമേറ്റഡ് ഇമെയിൽ മറുപടികൾ. ഓരോ ഇവന്റിനും ആദ്യത്തെ സജീവ ടെംപ്ലേറ്റ് മാത്രമേ ഉപയോഗിക്കൂ.',
        ],
        'messaging' => [
            'channels_heading' => 'മെസേജിംഗ് ചാനലുകൾ',
            'channels_intro' => 'ഉപഭോക്താക്കൾക്ക് WhatsApp വഴി ഒരു അനലിസ്റ്റുമായി ചാറ്റ് ചെയ്യാൻ അനുവദിക്കുക — ഇമെയിൽ പോലെ തന്നെ ഓരോ സന്ദേശവും ഒരു ടിക്കറ്റാകും. താഴെ ഒരു ചാനൽ ചേർക്കുക, എന്നിട്ട് ഇൻബൗണ്ട് സന്ദേശങ്ങൾ ഈ ഇൻസ്റ്റലേഷനിൽ എത്താൻ അതിന്റെ <strong>വെബ്ഹുക്ക് URL</strong> നിങ്ങളുടെ ദാതാവിൽ (Twilio അല്ലെങ്കിൽ Meta) പേസ്റ്റ് ചെയ്യുക.',
            'base_url_label' => '<strong>പൊതു ബേസ് URL</strong>',
            'base_url_placeholder' => 'https://your-domain.com  (അല്ലെങ്കിൽ ടെസ്റ്റ് ചെയ്യുമ്പോൾ നിങ്ങളുടെ ngrok വിലാസം)',
            'base_url_help' => 'ഈ ഇൻസ്റ്റലേഷനിൽ എത്താൻ ദാതാക്കൾ ഉപയോഗിക്കുന്ന വിലാസം. ഇത് സെറ്റ് ചെയ്താൽ താഴെയുള്ള വെബ്ഹുക്ക് URL-കൾ കോപ്പി-പേസ്റ്റ്-റെഡി ആകും. നിങ്ങൾ ബ്രൗസ് ചെയ്യുന്ന ഏത് വിലാസവും ഉപയോഗിക്കാൻ ശൂന്യമായി വിടുക. ലോക്കലായി ടെസ്റ്റ് ചെയ്യുകയാണോ? <code>ngrok http 80</code> റൺ ചെയ്ത് അത് പ്രിന്റ് ചെയ്യുന്ന <code>https://…ngrok-free.dev</code> വിലാസം പേസ്റ്റ് ചെയ്യുക.',
            'templates_heading' => 'സന്ദേശ ടെംപ്ലേറ്റുകൾ',
            'templates_intro' => '<strong>24 മണിക്കൂർ വിൻഡോ അടച്ചതിന് ശേഷം</strong> ഒരു അനലിസ്റ്റിന് മറുപടി നൽകാൻ മുൻകൂട്ടി അംഗീകരിച്ച ടെംപ്ലേറ്റുകൾ അനുവദിക്കുന്നു. ഉപഭോക്താവിന്റെ അവസാന സന്ദേശത്തിന് ശേഷം 24 മണിക്കൂറിനുള്ളിൽ മാത്രമേ WhatsApp സ്വതന്ത്ര ടെക്സ്റ്റ് അനുവദിക്കൂ; അതിനപ്പുറം, Meta/Twilio അംഗീകരിച്ച ഒരു ടെംപ്ലേറ്റ് മാത്രമേ അയക്കാൻ കഴിയൂ. നിങ്ങളുടെ ദാതാവിൽ ടെംപ്ലേറ്റ് സൃഷ്ടിച്ച് &amp; അംഗീകരിക്കുക, എന്നിട്ട് അതിന്റെ നിർവചനം ഇവിടെ ചേർക്കുക (<code>{{1}}</code>, <code>{{2}}</code> പ്ലേസ്‌ഹോൾഡറുകളോടെ) അനലിസ്റ്റുകൾക്ക് അത് തിരഞ്ഞെടുത്ത് പൂരിപ്പിക്കാൻ.',
        ],
