            'business_hours_help' => 'ഈ സമയത്തിന് പുറത്ത് വിജറ്റ് നിങ്ങളുടെ ഓഫ്‌ലൈൻ സന്ദേശം കാണിക്കും, എന്നിട്ടും അന്വേഷണം പിന്നീട് മറുപടി നൽകാനുള്ള ഒരു ടിക്കറ്റായി എടുക്കും. കലണ്ടറുകൾ SLA ക്രമീകരണങ്ങൾക്ക് കീഴിൽ മാനേജ് ചെയ്യുന്നു.',
