            'priority_change_reset' => 'SLA ക്ലോക്ക് പൂർണ്ണമായും റീസെറ്റ് ചെയ്യുക',
            'reopen_label' => 'അടച്ച ഒരു ടിക്കറ്റ് വീണ്ടും തുറക്കുമ്പോൾ',
            'reopen_reset' => 'SLA പുതുതായി തുടങ്ങുക',
