            'first_response_label' => 'ആദ്യ റെസ്പോൺസ് ആയി കണക്കാക്കുന്നത്',
            'first_response_outbound' => 'ഔട്ട്ബൗണ്ട് ഇമെയിൽ മാത്രം (Reply / Forward)',
