            'warning_threshold_help' => 'ടിക്കറ്റുകൾ അവയുടെ SLA-യുടെ ഈ % കടന്നാൽ ഇൻബോക്സിൽ ദൃശ്യപരമായി ഫ്ലാഗ് ചെയ്യും.',
            'notifications_label' => 'അറിയിപ്പുകൾ',
            'notify_assignee' => 'മുന്നറിയിപ്പ് ത്രെഷോൾഡിൽ അസൈനിക്ക് ഇമെയിൽ അയക്കുക',
            'notify_lead' => 'ബ്രീച്ചിൽ ടീം ലീഡിന് ഇമെയിൽ അയക്കുക',
            'save_global' => 'ആഗോള ക്രമീകരണങ്ങൾ സേവ് ചെയ്യുക',
            'targets_heading' => 'ഓരോ മുൻഗണനയ്ക്കുമുള്ള SLA ടാർഗെറ്റുകൾ',
            'targets_intro' => 'ഓരോ ടിക്കറ്റ് മുൻഗണനയ്ക്കുമുള്ള റെസ്പോൺസ്, റെസലൂഷൻ സമയങ്ങൾ. സമയങ്ങൾ മിനിറ്റിലാണ് (60 = 1 മണിക്കൂർ, 240 = 4 മണിക്കൂർ, 1440 = 1 ദിവസം). ക്ലോക്ക് ഏത് ബിസിനസ് സമയത്തിനെതിരെ പ്രവർത്തിക്കുമെന്ന് കലണ്ടർ തീരുമാനിക്കുന്നു. ആ ടാർഗെറ്റ് ഒഴിവാക്കാൻ ശൂന്യമായി വിടുക.',
            'col_priority' => 'മുൻഗണന',
            'col_response_mins' => 'റെസ്പോൺസ് (മിനിറ്റ്)',
            'col_resolution_mins' => 'റെസലൂഷൻ (മിനിറ്റ്)',
            'col_calendar' => 'കലണ്ടർ',
            'col_save' => 'സേവ്',
            'calendars_heading' => 'ബിസിനസ് കലണ്ടറുകൾ',
            'calendars_intro' => 'പ്രവൃത്തി സമയങ്ങൾ, ടൈംസോണുകൾ, അവധി ലിസ്റ്റുകൾ നിർവചിക്കുക. കലണ്ടറുകളെ SLA ടാർഗെറ്റുകൾ (മുകളിൽ), വ്യക്തിഗത മുൻഗണനകൾ എന്നിവ റെഫറൻസ് ചെയ്യുന്നു. പുതിയ മുൻഗണനകൾക്കുള്ള സ്ഥിരസ്ഥിതി ഒരു കലണ്ടറാണ്.',
            'col_name' => 'പേര്',
            'col_timezone' => 'ടൈംസോൺ',
            'col_hours' => 'മണിക്കൂറുകൾ',
            'col_holidays' => 'അവധികൾ',
            'col_default' => 'സ്ഥിരസ്ഥിതി',
            'col_actions' => 'പ്രവർത്തനങ്ങൾ',
            'notifs_heading' => 'ബ്രീച്ച് അറിയിപ്പുകൾ',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">അറിയിപ്പ് നിയമങ്ങൾ എങ്ങനെ പ്രവർത്തിക്കുന്നു</strong>ഓരോ നിയമത്തിനും നാല് ഭാഗങ്ങളുണ്ട്: ഒരു <strong>സ്കോപ്പ്</strong>, ഒരു <strong>ട്രിഗ്ഗർ</strong>, ഒരു <strong>ടാർഗെറ്റ്</strong>, <strong>സ്വീകർത്താക്കളുടെ</strong> ഒരു ലിസ്റ്റ്.<br><br><strong>സ്കോപ്പ്</strong> ഒന്നുകിൽ <em>Default</em> ആകാം (നിയമം എല്ലാ വകുപ്പിലെയും ടിക്കറ്റുകൾക്ക് ബാധകമാണ്) അല്ലെങ്കിൽ ഒരു <em>നിർദ്ദിഷ്ട വകുപ്പ്</em> (നിയമം ആ വകുപ്പിലെ ടിക്കറ്റുകൾക്ക് മാത്രം ബാധകമാണ്).<br>ഒരു ടിക്കറ്റ് വിലയിരുത്തുമ്പോൾ, സിസ്റ്റം ആദ്യം അതിന്റെ വകുപ്പുമായി പൊരുത്തപ്പെടുന്ന ഒരു നിയമം തിരയുന്നു &mdash; ഒന്ന് ഉണ്ടെങ്കിൽ, ആ നിയമം ജയിക്കുകയും സ്ഥിരസ്ഥിതി അവഗണിക്കുകയും ചെയ്യും. വകുപ്പ്-നിർദ്ദിഷ്ട നിയമമില്ലെങ്കിൽ, സ്ഥിരസ്ഥിതി നിയമം ഉപയോഗിക്കും. ഇങ്ങനെ എല്ലാ വകുപ്പിനെയും ഉൾക്കൊള്ളുന്ന യുക്തിസഹമായ സ്ഥിരസ്ഥിതികൾ സെറ്റ് ചെയ്യാം, പിന്നെ ഒരു ടീമിന് വ്യത്യസ്ത എസ്കലേഷൻ ആവശ്യങ്ങളുള്ളിടത്ത് ഒഴിവാക്കലുകൾ ഉണ്ടാക്കാം.<br><br><strong>ട്രിഗ്ഗർ</strong> ഒന്നുകിൽ <em>Warning</em> ആണ് (ടിക്കറ്റ് മുന്നറിയിപ്പ് ത്രെഷോൾഡ് കടന്നിരിക്കുന്നു &mdash; സാധ്യമായ ബ്രീച്ച് അടുക്കുന്നു) അല്ലെങ്കിൽ <em>Breach</em> (ടിക്കറ്റ് ഇപ്പോൾ അതിന്റെ SLA ടാർഗെറ്റ് കടന്നിരിക്കുന്നു &mdash; യഥാർത്ഥ ബ്രീച്ച്). ഓരോന്നും അതിന്റേതായ നിയമമാണ്, അതിനാൽ മുന്നറിയിപ്പുകൾക്കും ബ്രീച്ചുകൾക്കും വ്യത്യസ്ത ആളുകളെ അറിയിക്കാം.<br><br><strong>ടാർഗെറ്റ്</strong> ഏത് SLA ക്ലോക്ക് നിരീക്ഷിക്കണം എന്നാണ് &mdash; <em>Response</em>, <em>Resolution</em>, അല്ലെങ്കിൽ <em>Both</em>.<br><br><strong>സ്വീകർത്താക്കൾ</strong> ഇവയുടെ ഏത് സംയോജനവും ആകാം: ടിക്കറ്റിന്റെ നിലവിലെ അസൈനി, ടിക്കറ്റിന്റെ വകുപ്പ് ടീമുകളിലെ ഓരോ അനലിസ്റ്റും, പേരുള്ള ഒരു അനലിസ്റ്റ്, കൂടാതെ/അല്ലെങ്കിൽ ഫ്രീ-ഫോം ഇമെയിൽ അഡ്രസുകളുടെ ഒരു ലിസ്റ്റ് (പങ്കിട്ട ഇൻബോക്സുകൾക്കോ Slack/Teams ഇമെയിൽ ബ്രിഡ്ജുകൾക്കോ ഉപകാരപ്രദം).<br><br><strong style="color:var(--warning-text, #92400e);">നിയമങ്ങളില്ല = ഇമെയിലുകളില്ല.</strong> ഒരു ടിക്കറ്റ് ബ്രീച്ച് ആയാൽ പോലും, നിങ്ങൾ കുറഞ്ഞത് ഒരു നിയമമെങ്കിലും ചേർക്കുന്നത് വരെ ഒന്നും പ്രവർത്തിക്കില്ല (എല്ലാത്തിനും കവറേജ് ലഭിക്കാൻ ഒരു Default-സ്കോപ്പ് Warning + Breach ജോഡിയിൽ തുടങ്ങുക).',
            'notifs_dedup' => 'ഓരോ ടിക്കറ്റും (ടാർഗെറ്റ്, ട്രിഗ്ഗർ) ഓരോന്നിനും കൂടിയാൽ ഒരു ഇമെയിൽ മാത്രമേ അയക്കൂ &mdash; ഇരട്ടിപ്പ് ഒഴിവാക്കാൻ ഇതിനകം അയച്ചത് എന്താണെന്ന് ക്രോൺ വർക്കർ ട്രാക്ക് ചെയ്യുന്നു.',
            'col_scope' => 'സ്കോപ്പ്',
            'col_trigger' => 'ട്രിഗ്ഗർ',
            'col_target' => 'ടാർഗെറ്റ്',
            'col_recipients' => 'സ്വീകർത്താക്കൾ',
            'col_active' => 'സജീവം',
            'notifs_cron_note' => 'ഈ ഇമെയിലുകൾ അയക്കുന്ന ക്രോൺ വർക്കർ <code>cron/sla_breach_check.php</code>-ലാണ്. Windows Task Scheduler + Linux cron സെറ്റപ്പിന് <code>docs/sla-cron-setup.md</code> കാണുക.',
