            'snooze_hour_help' => '"നാളെ" അല്ലെങ്കിൽ "അടുത്ത ആഴ്ച" വരെ സ്നൂസ് ചെയ്ത ഒരു ടിക്കറ്റ് തിരികെ വരുന്ന സമയം. ഓരോ അനലിസ്റ്റിന്റെയും സ്വന്തം ടൈംസോണിൽ വായിക്കുന്നു, അതിനാൽ വിവിധ സോണുകളിൽ വ്യാപിച്ച ഒരു ഡെസ്കിന് അതിന്റേതായ പ്രഭാതം ലഭിക്കും.',
            'collapse_heading' => 'നീണ്ട സന്ദേശങ്ങൾ',
            'collapse_desc' => 'നീണ്ട ഇമെയിലുകൾ, നിങ്ങൾ ടിക്കറ്റ് തുറന്ന് വായിക്കാൻ ഉദ്ദേശിച്ച കാര്യത്തെ മൂടിക്കളയും. താഴെയുള്ള പരിധിയിലും ഉയരമുള്ള സന്ദേശങ്ങൾ ഒരു Show more ലിങ്കോടെ ചുരുക്കും. ഒന്നും ഡിലീറ്റ് ചെയ്യില്ല — മുഴുവൻ സന്ദേശവും എപ്പോഴും ഒരു ടാപ്പ് അകലെ.',
            'collapse_enabled_label' => 'നീണ്ട സന്ദേശങ്ങൾ ചുരുക്കുക',
            'collapse_lines_label' => 'ഇത്ര ഉയരമുള്ള സന്ദേശങ്ങൾ ചുരുക്കുക',
            'collapse_lines_help' => 'വരികൾ. പരിധി അല്പം കടന്ന ഒരു സന്ദേശം അതേപടി വിടും, അതിനാൽ രണ്ട് വാക്കിന് വേണ്ടി ലിങ്ക് ഒരിക്കലും പ്രത്യക്ഷപ്പെടില്ല.',
            'collapse_newest_label' => 'ഏറ്റവും പുതിയ സന്ദേശം എപ്പോഴും മുഴുവനായി കാണിക്കുക',
            'collapse_newest_help' => 'നിങ്ങൾ വായിക്കാൻ വന്ന സന്ദേശം ഒരിക്കലും ചുരുക്കില്ല.',
            'collapse_quoted_label' => 'ഉദ്ധരിച്ച ചരിത്രം ചുരുക്കുക',
            'collapse_quoted_help' => 'അതിനടിയിൽ ഒരു നീണ്ട ഉദ്ധരണ ചെയിനുള്ള ഒരു ചെറിയ മറുപടി ഏത് വരി എണ്ണത്തിലും ചെറുതാണ്, എന്നിട്ടും വായിക്കാൻ കഴിയാത്തതാണ്, അതിനാൽ ഉദ്ധരിച്ച ചരിത്രം വേറിട്ട് ചുരുക്കുന്നു.',
            'collapse_remember_label' => 'ഞാൻ തുറന്നത് ഓർമ്മിക്കുക',
            'collapse_remember_help' => 'നിങ്ങൾ വികസിപ്പിക്കുന്ന സന്ദേശങ്ങൾ ഈ ഡിവൈസിൽ വികസിച്ചു തന്നെ തുടരും, അതിനാൽ ഒരു ത്രെഡിലൂടെ ജോലി ചെയ്യുന്നത് ഓരോ പുതുക്കലിലും സ്വയം പഴയപടിയാകില്ല.',
            'group_older_label' => 'പഴയ സന്ദേശങ്ങൾ ഒളിപ്പിക്കുക',
            'group_older_help' => 'താഴെയുള്ള നമ്പറിനപ്പുറം, പഴയ സന്ദേശങ്ങൾ നിങ്ങൾക്ക് തുറക്കാവുന്ന ഒരു വരിയിലേക്ക് ഒതുങ്ങും. ഒരു നീണ്ട ടിക്കറ്റ് ഒരു നീണ്ട സന്ദേശത്തിൽ നിന്ന് വ്യത്യസ്തമായ ഒരു പ്രശ്നമാണ്.',
            'group_show_label' => 'ഇത്രയും സമീപകാല സന്ദേശങ്ങൾ തുറന്ന് സൂക്ഷിക്കുക',
            'flag_duplicates_label' => 'മുമ്പ് എത്തിയ സന്ദേശങ്ങൾ ചൂണ്ടിക്കാണിക്കുക',
            'flag_duplicates_help' => 'ഒരു വീണ്ടും അയക്കൽ, ഒരു ഡ്യൂപ്ലിക്കേറ്റ് ഡെലിവറി, അല്ലെങ്കിൽ ഒറിജിനലിനെ തിരികെ കൊണ്ടുവരുന്ന ഒരു ബൗൺസ് - അത് ഏത് സന്ദേശവുമായി പൊരുത്തപ്പെടുന്നു എന്ന് പറയുന്ന ഒരു കുറിപ്പോടെ ഒളിപ്പിക്കും. ഒന്നും ഡിലീറ്റ് ചെയ്യില്ല.',
            'ai_heading' => 'AI വായനാ സഹായികൾ',
            'ai_desc' => 'ഓപ്ഷണൽ, നിങ്ങൾ ഓണാക്കുന്നതുവരെ ഓഫ്: ഈ പേജിലെ മറ്റെല്ലാത്തിൽ നിന്നും വ്യത്യസ്തമായി, ഇവ നിങ്ങളുടെ സ്വന്തം AI പ്രൊവൈഡർ ഉപയോഗിക്കുകയും ഓരോ ഉപയോഗത്തിനും പണം ചെലവാകുകയും ചെയ്യും. പ്രൊവൈഡർ, മോഡൽ, API കീ എന്നിവ Reply cleanup ടാബിൽ ഒരിക്കൽ ക്രമീകരിക്കുന്നു. AI എഴുതുന്ന ഒന്നും ടിക്കറ്റിനെ ഒരിക്കലും മാറ്റിസ്ഥാപിക്കില്ല — സംഭാഷണം അത് ഉള്ളിടത്ത് തന്നെ, മുഴുവനായി തുടരും.',
            'ai_summary_label' => 'ഓരോ ടിക്കറ്റിന്റെയും മുകളിൽ ഒരു ചെറിയ AI സംഗ്രഹം സൂക്ഷിക്കുക',
            'ai_summary_help' => 'ടിക്കറ്റ് എവിടെ നിൽക്കുന്നു എന്ന് പറയുന്ന കുറച്ച് വരികൾ, ആവശ്യപ്പെടുമ്പോൾ എഴുതി അപ്-റ്റു-ഡേറ്റായി സൂക്ഷിക്കുന്നു. ഇത് എപ്പോൾ എഴുതിയെന്നും, എത്രത്തോളം വായിച്ചു എന്നും, അതിനുശേഷം സംഭാഷണം എത്ര മുന്നോട്ട് പോയെന്നും എപ്പോഴും കാണിക്കും. എല്ലാ പതിപ്പുകളും സൂക്ഷിക്കുന്നു, അതിനാൽ മോശമായ ഒരു സംഗ്രഹം ഒരിക്കലും മികച്ച ഒന്നിനെ നശിപ്പിക്കില്ല.',
            'ai_auto_label' => 'ഇത്രയും പുതിയ സന്ദേശങ്ങൾക്ക് ശേഷം സ്വയമേവ പുതുക്കുക',
            'ai_auto_help' => '0 എന്നാൽ ഒരിക്കലും വേണ്ട എന്നാണ് — അപ്പോൾ Refresh ബട്ടൺ മാത്രമേ വഴിയുള്ളൂ, ആരും ചോദിക്കാതെ ഒരിക്കലും ചാർജ് ചെയ്യില്ല. ഒരു അനലിസ്റ്റ് ടിക്കറ്റ് തുറക്കുമ്പോൾ മാത്രമേ ഒരു പുതുക്കൽ സംഭവിക്കൂ, അതിനാൽ ആരും വായിക്കാത്ത തിരക്കുള്ള ഒരു ക്യൂവിന് ഒന്നും ചെലവാകില്ല.',
            'ai_max_label' => 'വായിക്കേണ്ട സന്ദേശങ്ങൾ',
            'ai_max_help' => 'ഒരു സംഗ്രഹം എത്ര പിന്നിലേക്ക് വായിക്കുന്നു. ഒരു നീണ്ട ടിക്കറ്റ് അതിന്റെ ഏറ്റവും പുതിയ അറ്റത്ത് നിന്ന് വായിക്കുന്നു, സംഗ്രഹം അത് കണ്ടിട്ടില്ലാത്ത ഒരു തുടക്കം വിവരിക്കുന്നതിന് പകരം അത് പറയും.',
            'ai_notes_label' => 'ഇന്റേണൽ കുറിപ്പുകൾ വായിക്കാൻ അനുവദിക്കുക',
            'ai_notes_help' => 'ഇന്റേണൽ കുറിപ്പുകൾ പലപ്പോഴും യഥാർത്ഥത്തിൽ ശ്രമിച്ചത് എന്താണെന്ന് സൂക്ഷിക്കുന്നു. ഏത് വിധത്തിലും അവ സ്റ്റാഫിന് മാത്രമുള്ളതാണ് — സംഗ്രഹം ഒരിക്കലും അഭ്യർത്ഥിച്ചയാൾക്ക് കാണിക്കില്ല — പക്ഷേ നിങ്ങളുടെ ഡെസ്കിലെ കുറിപ്പുകൾ അതിനുവെളിയിൽ പോകാൻ പാടില്ലാത്ത കാര്യങ്ങൾ സൂക്ഷിക്കുന്നെങ്കിൽ ഇത് ഓഫ് ചെയ്യുക.',
            'ai_read_label' => 'ഒരു ടിക്കറ്റിൽ "Read it for me" വാഗ്ദാനം ചെയ്യുക',
            'ai_read_help' => 'മുഴുവൻ ടിക്കറ്റും വായിച്ച് അതിനെക്കുറിച്ച് നിങ്ങൾക്ക് ബ്രീഫ് ചെയ്യുന്ന ഒരു ബട്ടൺ: എന്ത് സംഭവിച്ചു, എന്താണ് പരിഹരിക്കാത്തത്, അടുത്തതായി എന്ത് ചെയ്യും. ചോദിക്കുമ്പോൾ മാത്രം ഒരു തവണ വായിക്കുന്നു, എവിടെയും സൂക്ഷിക്കില്ല.',
            'reopen_help' => 'ഒരു അഭ്യർത്ഥിച്ചയാൾ എവിടെ തിരികെ വന്നാലും ബാധകമാണ് — സെൽഫ്-സർവീസ് പോർട്ടൽ, നിങ്ങളുടെ അറിയിപ്പ് ഇമെയിലിനുള്ള മറുപടി, WhatsApp അല്ലെങ്കിൽ വെബ് ചാറ്റ്. ടിക്കറ്റ് നിങ്ങളുടെ ആദ്യത്തെ ഓപ്പൺ നിലയിലേക്ക് തിരികെ പോകും. അടച്ചതായി അടയാളപ്പെടുത്തിയ ഒരു നിലയിലുള്ള ടിക്കറ്റുകളെ മാത്രമേ ഇത് ബാധിക്കൂ (ഏതൊക്കെയാണ് എന്ന് നിലകൾക്ക് കീഴിൽ സെറ്റ് ചെയ്യുക).',
        ],
        'privacy' => [
            'third_party_label' => 'അഭ്യർത്ഥിച്ചയാൾ അല്ലാത്ത ആർക്കെങ്കിലും അയച്ച സന്ദേശങ്ങൾ',
            'opt_hide' => 'അഭ്യർത്ഥിച്ചയാളിൽ നിന്ന് അവ മറയ്ക്കുക',
            'opt_hide_help' => 'സന്ദേശവും അതിന്റെ അറ്റാച്ച്മെന്റുകളും അഭ്യർത്ഥിച്ചയാളുടെ പോർട്ടലിൽ ഒട്ടും ദൃശ്യമാകില്ല. ശുപാർശ ചെയ്യുന്നത്: ഒരു ടിക്കറ്റ് ഒരു സപ്ലയറിലേക്ക് ഫോർവേഡ് ചെയ്യുന്നത് സ്വകാര്യമാണ് എന്ന് മിക്ക ആളുകളും കരുതുന്നു.',
            'opt_no_attachments' => 'സന്ദേശം കാണിക്കുക, പക്ഷേ അതിന്റെ അറ്റാച്ച്മെന്റുകൾ അല്ല',
            'opt_no_attachments_help' => 'നിങ്ങൾ മറ്റാരെയെങ്കിലും ബന്ധപ്പെട്ടു എന്നും എന്താണ് എഴുതിയത് എന്നും അഭ്യർത്ഥിച്ചയാൾക്ക് കാണാം, പക്ഷേ ചേർത്ത ഫയലുകൾ ഒന്നും ഡൗൺലോഡ് ചെയ്യാൻ കഴിയില്ല.',
            'opt_show' => 'എല്ലാം കാണിക്കുക',
            'opt_show_help' => 'അഭ്യർത്ഥിച്ചയാൾ നിങ്ങളുടെ അനലിസ്റ്റുകൾ കാണുന്നത് പോലെ തന്നെ മുഴുവൻ ടിക്കറ്റും കാണും, ഫോർവേഡുകളും മൂന്നാം-കക്ഷി മറുപടികളും ഉൾപ്പെടെ. ഈ ക്രമീകരണം നിലവിൽ വരുന്നതിന് മുമ്പുള്ള പെരുമാറ്റം ഇതായിരുന്നു.',
            'always_visible_note' => '<strong>അഭ്യർത്ഥിച്ചയാൾക്ക് എപ്പോഴും ദൃശ്യമാകുന്നത്:</strong> അവരുടെ സ്വന്തം സന്ദേശങ്ങളും, അവരെ അഭിസംബോധന ചെയ്യുന്ന ഏത് മറുപടിയും. <strong>ഒരിക്കലും ദൃശ്യമാകാത്തത്:</strong> ഇന്റേണൽ കുറിപ്പുകൾ — ഈ ക്രമീകരണം എന്തായാലും അവ പോർട്ടലിൽ നിന്ന് മറഞ്ഞിരിക്കും. WhatsApp, വെബ് ചാറ്റ് സന്ദേശങ്ങൾ എപ്പോഴും കാണിക്കും, കാരണം ആ സംഭാഷണങ്ങൾ നിർവചനം അനുസരിച്ച് അഭ്യർത്ഥിച്ചയാൾക്കും നിങ്ങളുടെ ഡെസ്കിനും ഇടയിലാണ്.',
            'timezone' => 'ടൈംസോൺ',
            'timezone_help' => 'സിസ്റ്റത്തിലുടനീളം തീയതികളും സമയങ്ങളും കാണിക്കാൻ ഉപയോഗിക്കുന്നു.',
        ],
        'reply_cleanup' => [
            'intro1' => 'ടിക്കറ്റ് കമ്പോസ് മോഡലിൽ ഒരു അനലിസ്റ്റ് ഒരു ലളിതമായ മറുപടി ടൈപ്പ് ചെയ്യുമ്പോൾ, <strong>✨ Cleanup</strong> ബട്ടൺ അത് ശരിയായി ഫോർമാറ്റ് ചെയ്ത ഒരു ഇമെയിലായി മാറ്റിയെഴുതും — "Dear [name]," എന്ന അഭിവാദനം ചേർത്ത്, വ്യാകരണം തിരുത്തി, താഴെ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ടോൺ പ്രയോഗിച്ച്, "Kind regards," എന്ന് ഒപ്പിട്ട്. ഇത് സാങ്കേതിക വിശദാംശങ്ങൾ കെട്ടിച്ചമയ്ക്കുകയോ ഉള്ളടക്കം നീട്ടുകയോ <strong>ചെയ്യില്ല</strong>.',
            'intro2' => 'ഈ ഫീച്ചർ അതിന്റെ സ്വന്തം Anthropic API കീ ഉപയോഗിക്കുന്നു (RFP AI, Knowledge AI എന്നിവയിൽ നിന്ന് വേറിട്ട്), അതിനാൽ Anthropic ബില്ലിംഗ് ഡാഷ്ബോർഡിൽ ഇതിന്റെ ഉപയോഗം ഒരു പ്രത്യേക വരിയായി കാണിക്കും.',
            'tone' => 'ടോൺ',
            'tone_friendly' => 'സൗഹൃദപരം (സ്ഥിരസ്ഥിതി)',
            'tone_formal' => 'ഫോർമൽ',
            'tone_brief' => 'ചുരുക്കം',
            'tone_help' => 'ഇവിടെ മാറ്റുന്നില്ലെങ്കിൽ ഓരോ ക്ലീൻഅപ്പിനും ഇത് പ്രയോഗിക്കും.',
            'custom_label' => 'കസ്റ്റം നിർദ്ദേശങ്ങൾ <span style="color: #999; font-weight: normal;">(ഓപ്ഷണൽ)</span>',
            'custom_placeholder' => 'ഉദാ. എപ്പോഴും \'Many thanks,\' എന്ന് ഒപ്പിടുക&#10;കമ്പനിയെ \'BillCorp\' എന്ന് വിളിക്കുക&#10;എല്ലായിടത്തും British English സ്പെല്ലിംഗുകൾ ഉപയോഗിക്കുക',
            'custom_help' => 'വലതുവശത്ത് കാണിക്കുന്ന സിസ്റ്റം പ്രോംപ്റ്റിന്റെ അവസാനം ചേർക്കും. ഓർഗനൈസേഷൻ-നിർദ്ദിഷ്ട ട്വീക്കുകൾക്ക് (ഒപ്പ് വകഭേദങ്ങൾ, കമ്പനിയുടെ പേര്, ഭാഷാ മുൻഗണനകൾ) ഇത് ഉപയോഗിക്കുക. കർശനമായ സുരക്ഷാ നിയമങ്ങളും ഔട്ട്പുട്ട് ഫോർമാറ്റും അപ്പോഴും മുൻഗണന നേടും.',
            'prompt_summary' => 'സിസ്റ്റം പ്രോംപ്റ്റ് കാണുക (റീഡ്-ഒൺലി)',
            'prompt_panel_intro' => 'ഓരോ ക്ലീൻഅപ്പിലും Claude-ന് അയക്കുന്ന മുഴുവൻ സിസ്റ്റം പ്രോംപ്റ്റ് ഇതാണ്. അഭിവാദന നാമം ഓരോ ടിക്കറ്റിനും വ്യത്യാസപ്പെടും; ടോൺ ഇടതുവശത്തെ നിങ്ങളുടെ തിരഞ്ഞെടുപ്പ് പ്രതിഫലിപ്പിക്കും. നിങ്ങളുടെ കസ്റ്റം നിർദ്ദേശങ്ങൾ (ഉണ്ടെങ്കിൽ) റൺടൈമിൽ അവസാനം ചേർക്കും — അവ ഇവിടെ കാണിക്കില്ല, ഇടതുവശത്തെ ടെക്സ്റ്റ്എരിയയിൽ എഡിറ്റ് ചെയ്യുക.',
        ],
        'csat_tab' => [
            'intro1' => 'ഒരു ടിക്കറ്റ് അടയ്ക്കുമ്പോൾ, അനുഭവം 1&ndash;5 റേറ്റ് ചെയ്യാൻ ആവശ്യപ്പെടുന്ന ഒരു ചെറിയ സർവേ ഇമെയിൽ അഭ്യർത്ഥിച്ചയാൾക്ക് അയക്കുക. പ്രതികരണങ്ങൾ ടിക്കറ്റ് അടച്ച അനലിസ്റ്റിനെതിരെ രേഖപ്പെടുത്തുന്നു, അതിനാൽ ഓരോ അനലിസ്റ്റിന്റെയും CSAT ട്രെൻഡുകൾ എടുക്കാം, ഡാഷ്ബോർഡിൽ ഒരു വിജറ്റായി ജീവിക്കും.',
            'intro2' => 'സർവേ ഇമെയിൽ <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">ഇമെയിൽ ടെംപ്ലേറ്റുകൾ</a>-ന് കീഴിൽ ക്രമീകരിക്കുന്നു &mdash; <strong>CSAT survey</strong> ഇവന്റോടെ ഒരു ടെംപ്ലേറ്റ് സൃഷ്ടിക്കുക, ഒറ്റത്തവണ റേറ്റിംഗ് URL ചേർക്കാൻ ബോഡിയിൽ <code>[csat_link]</code> ഉൾപ്പെടുത്തുക.',
