            'mode_manual' => 'മാനുവൽ മാത്രം',
            'mode_manual_help' => 'ചോദിക്കണമെന്ന് തോന്നുമ്പോൾ അനലിസ്റ്റുകൾ ടിക്കറ്റ് ടൂൾബാറിൽ നിന്ന് <em>Feedback</em> ക്ലിക്ക് ചെയ്യുന്നു.',
            'delay_help' => 'അടച്ചതിനുശേഷം അയക്കുന്നതിന് മുമ്പ് ഇത്രയും മിനിറ്റ് കാത്തിരിക്കുക. <code>0</code> = ഉടനടി. പരിഹാരം ശരിക്കും നിലനിന്നോ എന്ന് റേറ്റ് ചെയ്യാൻ ആവശ്യപ്പെടുന്നതിന് മുമ്പ് ഉപയോക്താവിനെ പരിശോധിക്കാൻ അനുവദിക്കണമെങ്കിൽ ഉപകാരപ്രദം.',
            'one_per_ticket' => 'ഒരു ടിക്കറ്റിന് ഒരു സർവേ',
            'one_per_ticket_help' => 'ഓണാണെങ്കിൽ, വീണ്ടും തുറന്ന് പിന്നെ അടച്ച ഒരു ടിക്കറ്റിന് ഒരു അനലിസ്റ്റ് മാനുവലായി ട്രിഗർ ചെയ്യുമ്പോൾ മാത്രമേ മറ്റൊരു സർവേ ലഭിക്കൂ &mdash; അസ്ഥിരമായ ഒരു ടിക്കറ്റിനെ സർവേ-സ്പാം ചെയ്യുന്നത് നിർത്തുന്നു.',
            'scale_stars' => 'സ്റ്റാറുകൾ',
            'scale_emojis' => 'ഇമോജികൾ',
            'scale_help' => 'രണ്ട് ഓപ്ഷനുകളും ഒരേ 1&ndash;5 നമ്പർ സ്റ്റോർ ചെയ്യുന്നു, അതിനാൽ ഏത് വിധത്തിലായാലും ഡാഷ്ബോർഡുകളും ശരാശരികളും ഒരുപോലെ പ്രവർത്തിക്കും &mdash; ഇത് സർവേ പേജ് തന്നെ എങ്ങനെ കാണപ്പെടും എന്ന് മാത്രമേ മാറ്റുന്നുള്ളൂ.',
