        'hero_sub' => 'ഒറ്റ ഫോൾഡർ അടിസ്ഥാനമാക്കിയ ഇൻബോക്സിൽ നിന്ന് IT സപ്പോർട്ട് അഭ്യർത്ഥനകൾ ലോഗ് ചെയ്യുക, ട്രാക്ക് ചെയ്യുക, പരിഹരിക്കുക &mdash; സർവീസ് ഡെസ്ക് ടീമുകൾക്കായി നിർമ്മിച്ചത്.',
