        'overview' => [
            'heading' => 'അവലോകനം',
            'intro' => 'നിങ്ങളുടെ IT സർവീസ് ഡെസ്കിന്റെ കാതൽ ടിക്കറ്റുകൾ മൊഡ്യൂളാണ്. സപ്പോർട്ട് അഭ്യർത്ഥനകൾ, സംഭവങ്ങൾ, സർവീസ് ടാസ്കുകൾ എന്നിവ കൈകാര്യം ചെയ്യാൻ പരിചിതമായ ഒരു ഇമെയിൽ-ക്ലയന്റ് ശൈലിയിലുള്ള ഇന്റർഫേസ് ഇത് നൽകുന്നു. എൻഡ് യൂസർമാരിൽ നിന്ന് ഇമെയിൽ വഴിയോ നേരിട്ട് സൃഷ്ടിച്ചോ ടിക്കറ്റുകൾ വന്നുചേരുന്നു, അനലിസ്റ്റുകൾ ഫോൾഡറുകൾ, മുൻഗണനകൾ, SLA ടൈമറുകൾ എന്നിവ ഉപയോഗിച്ച് അവ കൈകാര്യം ചെയ്യുന്നു &mdash; പ്രതികരണശേഷിയുള്ള IT സപ്പോർട്ട് നൽകാൻ വേണ്ടതെല്ലാം.',
            'card_inbox_title' => 'ഇൻബോക്സ്',
            'card_inbox_body' => 'ഒരു ഇമെയിൽ ക്ലയന്റിനെ മാതൃകയാക്കിയ ഫോൾഡർ അടിസ്ഥാനമാക്കിയ ഇൻബോക്സ്. എന്റെ ടിക്കറ്റുകൾ, നിയോഗിക്കാത്തവ, എല്ലാ തുറന്നവയും, അടച്ചവ എന്നീ ഫോൾഡറുകൾ ബ്രൗസ് ചെയ്യുക. പൂർണ്ണ വിശദാംശങ്ങൾ, ചരിത്രം, പ്രവർത്തനങ്ങൾ എന്നിവയുള്ള ഒരു റീഡിംഗ് പെയ്ൻ തുറക്കാൻ ഏതെങ്കിലും ടിക്കറ്റിൽ ക്ലിക്ക് ചെയ്യുക.',
            'card_dashboard_title' => 'ഡാഷ്‌ബോർഡ്',
            'card_dashboard_body' => 'ഇഷ്ടാനുസൃതമാക്കാവുന്ന Chart.js വിജറ്റുകൾ ഉപയോഗിച്ച് വ്യക്തിഗതമാക്കിയ ഡാഷ്‌ബോർഡ് നിർമ്മിക്കുക. ബാർ, പൈ, ഡോനട്ട്, ലൈൻ ചാർട്ടുകൾ ഉപയോഗിച്ച് ടിക്കറ്റ് വോള്യങ്ങൾ, പ്രതികരണ സമയങ്ങൾ, വിഭാഗം തിരിച്ചുള്ള വിശകലനം, അനലിസ്റ്റ് വർക്ക്‌ലോഡുകൾ എന്നിവ വിഷ്വലൈസ് ചെയ്യുക.',
            'card_calendar_title' => 'കലണ്ടർ',
            'card_calendar_body' => 'സൃഷ്ടിച്ച, അവസാന തീയതി, അല്ലെങ്കിൽ പരിഹരിച്ച തീയതികളെ അടിസ്ഥാനമാക്കി ടിക്കറ്റുകൾ ഒരു കലണ്ടർ ഗ്രിഡിൽ കാണുക. കാലാവധി കഴിഞ്ഞ ഇനങ്ങൾ പെട്ടെന്ന് കണ്ടെത്തുകയും ടിക്കറ്റ് സ്ഥിതി ഒറ്റനോട്ടത്തിൽ കണ്ട് നിങ്ങളുടെ ആഴ്ച ആസൂത്രണം ചെയ്യുകയും ചെയ്യുക.',
            'card_rota_title' => 'റോട്ട',
            'card_rota_body' => 'അനലിസ്റ്റ് ഷിഫ്റ്റുകളും ഓൺ-കോൾ റോട്ടകളും ഷെഡ്യൂൾ ചെയ്യുക. ഏത് സമയത്തും ആരാണ് ലഭ്യമെന്ന് കാണുക, വാരാന്ത്യങ്ങൾക്കും അവധി ദിവസങ്ങൾക്കുമുള്ള കവറേജ് ആസൂത്രണം ചെയ്യുക, ഒരു ടിക്കറ്റും ശ്രദ്ധിക്കപ്പെടാതെ പോകുന്നില്ലെന്ന് ഉറപ്പാക്കുക.',
        ],
        'inbox' => [
            'heading' => 'ഇൻബോക്സ്',
            'intro' => 'ഇൻബോക്സ് അനലിസ്റ്റുകൾക്കുള്ള പ്രധാന വർക്ക്സ്പേസ് ആണ്. ഇത് മൂന്ന്-പെയ്ൻ ലേഔട്ട് ഉപയോഗിക്കുന്നു &mdash; ഇടത് വശത്ത് ഫോൾഡറുകൾ, മധ്യത്തിൽ ടിക്കറ്റ് ലിസ്റ്റ്, വലത് വശത്ത് ഒരു റീഡിംഗ് പെയ്ൻ &mdash; അതിനാൽ പേജ് വിട്ടുപോകാതെ തന്നെ ട്രയാജ് ചെയ്യാനും മറുപടി നൽകാനും കഴിയും.',
            'p_folders' => 'ഫോൾഡർ പാനൽ ടിക്കറ്റുകളെ യുക്തിസഹമായ ഗ്രൂപ്പുകളായി ക്രമീകരിക്കുന്നു. പുതിയ ജോലി ഉടനടി കണ്ടെത്താൻ കഴിയുന്ന വിധം ഓരോ ഫോൾഡറും ഒരു വായിക്കാത്ത എണ്ണം കാണിക്കുന്നു:',
            'field_my' => '<strong>എന്റെ ടിക്കറ്റുകൾ</strong> &mdash; നിങ്ങൾക്ക് നൽകിയ ടിക്കറ്റുകൾ. ഇത് നിങ്ങളുടെ വ്യക്തിഗത ക്യൂ ആണ്, ഓരോ ദിവസവും തുടങ്ങാൻ ഏറ്റവും നല്ല സ്ഥലം.',
            'field_unassigned' => '<strong>നിയോഗിക്കാത്തവ</strong> &mdash; വന്നുചേർന്നിട്ടുള്ളതും എന്നാൽ ഇതുവരെ ഒരു അനലിസ്റ്റും ഇല്ലാത്തതുമായ ടിക്കറ്റുകൾ. ഉടമസ്ഥാവകാശം ഏറ്റെടുക്കാൻ ഇവിടെ നിന്ന് ഇനങ്ങൾ തിരഞ്ഞെടുക്കുക.',
            'field_all_open' => '<strong>എല്ലാ തുറന്നവയും</strong> &mdash; ആരുടെ ഉടമസ്ഥതയിലാണെങ്കിലും ഇതുവരെ അടയ്ക്കാത്ത എല്ലാ ടിക്കറ്റുകളും. മൊത്തം വോള്യം നിരീക്ഷിക്കുന്ന മാനേജർമാർക്കും ടീം ലീഡുകൾക്കും ഉപയോഗപ്രദം.',
            'field_closed' => '<strong>അടച്ചവ</strong> &mdash; പരിഹരിച്ച ടിക്കറ്റുകൾ. മുൻകാല പരിഹാരം റഫർ ചെയ്യേണ്ടതോ ഒരു പ്രശ്നം വീണ്ടും തുറക്കേണ്ടതോ ആയ സാഹചര്യത്തിൽ ഇവിടെ തിരയുക.',
            'field_dept' => '<strong>വകുപ്പ് ഫോൾഡറുകൾ</strong> &mdash; വകുപ്പ് അനുസരിച്ച് ഗ്രൂപ്പ് ചെയ്ത ടിക്കറ്റുകൾ (ഉദാ. IT, HR, Finance). വകുപ്പുകൾ ക്രമീകരണങ്ങളിൽ സജ്ജീകരിക്കുന്നു, അവ സ്വയമേവ സബ്-ഫോൾഡറുകളായി പ്രത്യക്ഷപ്പെടും.',
            'switch_heading' => '<strong>വകുപ്പ്, അനലിസ്റ്റ് ഗ്രൂപ്പിംഗ് തമ്മിൽ മാറൽ</strong>',
            'switch_body' => 'ഫോൾഡർ പാനലിന്റെ മുകളിലുള്ള ചെറിയ രണ്ട്-ബട്ടൺ ടോഗിൾ ഒരേ ഡാറ്റയുടെ രണ്ട് വ്യൂകൾ തമ്മിൽ മാറുന്നു. <strong>വകുപ്പ്</strong> ഗ്രൂപ്പിംഗ് (സ്ഥിരസ്ഥിതി) ഓരോ വകുപ്പിനും കീഴിൽ, അതിനുള്ളിൽ നില സബ്-ഫോൾഡറുകളോടെ ടിക്കറ്റുകൾ ലിസ്റ്റ് ചെയ്യുന്നു; <strong>അനലിസ്റ്റ്</strong> ഗ്രൂപ്പിംഗ് ഇത് മറിച്ചിടുന്നു, അതിനാൽ ഓരോ ടോപ്പ്-ലെവൽ ഫോൾഡറും അതിനുള്ളിൽ നില സബ്-ഫോൾഡറുകളോടെ ഒരു അനലിസ്റ്റിന്റെ വ്യക്തിഗത ക്യൂവിനെ പ്രതിനിധീകരിക്കുന്നു. <strong>നിയോഗിക്കാത്തവ</strong> ഫോൾഡർ ഓരോ വ്യൂവിലും സന്ദർഭത്തിനനുസരിച്ച് മാറുന്നു &mdash; വകുപ്പ് വ്യൂവിൽ വകുപ്പ് സജ്ജമാക്കാത്ത ടിക്കറ്റുകൾ ഇത് ലിസ്റ്റ് ചെയ്യുന്നു; അനലിസ്റ്റ് വ്യൂവിൽ അസൈനി ഇല്ലാത്ത ടിക്കറ്റുകൾ ഇത് ലിസ്റ്റ് ചെയ്യുന്നു &mdash; അതിനാൽ എടുക്കേണ്ടത് എന്താണെന്ന് നിങ്ങൾക്ക് എപ്പോഴും കാണാം. നിങ്ങളുടെ തിരഞ്ഞെടുപ്പ് ഓരോ അനലിസ്റ്റിനും പ്രത്യേകം സേവ് ചെയ്യുന്നു, അതിനാൽ ഓരോ ടീം അംഗവും സെഷനുകളിലുടനീളം അവർക്കിഷ്ടമുള്ള വ്യൂ നിലനിർത്തുന്നു.',
            'row_name' => 'ഓരോ വരിയും ടിക്കറ്റ് റഫറൻസും പിന്നീട് ഒരു പേരും കാണിക്കുന്നു. സ്ഥിരസ്ഥിതിയായി അത് <strong>ടിക്കറ്റ് ഉയർത്തിയ വ്യക്തി</strong> ആണ്, ടിക്കറ്റിന്റെ ജീവിതകാലം മുഴുവൻ അത് അതേപടി തുടരും. ഏറ്റവും പുതിയ സന്ദേശം അയച്ചയാളെ കാണാനാണ് നിങ്ങൾ ആഗ്രഹിക്കുന്നതെങ്കിൽ &mdash; നിങ്ങൾ മറുപടി നൽകിക്കഴിഞ്ഞാൽ അത് നിങ്ങളുടെ സ്വന്തം മെയിൽബോക്സ് ആയി മാറും &mdash; <strong>ക്രമീകരണങ്ങൾ &rarr; വരി പ്രദർശനം</strong> എന്നതിന് കീഴിലുള്ള <strong>ടിക്കറ്റ് നമ്പറിന് അരികിലുള്ള പേര്</strong> മാറ്റുക, അവിടെ നിങ്ങൾക്ക് പേര് മറച്ച് റഫറൻസ് മാത്രം അവശേഷിപ്പിക്കാനും കഴിയും. ആ ടാബ് നിങ്ങളുടെ സ്വന്തം ക്രമീകരണമാണ്: മറ്റാർക്കും ഇത് ഒന്നും മാറ്റില്ല.',
            'tip' => 'ലിസ്റ്റിലെ ഏതെങ്കിലും ടിക്കറ്റിൽ ക്ലിക്ക് ചെയ്ത് റീഡിംഗ് പെയ്നിൽ ലോഡ് ചെയ്യുക. അവിടെ നിന്ന് നിങ്ങൾക്ക് ഫീൽഡുകൾ അപ്ഡേറ്റ് ചെയ്യാം, അഭിപ്രായങ്ങൾ ചേർക്കാം, ഇമെയിൽ വഴി മറുപടി നൽകാം, അല്ലെങ്കിൽ ഫയലുകൾ അറ്റാച്ച് ചെയ്യാം &mdash; ഇൻബോക്സ് വിട്ടുപോകാതെ തന്നെ.',
        ],
        'faster' => [
            'heading' => 'വേഗത്തിൽ പ്രവർത്തിക്കൽ',
            'intro' => 'തിരക്കേറിയ ഒരു രാവിലെയെ കൈകാര്യം ചെയ്യാവുന്നതാക്കി മാറ്റുന്ന നാല് കാര്യങ്ങൾ: സേവ് ചെയ്ത മറുപടികൾ, ഒരേസമയം പല ടിക്കറ്റുകളിലും പ്രവർത്തിക്കൽ, സംഭാഷണങ്ങൾ അവ ഉൾപ്പെടേണ്ടിടത്ത് വയ്ക്കൽ.',
            'templates_heading' => 'തയ്യാറാക്കിയ മറുപടികൾ',
            'templates_body' => 'നിങ്ങൾ അതേ ഏതാനും മറുപടികൾ തന്നെ നിരന്തരം അയയ്ക്കുന്നു. ഒരിക്കൽ ഒന്ന് എഴുതുക, എന്നിട്ട് നിങ്ങളുടെ കഴ്സറിൽ അത് ഇടാൻ റിപ്ലൈ എഡിറ്ററിന് മുകളിലുള്ള <strong>ടെംപ്ലേറ്റുകൾ</strong> ക്ലിക്ക് ചെയ്യുക &mdash; ഇത് നിങ്ങൾ ഇതിനകം ടൈപ്പ് ചെയ്തതിനെ മാറ്റിസ്ഥാപിക്കുന്നതിന് പകരം അതിനോട് കൂട്ടിച്ചേർക്കുന്നു. ടെംപ്ലേറ്റുകൾ റിച്ച് ടെക്സ്റ്റ് ആണ്, ഓട്ടോമേറ്റഡ് ഇമെയിലുകളിലേതു പോലെ അതേ <code>[merge_code]</code> പ്ലേസ്ഹോൾഡറുകളെ പിന്തുണയ്ക്കുന്നു, അതിനാൽ നിങ്ങൾ ചേർക്കുമ്പോൾ <code>[requester_first_name]</code> യഥാർത്ഥ പേരായി മാറുന്നു.',
            'templates_team' => '<strong>ടീം ടെംപ്ലേറ്റുകൾ</strong> &mdash; എല്ലാവരുമായും പങ്കിട്ടത്, ക്രമീകരണങ്ങൾ &rarr; റിപ്ലൈ ടെംപ്ലേറ്റുകളിൽ സജ്ജീകരിച്ചത്.',
            'templates_mine' => '<strong>നിങ്ങളുടേത്</strong> &mdash; <em>ഡ്രാഫ്റ്റ് ടെംപ്ലേറ്റായി സംരക്ഷിക്കുക</em> ഉപയോഗിച്ച് ഒരു ഡ്രാഫ്റ്റ് സേവ് ചെയ്യുക. നിങ്ങൾക്ക് മാത്രം സ്വകാര്യം, അനുമതി ആവശ്യമില്ല.',
            'templates_tip' => 'ടെംപ്ലേറ്റിന് അതിന്റെ വാക്കുകൾക്കല്ല, സാഹചര്യത്തിനനുസരിച്ച് പേര് നൽകുക ("Printer offline &mdash; first steps"). രാവിലെ 9 മണിക്ക് നിങ്ങൾ തിരയാൻ പോകുന്നത് അതാണ്.',
            'select_heading' => 'പല ടിക്കറ്റുകൾ തിരഞ്ഞെടുക്കൽ',
            'select_body' => 'ടിക്കറ്റ് ലിസ്റ്റ് Outlook അല്ലെങ്കിൽ File Explorer പോലെ പ്രവർത്തിക്കുന്നു. ചെക്ക്ബോക്സുകളില്ല.',
            'key_click' => 'ക്ലിക്ക്',
            'key_click_d' => 'ഒന്ന് തിരഞ്ഞെടുത്ത് തുറക്കുക',
            'key_ctrl' => 'Ctrl+ക്ലിക്ക്',
            'key_ctrl_d' => 'ഒന്ന് ചേർക്കുകയോ നീക്കം ചെയ്യുകയോ ചെയ്യുക, ബാക്കിയുള്ളവ അതേപടി വിടുക',
            'key_shift' => 'Shift+ക്ലിക്ക്',
            'key_shift_d' => 'നിങ്ങൾ അവസാനം ക്ലിക്ക് ചെയ്തിടത്ത് നിന്ന് ഒരു മുഴുവൻ ബ്ലോക്ക് തിരഞ്ഞെടുക്കുക',
            'key_kb' => 'കീബോർഡ്',
            'key_kb_d' => 'നീങ്ങാൻ ആരോകൾ, വികസിപ്പിക്കാൻ Shift+ആരോകൾ, ചിതറിക്കിടക്കുന്ന ടിക്കറ്റുകൾ തിരഞ്ഞെടുക്കാൻ Ctrl+ആരോകളും Space ഉം, എല്ലാം തിരഞ്ഞെടുക്കാൻ Ctrl+A, മായ്ക്കാൻ Escape',
            'select_actions' => 'പലതും തിരഞ്ഞെടുത്ത ശേഷം, അവയെല്ലാത്തിനും ഒരുമിച്ച് നില, മുൻഗണന, വകുപ്പ്, തരം അല്ലെങ്കിൽ അസൈനി സജ്ജമാക്കാൻ <strong>അവയിൽ ഏതെങ്കിലും ഒന്നിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്യുക</strong> &mdash; അല്ലെങ്കിൽ മുഴുവൻ സെറ്റും ഒരു ഫോൾഡറിലേക്ക് വലിച്ചിടുക. പലതും തിരഞ്ഞെടുത്തിരിക്കുമ്പോൾ സ്ക്രീൻ എന്ത് കാണിക്കുന്നു എന്നത് നിങ്ങളുടെ തിരഞ്ഞെടുപ്പാണ്, അക്കൗണ്ട് മെനുവിലെ Preferences-ന് കീഴിൽ.',
            'select_tip' => 'നിങ്ങളുടെ തിരഞ്ഞെടുപ്പിൽ <em>ഇല്ലാത്ത</em> ഒരു ടിക്കറ്റിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്യുന്നത് തിരഞ്ഞെടുപ്പ് മായ്ച്ച് ആ ഒന്നിനെ മാത്രം ടാർഗെറ്റ് ചെയ്യുന്നു. അത് മനഃപൂർവമാണ് &mdash; നിങ്ങൾ ഉപേക്ഷിച്ചു എന്ന് കരുതിയ ഒരു സെറ്റിൽ നിങ്ങൾക്ക് ഒരിക്കലും പ്രവർത്തിക്കാൻ കഴിയില്ല.',
            'merge_heading' => 'ഡ്യൂപ്ലിക്കേറ്റുകൾ ലയിപ്പിക്കൽ',
            'merge_body' => 'രണ്ട് പേർ ഒരേ തടസ്സം റിപ്പോർട്ട് ചെയ്തോ? ടിക്കറ്റുകൾ തിരഞ്ഞെടുത്ത്, റൈറ്റ്-ക്ലിക്ക് ചെയ്ത്, <strong>ലയിപ്പിക്കുക</strong>. സംഭാഷണങ്ങൾ ഒരുമിച്ച് വരുന്നു, നിങ്ങൾ ഒരു AI ദാതാവ് സജ്ജീകരിച്ചിട്ടുണ്ടെങ്കിൽ, എല്ലാവരും ചോദിച്ചതും ഇതിനകം ചെയ്തതും എന്താണെന്നതിന്റെ ഒരു ചെറിയ ബ്രീഫിംഗ് FreeITSM എഴുതുന്നു, അതിനാൽ ഇത് ഏറ്റെടുക്കുന്നയാൾക്ക് നാല് ത്രെഡുകൾ വായിക്കേണ്ടി വരില്ല.',
            'merge_tip' => 'ഒന്നും ഒരിക്കലും ഇല്ലാതാക്കില്ല. ലയിപ്പിച്ചുപോയ ടിക്കറ്റ് അതിന്റെ റഫറൻസ് നിലനിർത്തുന്നു, തിരയാൻ കഴിയുന്നതായി തുടരുന്നു, അത് എവിടേക്ക് പോയി എന്ന് കാണിക്കുന്നു &mdash; അതിനെക്കുറിച്ചുള്ള ഒരു പഴയ ഇമെയിലിന് മറുപടി നൽകുന്ന ഒരു കസ്റ്റമർ ഇപ്പോഴും നിങ്ങളിലേക്ക് എത്തുന്നു.',
            'split_heading' => 'ഒരു ടിക്കറ്റ് വിഭജിക്കൽ',
            'split_body' => 'ഇതിന്റെ എതിർ ജോലി. ഒരു സംഭാഷണത്തിന്റെ പകുതിയിൽ ആരെങ്കിലും രണ്ടാമതൊരു, ബന്ധമില്ലാത്ത കാര്യം ഉന്നയിക്കുമ്പോൾ, ആ സന്ദേശത്തിൽ <strong>വിഭജിക്കുക</strong> ക്ലിക്ക് ചെയ്യുക (അല്ലെങ്കിൽ സന്ദേശ ഹെഡറിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്യുക). ഇത് ഒരു പുതിയ ടിക്കറ്റിലേക്ക് മാറുന്നു, ഇഷ്ടാനുസരണം അതിനുശേഷമുള്ള എല്ലാ സന്ദേശങ്ങളും കൂടെ കൊണ്ടുപോകുന്നു, യഥാർത്ഥ ടിക്കറ്റ് അവ എവിടേക്ക് പോയി എന്ന് കാണിക്കുന്ന ഒരു മാർക്കർ നിലനിർത്തുന്നു.',
            'split_tip' => 'പുതിയ ടിക്കറ്റിന് ശരിയായ ഒരു വിഷയം നൽകുക. ഇത് സ്ഥിരസ്ഥിതിയായി മാറ്റിയ സന്ദേശത്തിന്റേതായിരിക്കും, അത് സാധാരണയായി <em>പഴയ</em> പ്രശ്നത്തിന്റെ ഒരു "RE:" ആയിരിക്കും.',
            'undo_heading' => 'മനസ്സ് മാറിയോ',
            'undo_body' => 'രണ്ടും ടിക്കറ്റിലെ ബാനറിൽ നിന്ന് പഴയപടിയാക്കാം. പുതിയ ടിക്കറ്റിൽ ആരെങ്കിലും മറുപടി നൽകിയോ, കുറിപ്പ് ചേർത്തോ, സമയം രേഖപ്പെടുത്തിയോ കഴിഞ്ഞാൽ <strong>വിഭജനം</strong> പഴയപടിയാക്കുന്നത് നിഷേധിക്കപ്പെടും &mdash; എന്താണ് തടസ്സമെന്ന് കൃത്യമായി നിങ്ങളോട് പറയും. <strong>ലയനം</strong> പഴയപടിയാക്കുന്നത് ടിക്കറ്റിന് അതിന്റെ സന്ദേശങ്ങളും കുറിപ്പുകളും രേഖപ്പെടുത്തിയ സമയവും തിരികെ നൽകുകയും അത് പഴയപടി തുറക്കുകയും ചെയ്യുന്നു, എന്നാൽ ലയനത്തിനുശേഷം മറ്റേ ടിക്കറ്റിൽ എഴുതിയ മറുപടികൾ അവിടെത്തന്നെ നിൽക്കും.',
        ],
        'working' => [
            'heading' => 'ടിക്കറ്റുകളുമായി പ്രവർത്തിക്കൽ',
            'intro' => 'ഓരോ സപ്പോർട്ട് അഭ്യർത്ഥനയും ഒരു ജീവിതചക്രം പിന്തുടരുന്നു: അത് സൃഷ്ടിക്കപ്പെടുന്നു, ട്രയാജ് ചെയ്യപ്പെടുന്നു, അതിൽ പ്രവർത്തിക്കുന്നു, ഒടുവിൽ പരിഹരിക്കപ്പെടുന്നു. പ്രാരംഭ ലോഗിംഗ് മുതൽ ക്ലോഷർ വരെ ഓരോ ഘട്ടവും കാര്യക്ഷമമായി കൈകാര്യം ചെയ്യാനുള്ള ടൂളുകൾ ടിക്കറ്റുകൾ മൊഡ്യൂൾ നിങ്ങൾക്ക് നൽകുന്നു.',
            'creating_heading' => '<strong>പുതിയ ടിക്കറ്റ് സൃഷ്ടിക്കൽ</strong>',
            'step1' => '<strong>പുതിയത് ക്ലിക്ക് ചെയ്യുക</strong> &mdash; ഇൻബോക്സ് ടൂൾബാറിൽ നിന്ന് പുതിയ ടിക്കറ്റ് മോഡൽ തുറക്കുക. അപ്ഡേറ്റുകൾ ലഭിക്കാൻ അഭ്യർത്ഥിച്ചയാളുടെ പേരും ഇമെയിൽ വിലാസവും നൽകുക.',
            'step2' => '<strong>വിഷയം സജ്ജമാക്കുക</strong> &mdash; പ്രശ്നത്തിന്റെ വ്യക്തവും സംക്ഷിപ്തവുമായ ഒരു സംഗ്രഹം എഴുതുക. ഇത് ടിക്കറ്റ് ലിസ്റ്റിലും എൻഡ് യൂസറിന് അയയ്ക്കുന്ന ഇമെയിൽ അറിയിപ്പുകളിലും പ്രത്യക്ഷപ്പെടും.',
            'step3' => '<strong>വകുപ്പ്, തരം, മുൻഗണന എന്നിവ തിരഞ്ഞെടുക്കുക</strong> &mdash; അനുയോജ്യമായ വകുപ്പ്, ടിക്കറ്റ് തരം (ഉദാ. Incident, Service Request), മുൻഗണനാ നിലവാരം എന്നിവ തിരഞ്ഞെടുക്കുക. ഈ ഫീൽഡുകൾ SLA ടൈമറുകളും റൂട്ടിംഗ് നിയമങ്ങളും നിയന്ത്രിക്കുന്നു.',
            'step4' => '<strong>വിവരണം ചേർക്കുക</strong> &mdash; റിച്ച് ടെക്സ്റ്റ് എഡിറ്റർ ഉപയോഗിച്ച് പ്രശ്നത്തിന്റെ പൂർണ്ണ വിശദാംശങ്ങൾ നൽകുക. പുനരാവർത്തിക്കാനുള്ള ഘട്ടങ്ങൾ, പിശക് സന്ദേശങ്ങൾ, പരിഹരിക്കുന്ന അനലിസ്റ്റിന് ആവശ്യമായേക്കാവുന്ന പ്രസക്തമായ ഏത് സന്ദർഭവും ഉൾപ്പെടുത്തുക.',
            'step5' => '<strong>സംരക്ഷിക്കുക</strong> &mdash; ടിക്കറ്റ് ഒരു തനത് റഫറൻസ് നമ്പറോടെ സൃഷ്ടിക്കപ്പെടുകയും അനുയോജ്യമായ ഫോൾഡറിൽ പ്രത്യക്ഷപ്പെടുകയും ചെയ്യുന്നു. മുൻഗണനയെ അടിസ്ഥാനമാക്കി SLA ക്ലോക്ക് ഉടനടി ആരംഭിക്കുന്നു.',
            'editing_heading' => '<strong>ടിക്കറ്റുകൾ എഡിറ്റ് ചെയ്യലും കൈകാര്യം ചെയ്യലും</strong>',
            'editing_body' => 'ഒരു ടിക്കറ്റ് നിലവിലുണ്ടായിക്കഴിഞ്ഞാൽ, റീഡിംഗ് പെയ്നിൽ നിന്ന് നിങ്ങൾക്ക് ഏത് ഫീൽഡും അപ്ഡേറ്റ് ചെയ്യാം. പ്രധാന ഫീൽഡുകളിൽ ഇവ ഉൾപ്പെടുന്നു:',
            'card_status_title' => 'നില',
            'card_status_body' => 'ടിക്കറ്റ് ജീവിതചക്രം ട്രാക്ക് ചെയ്യുക: പുതിയത്, തുറന്നത്, പുരോഗതിയിൽ, തീർപ്പാക്കാത്തത്, പരിഹരിച്ചത്, അടച്ചത്',
            'card_priority_title' => 'മുൻഗണന',
            'card_priority_body' => 'അടിയന്തിരതയും ആഘാതവും സജ്ജമാക്കുക: ഗുരുതരം, ഉയർന്നത്, ഇടത്തരം, കുറവ്. ഓരോ നിലവാരത്തിനും അതിന്റേതായ SLA ലക്ഷ്യമുണ്ട്',
            'card_category_title' => 'വിഭാഗം',
            'card_category_body' => 'പ്രശ്ന തരം തരംതിരിക്കുക: Hardware, Software, Network, Access, General. റിപ്പോർട്ടിംഗിന് ഉപയോഗപ്രദം',
            'card_analyst_title' => 'നിയോഗിച്ച അനലിസ്റ്റ്',
            'card_analyst_body' => 'ടിക്കറ്റ് പരിഹരിക്കുന്നതിന് ഉത്തരവാദിയായ വ്യക്തി. പുനർനിയോഗം ആക്ടിവിറ്റി ട്രെയിലിൽ രേഖപ്പെടുത്തുന്നു',
            'card_enduser_title' => 'എൻഡ് യൂസർ',
            'card_enduser_body' => 'അഭ്യർത്ഥന ഉയർത്തിയ വ്യക്തി. നിലവിലുള്ള ഒരു ഉപയോക്തൃ റെക്കോർഡിലേക്ക് ലിങ്ക് ചെയ്യാൻ പേര് അല്ലെങ്കിൽ ഇമെയിൽ വഴി തിരയുക',
            'card_dept_title' => 'വകുപ്പ്',
            'card_dept_body' => 'ടിക്കറ്റുകൾ ശരിയായ ടീമിലേക്ക് റൂട്ട് ചെയ്യുക. വകുപ്പുകൾ ഫോൾഡർ ഗ്രൂപ്പിംഗും ഡാഷ്‌ബോർഡ് ഫിൽട്ടറുകളും നിയന്ത്രിക്കുന്നു',
            'flow_new' => 'പുതിയത്',
            'flow_in_progress' => 'പുരോഗതിയിൽ',
            'flow_resolved' => 'പരിഹരിച്ചു',
            'flow_closed' => 'അടച്ചു',
            'triage_heading' => '<strong>ഡ്രാഗ് ആൻഡ് ഡ്രോപ്പ് വഴി ട്രയാജ്</strong>',
            'triage_body' => 'ഒരു ടിക്കറ്റ് ട്രയാജ് ചെയ്യാൻ അത് തുറക്കേണ്ട ആവശ്യമില്ല. ഒറ്റ ചലനത്തിൽ ഫീൽഡുകൾ അപ്ഡേറ്റ് ചെയ്യാൻ ടിക്കറ്റ് ലിസ്റ്റിൽ നിന്ന് ഏതെങ്കിലും വരി ഒരു ഫോൾഡറിലേക്ക് വലിച്ചിടുക:',
            'triage_dept' => '<strong>വകുപ്പ് വ്യൂ</strong> &mdash; പുനർനിയോഗിക്കാൻ ഒരു വകുപ്പ് ഫോൾഡറിൽ ഇടുക, ഒരേസമയം രണ്ടും അപ്ഡേറ്റ് ചെയ്യാൻ ഒരു വകുപ്പിന് കീഴിലുള്ള നില സബ്-ഫോൾഡറിൽ ഇടുക, വകുപ്പ് മായ്ക്കാൻ <strong>നിയോഗിക്കാത്തവ</strong>യിൽ ഇടുക.',
            'triage_analyst' => '<strong>അനലിസ്റ്റ് വ്യൂ</strong> &mdash; ആ അനലിസ്റ്റിനെ ഉടമയായി നിയോഗിക്കാൻ ഒരു അനലിസ്റ്റിന്റെ ഫോൾഡറിൽ ഇടുക (<code>assigned_analyst_id</code>, <code>owner_id</code> എന്നിവ രണ്ടും സജ്ജമാക്കുന്നു, അതിനാൽ റീഡിംഗ് പെയ്നിലെ Owner ഫീൽഡ് സമന്വയത്തിൽ തുടരും), രണ്ടും അപ്ഡേറ്റ് ചെയ്യാൻ ഒരു നില സബ്-ഫോൾഡറിൽ ഇടുക, അസൈനി മായ്ക്കാൻ <strong>നിയോഗിക്കാത്തവ</strong>യിൽ ഇടുക.',
            'triage_spring' => '<strong>സ്പ്രിംഗ്-ലോഡഡ് ഫോൾഡറുകൾ</strong> &mdash; ഒരു ഡ്രാഗിനിടയിൽ ചുരുക്കിയ ഒരു ഫോൾഡറിന് മുകളിൽ ഹോവർ ചെയ്താൽ അത് സ്വയമേവ വികസിക്കും (Outlook ശൈലിയിൽ), അതിനാൽ ആദ്യം ഇടാതെ തന്നെ ഏത് നെസ്റ്റഡ് നിലയും എത്തിച്ചേരാവുന്നതാണ്.',
            'fullscreen_heading' => '<strong>ഫുൾ-സ്ക്രീൻ വ്യൂ</strong>',
            'fullscreen_body' => 'ഒരൊറ്റ ടിക്കറ്റിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കേണ്ടി വരുമ്പോൾ &mdash; ഒരു നീണ്ട സംഭാഷണം, സങ്കീർണ്ണമായ ഒരു മാറ്റം, വിശദമായ ഒരു മറുപടി തയ്യാറാക്കൽ &mdash; ഫുൾ-സ്ക്രീൻ വ്യൂവിലേക്ക് മാറുക. ഫോൾഡർ ലിസ്റ്റും ടിക്കറ്റ് ലിസ്റ്റും അപ്രത്യക്ഷമാകുന്നു, സംഭാഷണം ലഭ്യമായ വീതി മുഴുവൻ നിറയ്ക്കുന്നു, പ്രോപ്പർട്ടികൾ (Department, Type, Status, Origin, First Time Fix, IT Training, Owner) വലത് വശത്തെ ലംബമായ സൈഡ്ബാറിലേക്ക് മാറുന്നു.',
            'fullscreen_max' => '<strong>Maximize ഐക്കൺ</strong> &mdash; ടിക്കറ്റ് വിഷയ വരിയുടെ വലത് അറ്റത്തുള്ള ചെറിയ ഐക്കൺ. ഫുൾ-സ്ക്രീനിലേക്ക് പ്രവേശിക്കാൻ ക്ലിക്ക് ചെയ്യുക; 3-പെയ്ൻ ലേഔട്ടിലേക്ക് മടങ്ങാൻ വീണ്ടും ക്ലിക്ക് ചെയ്യുക.',
            'fullscreen_dbl' => '<strong>ഒരു വരിയിൽ ഡബിൾ-ക്ലിക്ക് ചെയ്യുക</strong> &mdash; ലിസ്റ്റിലെ ഏതെങ്കിലും ടിക്കറ്റ് നേരിട്ട് ഫുൾ-സ്ക്രീനിൽ തുറക്കാൻ അതിൽ ഡബിൾ-ക്ലിക്ക് ചെയ്യുക, Outlook ശൈലിയിലുള്ള "really open this one" ജെസ്ച്ചർ.',
            'fullscreen_sticks' => '<strong>തിരഞ്ഞെടുപ്പുകളിലുടനീളം നിലനിൽക്കുന്നു</strong> &mdash; നിങ്ങൾ ഫുൾ-സ്ക്രീനിൽ ആയിക്കഴിഞ്ഞാൽ, അടുത്ത ടിക്കറ്റിലേക്ക് മാറുന്നത് നിങ്ങളെ അവിടെത്തന്നെ നിർത്തും. ഒരു ടിക്കറ്റും തിരഞ്ഞെടുക്കാതെ ഒരു പുതിയ പേജ് റീലോഡ് (F5) സ്ഥിരസ്ഥിതി 3-കോളം ലേഔട്ടിലേക്ക് മടങ്ങുന്നു, അതിനാൽ ഫോൾഡർ ലിസ്റ്റ് മറഞ്ഞ നിലയിൽ നിങ്ങൾ കുടുങ്ങിപ്പോകില്ല.',
            'rightclick_heading' => '<strong>പെട്ടെന്നുള്ള പ്രവർത്തനങ്ങൾക്ക് റൈറ്റ്-ക്ലിക്ക്</strong>',
            'rightclick_body' => 'ഒരു കോൺടെക്സ്റ്റ് മെനു തുറക്കാൻ ലിസ്റ്റിലെ ഏതെങ്കിലും ടിക്കറ്റിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്യുക. നിങ്ങൾ എന്തിലാണ് പ്രവർത്തിക്കുന്നതെന്ന് അറിയാൻ മെനു മുകളിൽ ടിക്കറ്റ് റഫറൻസ് കാണിക്കുന്നു, ഓരോ പ്രവർത്തനവും റീഡിംഗ് പെയ്നിൽ നിലവിൽ തുറന്നിരിക്കുന്നത് മാറ്റാതെ <em>തന്നെ</em> റൈറ്റ്-ക്ലിക്ക് ചെയ്ത ടിക്കറ്റിൽ പ്രവർത്തിക്കുന്നു &mdash; നിങ്ങൾ ടിക്കറ്റ് A വായിക്കുകയും നിങ്ങളുടെ സ്ഥാനം നഷ്ടപ്പെടാതെ ടിക്കറ്റ് B ട്രയാജ് ചെയ്യേണ്ടതായി വരികയും ചെയ്യുമ്പോൾ ഉപയോഗപ്രദം.',
            'rightclick_status' => '<strong>Set status &rarr;</strong> &mdash; ഓരോ സജീവ നിലയും അതിന്റെ കളർ സ്വാച്ചോടെ ലിസ്റ്റ് ചെയ്യുന്ന ഫ്ലൈഔട്ട് സബ്മെനു. നിങ്ങൾ തുറന്നിരിക്കുന്ന ടിക്കറ്റിൽ തന്നെയാണ് റൈറ്റ്-ക്ലിക്ക് ചെയ്യുന്നതെങ്കിൽ നിലവിലെ മൂല്യത്തിന് അരികിൽ ഒരു ടിക് പ്രത്യക്ഷപ്പെടും. തിരഞ്ഞെടുക്കുന്നത് ഉടനടി ടിക്കറ്റ് അപ്ഡേറ്റ് ചെയ്യുന്നു, ഒരു ഓഡിറ്റ്-ട്രെയിൽ എൻട്രി എഴുതുന്നു, ഫോൾഡർ എണ്ണങ്ങൾ പുതുക്കുന്നു, ബാധകമെങ്കിൽ റീഡിംഗ് പെയ്നിന്റെ Status ഡ്രോപ്പ്ഡൗൺ സമന്വയിപ്പിക്കുന്നു.',
            'rightclick_priority' => '<strong>Set priority &rarr;</strong> &mdash; അതേ ഫ്ലൈഔട്ട് പാറ്റേൺ, ഓരോന്നിന്റെയും നിറം സ്വാച്ചായി ഉപയോഗിച്ച് സജീവ മുൻഗണനകളുടെ ലുക്കപ്പിൽ നിന്ന്. നിയോഗം മായ്ക്കാനുള്ള <em>(മുൻഗണനയില്ല)</em> ഓപ്ഷനാണ് ആദ്യ വരി (മുൻഗണന nullable ആണ്).',
            'rightclick_assign' => '<strong>Assign to &rarr;</strong> &mdash; ലോഡ് ചെയ്ത ഓരോ അനലിസ്റ്റിനെയും ഒരു ചാര ഇനീഷ്യൽ ചിപ്പോടെ ലിസ്റ്റ് ചെയ്യുന്ന സബ്മെനു, മായ്ക്കാൻ മുകളിൽ ഒരു <em>(നിയോഗിച്ചിട്ടില്ല)</em> വരിയും. തിരഞ്ഞെടുക്കുന്നത് <code>assigned_analyst_id</code>, <code>owner_id</code> എന്നിവ രണ്ടും സജ്ജമാക്കുന്നു, അതിനാൽ റീഡിംഗ് പെയ്നിന്റെ Owner ഫീൽഡ് സമന്വയത്തിൽ തുടരും.',
            'rightclick_cmdb' => '<strong>Link CMDB object&hellip;</strong> &mdash; ടൈപ്പ് ചെയ്യുമ്പോൾ തിരയുന്ന ഒരു പിക്കർ തുറക്കുന്നു. ലിങ്ക് ചെയ്യാൻ ഒരു റിസൾട്ടിൽ ക്ലിക്ക് ചെയ്യുക, എന്നിട്ട് തിരഞ്ഞെടുക്കൽ തുടരുക &mdash; ഇൻപുട്ട് മായ്ക്കുകയും അടുത്തതിനായി വീണ്ടും ഫോക്കസ് ചെയ്യുകയും ചെയ്യുന്നു, മോഡലിനുള്ളിലെ ഒരു "Recently linked" ലോഗ് പച്ച-ടിക് സ്ഥിരീകരണങ്ങളുടെ നിങ്ങളുടെ തുടർച്ചയായ ലിസ്റ്റ് കാണിക്കുന്നു.',
            'rightclick_time' => '<strong>Record time&hellip;</strong> &mdash; മിനിറ്റുകൾ + ഒരു ഡേറ്റ്ടൈം പിക്കർ (ബാക്ക്ഡേറ്റ് ചെയ്യാനും കഴിയുന്ന വിധം സ്ഥിരസ്ഥിതിയായി "now") + ഒരു ഐച്ഛിക കുറിപ്പുകൾ ബോക്സ് എന്നിവയുള്ള ഒരു മോഡൽ തുറക്കുന്നു.',
            'rightclick_tip' => 'കോൺടെക്സ്റ്റ് മെനു വഴി നിങ്ങൾ പ്രവർത്തിക്കുന്ന ടിക്കറ്റ് യാദൃച്ഛികമായി റീഡിംഗ് പെയ്നിൽ തുറന്നിരിക്കുന്ന അതേ ഒന്നാണെങ്കിൽ, മോഡൽ അടയുമ്പോൾ അവിടത്തെ പ്രസക്തമായ വിഭാഗം (Status / Priority ഡ്രോപ്പ്ഡൗണുകൾ, CMDB ഒബ്ജക്റ്റുകൾ, ടൈം എൻട്രികൾ) സ്വയമേവ പുതുക്കുന്നു, അതിനാൽ UI സമന്വയത്തിൽ തുടരും.',
            'time_heading' => '<strong>സമയം രേഖപ്പെടുത്തൽ</strong>',
            'time_body' => 'ഒരു ടിക്കറ്റിൽ ചെലവഴിച്ച സമയം, ലിങ്ക് ചെയ്ത CMDB ഒബ്ജക്റ്റുകൾ പാനലിനും Notes പാനലിനും ഇടയിൽ സ്ഥിതി ചെയ്യുന്ന റീഡിംഗ് പെയ്നിലെ പ്രത്യേകമായ <strong>Time Entries</strong> വിഭാഗത്തിൽ രേഖപ്പെടുത്തുന്നു. ഹെഡർ ആകെ തുക കാണിക്കുന്നു (ഉദാ. "Total 2h 30m"), താഴെയുള്ള ഓരോ എൻട്രിയും ചെലവഴിച്ച സമയം, അനലിസ്റ്റ്, തീയതി, നിങ്ങൾ ചേർത്ത ഏത് കുറിപ്പുകളും കാണിക്കുന്നു.',
            'time_step1' => '<strong>ഇൻലൈൻ ഫോം</strong> &mdash; ചെലവഴിച്ച മിനിറ്റുകൾ ന്യൂമെറിക് ഇൻപുട്ടിലും, ഐച്ഛികമായ ഒരു ചെറിയ വിവരണം നോട്ട്സ് ഇൻപുട്ടിലും ടൈപ്പ് ചെയ്ത് <strong>ചേർക്കുക</strong> ക്ലിക്ക് ചെയ്യുക. പുതിയ എൻട്രി നിങ്ങളുടെ പേരും നിലവിലെ ടൈംസ്റ്റാമ്പുമായി ഉടനടി ലിസ്റ്റിന്റെ മുകളിൽ പ്രത്യക്ഷപ്പെടും.',
            'time_step2' => '<strong>റൈറ്റ്-ക്ലിക്ക് വഴി ബാക്ക്ഡേറ്റ്</strong> &mdash; നേരത്തെ രേഖപ്പെടുത്താൻ മറന്നുപോയ സമയം ലോഗ് ചെയ്യേണ്ടതുണ്ടെങ്കിൽ, ലിസ്റ്റിലെ ടിക്കറ്റിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്ത് <strong>Record time&hellip;</strong> തിരഞ്ഞെടുക്കുക. ജോലി ചെയ്ത യഥാർത്ഥ സമയം എൻട്രിയിൽ സ്റ്റാമ്പ് ചെയ്യാൻ കഴിയുന്ന വിധം മോഡലിൽ ഒരു ഡേറ്റ്ടൈം പിക്കർ ഉൾപ്പെടുന്നു.',
            'time_step3' => '<strong>നിങ്ങളുടെ സ്വന്തം എൻട്രികൾ ഇല്ലാതാക്കുക</strong> &mdash; നിങ്ങൾ ലോഗ് ചെയ്ത എൻട്രികൾക്ക് അരികിൽ ഒരു ചെറിയ &times; ബട്ടൺ പ്രത്യക്ഷപ്പെടും. സോഫ്റ്റ്-ഡിലീറ്റ് ചെയ്യാൻ അതിൽ ക്ലിക്ക് ചെയ്യുക (സ്ഥിരീകരിക്കുക) &mdash; വരി ഓഡിറ്റിനായി <code>is_active = 0</code> എന്നതോടെ ഡാറ്റാബേസിൽ തുടരും, പക്ഷേ ലിസ്റ്റിൽ നിന്ന് അപ്രത്യക്ഷമാകും. മറ്റ് അനലിസ്റ്റുകളുടെ എൻട്രികൾ നിങ്ങൾക്ക് ഇല്ലാതാക്കാൻ കഴിയില്ല.',
            'time_tip1' => 'സമയങ്ങൾ വെറും മിനിറ്റുകളായി സൂക്ഷിക്കുന്നു (45 min, 90 min മുതലായവ), UI-യിൽ <code>45m</code> അല്ലെങ്കിൽ <code>1h 30m</code> ആയി പ്രദർശിപ്പിക്കുന്നു &mdash; ചെറിയ ഫിക്സുകൾക്ക് വേണ്ടത്ര സൂക്ഷ്മം, ദശാംശ-മണിക്കൂർ റൗണ്ടിംഗ് ബുദ്ധിമുട്ടില്ല.',
            'time_tip2' => 'ഓരോ ഫീൽഡ് മാറ്റവും ടിക്കറ്റിന്റെ ആക്ടിവിറ്റി ട്രെയിലിൽ രേഖപ്പെടുത്തുന്നു. ആരാണ് എന്ത് എപ്പോൾ മാറ്റിയത് എന്ന് നിങ്ങൾക്ക് എപ്പോഴും കാണാം, ഇത് ഓഡിറ്റ് കംപ്ലയൻസിനും അനലിസ്റ്റുകൾ തമ്മിലുള്ള കൈമാറ്റത്തിനും അത്യന്താപേക്ഷിതമാണ്.',
        ],
        'comments' => [
            'heading' => 'അഭിപ്രായങ്ങൾ &amp; അറ്റാച്ച്മെന്റുകൾ',
            'intro' => 'ആക്ടിവിറ്റി ട്രെയിൽ ഓരോ ടിക്കറ്റിന്റെയും ഹൃദയമാണ്. ഒരു സപ്പോർട്ട് അഭ്യർത്ഥനയുടെ പൂർണ്ണ കഥ പറയുന്ന ഒരു കാലക്രമ ടൈംലൈനിൽ, എടുത്ത ഓരോ പ്രവർത്തനവും &mdash; അഭിപ്രായങ്ങൾ, ഫീൽഡ് മാറ്റങ്ങൾ, അയച്ച ഇമെയിലുകൾ, അറ്റാച്ച് ചെയ്ത ഫയലുകൾ &mdash; ഇത് പിടിച്ചെടുക്കുന്നു.',
            'adding_heading' => '<strong>അഭിപ്രായങ്ങൾ ചേർക്കൽ</strong>',
            'step1' => '<strong>ടിക്കറ്റ് തുറക്കുക</strong> &mdash; അതിന്റെ റീഡിംഗ് പെയ്ൻ ലോഡ് ചെയ്യാൻ ഇൻബോക്സിലെ ഏതെങ്കിലും ടിക്കറ്റിൽ ക്ലിക്ക് ചെയ്യുക. പൂർണ്ണ ആക്ടിവിറ്റി ട്രെയിലും താഴെയുള്ള കമന്റ് ബോക്സും കാണാൻ താഴേക്ക് സ്ക്രോൾ ചെയ്യുക.',
            'step2' => '<strong>നിങ്ങളുടെ കുറിപ്പ് എഴുതുക</strong> &mdash; കമന്റ് എഡിറ്റർ തുറക്കാൻ Add Note ബട്ടൺ ഉപയോഗിക്കുക. കുറിപ്പുകൾ സ്ഥിരസ്ഥിതിയായി ആന്തരികമാണ്, സർവീസ് ഡെസ്കിലെ അനലിസ്റ്റുകൾക്ക് മാത്രം ദൃശ്യമാണ്.',
            'step3' => '<strong>ഇമെയിൽ വഴി മറുപടി നൽകുക അല്ലെങ്കിൽ ഫോർവേഡ് ചെയ്യുക</strong> &mdash; എൻഡ് യൂസറിനോ മൂന്നാം കക്ഷിക്കോ ഒരു സന്ദേശം അയയ്ക്കാൻ Reply അല്ലെങ്കിൽ Forward പ്രവർത്തനങ്ങൾ ഉപയോഗിക്കുക. ഔട്ട്ബൗണ്ട് സന്ദേശ ഉള്ളടക്കത്തിനൊപ്പം ഇമെയിൽ ആക്ടിവിറ്റി ട്രെയിലിൽ രേഖപ്പെടുത്തുന്നു.',
            'files_heading' => '<strong>ഫയൽ അറ്റാച്ച്മെന്റുകൾ</strong>',
            'files_body' => 'സ്ക്രീൻഷോട്ടുകൾ, ലോഗുകൾ, പ്രമാണങ്ങൾ, അല്ലെങ്കിൽ ഏത് സഹായക ഫയലും നേരിട്ട് ഒരു ടിക്കറ്റിലേക്ക് അറ്റാച്ച് ചെയ്യുക. ഫയലുകൾ അറ്റാച്ച്മെന്റ് ഡ്രോപ്പ് സോണിലേക്ക് വലിച്ചിടാം അല്ലെങ്കിൽ ഫയൽ ബ്രൗസർ ഉപയോഗിച്ച് തിരഞ്ഞെടുക്കാം. ഒന്നും നഷ്ടപ്പെടാതിരിക്കാൻ അറ്റാച്ച്മെന്റുകൾ സെർവറിൽ സൂക്ഷിക്കുകയും ടിക്കറ്റിന്റെ ആക്ടിവിറ്റി ട്രെയിലുമായി ലിങ്ക് ചെയ്യുകയും ചെയ്യുന്നു.',
            'audit_heading' => '<strong>ഓഡിറ്റ് ലോഗിംഗ്</strong>',
            'audit_body' => 'അനലിസ്റ്റിന്റെ ഇടപെടലില്ലാതെ ആക്ടിവിറ്റി ട്രെയിൽ എല്ലാ പ്രവർത്തനവും സ്വയമേവ രേഖപ്പെടുത്തുന്നു. ഒരു മുൻഗണന Medium-ൽ നിന്ന് High-ലേക്ക് മാറ്റുമ്പോൾ, പഴയതും പുതിയതുമായ മൂല്യങ്ങൾ പിടിച്ചെടുക്കുന്നു. ഒരു ടിക്കറ്റ് പുനർനിയോഗിക്കുമ്പോൾ, മുമ്പത്തെയും പുതിയതുമായ അനലിസ്റ്റ് രണ്ടും രേഖപ്പെടുത്തുന്നു. ഇത് ITIL ഓഡിറ്റ് ആവശ്യകതകൾ തൃപ്തിപ്പെടുത്തുന്ന, കൃത്രിമം കാണിക്കാനാവാത്ത ഒരു പൂർണ്ണ ചരിത്രം സൃഷ്ടിക്കുകയും ടിക്കറ്റുകൾ എങ്ങനെ കൈകാര്യം ചെയ്യുന്നു എന്ന് മാനേജർമാരെ മനസ്സിലാക്കാൻ സഹായിക്കുകയും ചെയ്യുന്നു.',
            'tip' => 'ഇമെയിൽ വഴി മറുപടി നൽകുമ്പോൾ, അതേ പ്രവർത്തനത്തിൽ തന്നെ നിങ്ങൾക്ക് Cc സ്വീകർത്താക്കളെ ചേർക്കാനും ഫയലുകൾ അറ്റാച്ച് ചെയ്യാനും കഴിയും. മുഴുവൻ ഇമെയിൽ സംഭാഷണവും ടിക്കറ്റിന്റെ ആക്ടിവിറ്റി ട്രെയിലിലേക്ക് ത്രെഡ് ചെയ്യുന്നു, എല്ലാ ആശയവിനിമയവും ഒരിടത്ത് നിലനിർത്തുന്നു.',
        ],
        'ai' => [
            'heading' => 'AI ടൂളുകൾ',
            'intro' => 'ടിക്കറ്റ് വർക്ക്ഫ്ലോയ്ക്കുള്ളിൽ Claude-പവർഡ് ആയ രണ്ട് ഫീച്ചറുകളുണ്ട്: <strong>Reply Cleanup</strong> ഒരു പരുക്കൻ ഡ്രാഫ്റ്റിനെ കൃത്യമായി ഫോർമാറ്റ് ചെയ്ത ഒരു ഇമെയിലായി വീണ്ടും എഴുതുന്നു, <strong>Ask AI</strong> ടിക്കറ്റ് സന്ദർഭം ഉപയോഗിച്ച് സ്വാഭാവിക ഭാഷയിൽ നോളജ് ബേസ് തിരയുന്നു.',
            'cleanup_heading' => '<strong>Reply Cleanup &mdash; റിപ്ലൈ എഡിറ്ററിലെ ✨ ബട്ടൺ</strong>',
            'cleanup_body' => 'ഒരു മറുപടിയിൽ പെട്ടെന്നൊരു പരുക്കൻ ഡ്രാഫ്റ്റ് ടൈപ്പ് ചെയ്യുക (അല്ലെങ്കിൽ *"need to restart the print service, take screenshot for them"* പോലുള്ള ബുള്ളറ്റ് പോയിന്റുകൾ മാത്രം) എന്നിട്ട് <strong>✨ Cleanup</strong> ബട്ടൺ ക്ലിക്ക് ചെയ്യുക. Claude ഇത് കൃത്യമായി ഫോർമാറ്റ് ചെയ്ത ഒരു ഇമെയിലായി വീണ്ടും എഴുതുന്നു &mdash; അഭ്യർത്ഥിച്ചയാളിൽ നിന്നുള്ള ഒരു <em>Dear [name],</em> ആശംസ ചേർക്കുന്നു, വ്യാകരണം ശരിയാക്കുന്നു, ക്രമീകരിച്ച ടോൺ പ്രയോഗിക്കുന്നു, <em>Kind regards,</em> എന്നതോടെ അവസാനിപ്പിക്കുന്നു. സാങ്കേതിക വിശദാംശങ്ങൾ കെട്ടിച്ചമയ്ക്കുകയോ, ക്ഷമാപണങ്ങൾ വ്യാജമായി ഉണ്ടാക്കുകയോ, നിങ്ങൾ എഴുതിയതിനപ്പുറം ഉള്ളടക്കം നിറയ്ക്കുകയോ ചെയ്യാതിരിക്കാൻ പ്രോംപ്റ്റ് ലോക്ക് ചെയ്തിരിക്കുന്നു.',
            'cleanup_streams' => '<strong>തത്സമയം സ്ട്രീം ചെയ്യുന്നു</strong> &mdash; Claude ഇത് സൃഷ്ടിക്കുമ്പോൾ തന്നെ വീണ്ടും എഴുതിയത് എഡിറ്ററിൽ പ്രത്യക്ഷപ്പെടുന്നു (ഒരു സ്പിന്നറിന് മുന്നിൽ കാത്തിരിക്കേണ്ട ആവശ്യമില്ല).',
            'cleanup_undo' => '<strong>30 സെക്കൻഡിന് Undo ലിങ്ക്</strong> &mdash; Claude വീണ്ടും എഴുതിയത് മോശമായാൽ, യഥാർത്ഥ ഡ്രാഫ്റ്റ് പുനഃസ്ഥാപിച്ചുകൊണ്ട്, വീണ്ടും എഴുത്ത് പൂർത്തിയായതിന് ശേഷം 30 സെക്കൻഡ് നേരത്തേക്ക് എഡിറ്ററിന് താഴെ ഒരു ചെറിയ <em>Undo</em> ലിങ്ക് പ്രത്യക്ഷപ്പെടും.',
            'cleanup_tone' => '<strong>ഓരോ ടോണിനും</strong> &mdash; <strong>Settings &rarr; Reply Cleanup</strong>-ന് കീഴിൽ ക്രമീകരിക്കാവുന്ന മൂന്ന് ടോൺ പ്രീസെറ്റുകൾ: <em>Friendly</em> (സ്ഥിരസ്ഥിതി), <em>Formal</em>, <em>Brief</em>. നിങ്ങളുടെ ടീമിന്റെ ശൈലിയോട് യോജിക്കുന്നത് തിരഞ്ഞെടുക്കുക.',
            'cleanup_key' => '<strong>സ്വന്തം API കീ</strong> &mdash; RFP / Knowledge / Workflow AI ഫീച്ചറുകളിൽ നിന്ന് വേറിട്ട Anthropic കീ, അതിനാൽ Anthropic ബില്ലിംഗ് ഡാഷ്‌ബോർഡിൽ ഇതിന്റെ ഉപയോഗം സ്വന്തം ലൈനായി കാണിക്കും. <strong>Settings &rarr; Reply Cleanup</strong>-ന് കീഴിൽ ക്രമീകരിക്കുന്നു.',
            'cleanup_tip' => 'പതിവായ "I tried this, please try X" ശൈലിയിലുള്ള മറുപടികൾക്ക് Cleanup ഏറ്റവും നന്നായി ഉപയോഗിക്കാം. നീണ്ടതും സൂക്ഷ്മതയുള്ളതുമായ സന്ദേശങ്ങൾക്ക് നിങ്ങൾ സ്വയം എഴുതുന്നതാണ് നല്ലത് &mdash; AI ഘടനയിൽ മികച്ചതാണ്, പക്ഷേ നിങ്ങളുടെ പ്രത്യേക പരിസ്ഥിതി അറിയില്ല.',
            'ask_heading' => '<strong>Ask AI &mdash; ടിക്കറ്റ് ടൂൾബാറിലെ 🤖 ബട്ടൺ</strong>',
            'ask_body' => 'തുറന്ന ടിക്കറ്റിന്റെ വിഷയം, ബോഡി, റീഡിംഗ്-പെയ്ൻ സന്ദർഭം എന്നിവയെക്കുറിച്ച് അറിയാവുന്ന ഒരു സ്ലൈഡ്-ഇൻ ചാറ്റ് പാനൽ തുറക്കാൻ ടിക്കറ്റ് ടൂൾബാറിലെ <strong>Ask AI</strong> ബട്ടൺ (🤖) ക്ലിക്ക് ചെയ്യുക. *"have we seen this before?"* അല്ലെങ്കിൽ *"what\'s the usual fix for this error?"* പോലുള്ള ചോദ്യങ്ങൾ ചോദിക്കുക, ഇത് (Claude + OpenAI embeddings വഴി) സെമാന്റിക് ആയി <a href="../knowledge/" style="color:#0078d4;">Knowledge</a> ബേസ് തിരയുകയും പ്രസക്തമായ ആർട്ടിക്കിളുകൾ, അവ തുറക്കാനുള്ള നേരിട്ടുള്ള ലിങ്കുകൾ സഹിതം മറുപടി നൽകുകയും ചെയ്യുന്നു.',
            'ask_context' => '<strong>സന്ദർഭം അറിയാവുന്നത്</strong> &mdash; നിങ്ങൾ ഏത് ടിക്കറ്റാണ് നോക്കുന്നതെന്ന് പാനലിന് അറിയാം, അതിനാൽ നിങ്ങൾക്ക് പൊതുവായ ചോദ്യങ്ങൾ ചോദിക്കാം, പ്രസക്തമായ സന്ദർഭം ഇത് കണ്ടെത്തും.',
            'ask_linked' => '<strong>ലിങ്ക് ചെയ്ത ആർട്ടിക്കിളുകൾ</strong> &mdash; നിർദ്ദേശങ്ങൾ ക്ലിക്ക് ചെയ്യാവുന്നതാണ്, ഒരു പുതിയ ടാബിൽ പൊരുത്തപ്പെടുന്ന നോളജ് ആർട്ടിക്കിൾ തുറക്കുന്നു.',
            'ask_shared' => '<strong>Knowledge മൊഡ്യൂളുമായി പങ്കിട്ടത്</strong> &mdash; Knowledge AI തിരയലിന്റെ അതേ കീയും മോഡലും AI ഉപയോഗിക്കുന്നു, അതിനാൽ ഒരിക്കൽ ക്രമീകരിക്കുന്നത് രണ്ടും നൽകുന്നു. സജ്ജീകരണ വിശദാംശങ്ങൾക്ക് Knowledge മൊഡ്യൂൾ സഹായം കാണുക.',
        ],
        'csat' => [
            'heading' => 'കസ്റ്റമർ സാറ്റിസ്ഫാക്ഷൻ സർവേകൾ (CSAT)',
            'intro' => 'ഒരു ടിക്കറ്റ് പരിഹരിക്കുമ്പോൾ അഭ്യർത്ഥിച്ചയാൾക്ക് 1&ndash;5 സാറ്റിസ്ഫാക്ഷൻ സർവേ ഇമെയിൽ ചെയ്യുക, ലോഗിൻ ആവശ്യമില്ലാത്ത ഒരു ലാൻഡിംഗ് പേജിൽ പ്രതികരണം പിടിച്ചെടുക്കുക, ഒരു പ്രത്യേക അനലിറ്റിക്സ് പേജിൽ അനലിസ്റ്റ്-തിരിച്ചുള്ള ട്രെൻഡുകൾ ട്രാക്ക് ചെയ്യുക.',
            'modes_heading' => '<strong>രണ്ട് ട്രിഗർ മോഡുകൾ &mdash; ഒന്ന് തിരഞ്ഞെടുക്കുക</strong>',
            'mode_auto' => '<strong>അടയ്ക്കുമ്പോൾ ഓട്ടോ</strong> &mdash; ഒരു ടിക്കറ്റ് ഏതെങ്കിലും അടച്ച നിലയിലേക്ക് മാറുമ്പോൾ സർവേ സ്വയമേവ ക്യൂ ചെയ്യപ്പെടുന്നു. അനലിസ്റ്റ് ഒന്നും ചെയ്യേണ്ടതില്ല &mdash; പരിഹാരമാണ് സർവേയെ നയിക്കുന്നത്.',
            'mode_manual' => '<strong>മാനുവൽ മാത്രം</strong> &mdash; ചോദിക്കാൻ ആഗ്രഹിക്കുമ്പോൾ അനലിസ്റ്റ് ടിക്കറ്റ് ടൂൾബാറിലെ ⭐ <strong>Feedback</strong> ബട്ടൺ ക്ലിക്ക് ചെയ്യുന്നു. ഫീഡ്ബാക്ക് ക്ഷണിക്കണോ എന്ന് ഓരോ ടിക്കറ്റിലും വെവ്വേറെ തീരുമാനിക്കാൻ ആഗ്രഹിക്കുമ്പോൾ ഉപയോഗപ്രദം.',
            'mode_off' => '<strong>ഓഫ്</strong> &mdash; ഫീച്ചർ പ്രവർത്തനരഹിതം; സർവേ ഇമെയിലുകൾ അയയ്ക്കില്ല.',
            'modes_choose' => '<strong>Tickets &rarr; Settings &rarr; CSAT</strong>-ന് കീഴിൽ തിരഞ്ഞെടുക്കുക. <em>auto</em> മോഡിലും മാനുവൽ ബട്ടൺ പ്രവർത്തിക്കുന്നു &mdash; ആവശ്യമെങ്കിൽ ഇതിനകം സർവേ ചെയ്ത ഒരു ടിക്കറ്റിൽ അനലിസ്റ്റുകൾക്ക് വീണ്ടും ഫീഡ്ബാക്ക് അഭ്യർത്ഥിക്കാം.',
            'template_heading' => '<strong>ഇമെയിൽ ടെംപ്ലേറ്റ്</strong>',
            'template_body' => 'സർവേ ഇമെയിൽ ഉള്ളടക്കം നിലവിലുള്ള <strong>Email templates</strong> ടാബിൽ നിന്നാണ് &mdash; <em>Ticket assigned</em> / <em>Ticket closed</em> എന്നിവയ്ക്കൊപ്പമുള്ള പുതിയ ഇവന്റായ <strong>CSAT survey</strong> ഇവന്റോടെ ഒരു ടെംപ്ലേറ്റ് സൃഷ്ടിക്കുക, റേറ്റിംഗ് URL പ്രത്യക്ഷപ്പെടേണ്ടിടത്ത് <code>[csat_link]</code> മെർജ് കോഡ് ഉൾപ്പെടുത്തുക. സ്റ്റാൻഡേർഡ് മെർജ് കോഡുകൾ (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) പതിവുപോലെ ലഭ്യമാണ്.',
            'template_tip' => 'സജീവമായ CSAT ടെംപ്ലേറ്റ് ഇല്ലെങ്കിൽ, <em>Feedback</em> ബട്ടൺ വ്യക്തമായ ഒരു പിശകോടെ നിരസിക്കുന്നു, ഓട്ടോ-ട്രിഗർ നിശബ്ദമായി ഒഴിവാക്കുന്നു &mdash; നിങ്ങൾക്ക് ഒരിക്കലും ചത്ത സർവേ ലിങ്കുകൾ ഉണ്ടാക്കാൻ കഴിയില്ല.',
            'survey_heading' => '<strong>സർവേ പേജ്</strong>',
            'survey_body' => 'അഭ്യർത്ഥിച്ചയാൾ ഇമെയിലിലെ ലിങ്കിൽ ക്ലിക്ക് ചെയ്ത്, ഒരു 1&ndash;5 പിക്കറും ഐച്ഛികമായ ഒരു കമന്റ് ബോക്സുമുള്ള ലോഗിൻ ആവശ്യമില്ലാത്ത ഒരു പേജിൽ എത്തുന്നു. <strong>Settings &rarr; CSAT</strong>-ന് കീഴിൽ ക്രമീകരിക്കാവുന്ന രണ്ട് വിഷ്വൽ ശൈലികൾ:',
            'survey_stars' => '<strong>Stars</strong> &mdash; ക്ലാസിക് ഫിൽ-ഓൺ-ഹോവർ ട്രെയിലിംഗ് സ്വഭാവം. #3 നക്ഷത്രത്തിൽ ഹോവർ ചെയ്താൽ #1+#2+#3 എന്നിവ സ്വർണ്ണ നിറത്തിൽ നിറയുന്നു. ലോക്ക് ചെയ്യാൻ ക്ലിക്ക് ചെയ്യുക.',
            'survey_emojis' => '<strong>Emojis</strong> &mdash; 5 മുഖങ്ങൾ 😡 🙁 😐 🙂 😀 40% ഒപ്പാസിറ്റിയിൽ ഗ്രേസ്കെയിൽ ആയി തുടങ്ങുന്നു; ഹോവർ ചെയ്തതോ തിരഞ്ഞെടുത്തതോ ആയത് 1.25&times; സ്കെയിലിൽ പൂർണ്ണ നിറത്തിലേക്ക് മടങ്ങുന്നു. ലോക്ക് ചെയ്യാൻ ക്ലിക്ക് ചെയ്യുക.',
            'survey_store' => 'ഏത് ശൈലിയാണ് ഉപയോഗത്തിലുള്ളതെങ്കിലും ഡാഷ്‌ബോർഡുകളും ശരാശരികളും ഒരേപോലെ പ്രവർത്തിക്കാൻ രണ്ട് മോഡുകളും അതേ 1&ndash;5 നമ്പർ സൂക്ഷിക്കുന്നു. സർവേ URL ഒറ്റത്തവണ മാത്രമാണ് &mdash; ഉപയോക്താവ് സമർപ്പിച്ചുകഴിഞ്ഞാൽ, അതേ ലിങ്ക് വീണ്ടും സമർപ്പിക്കുന്നത് നിരസിക്കുന്നു.',
            'analytics_heading' => '<strong>അനലിറ്റിക്സ് പേജ്</strong>',
            'analytics_body' => 'അനലിറ്റിക്സ് ഡാഷ്‌ബോർഡ് <code>tickets/csat/</code>-ൽ തുറക്കാൻ ⭐ <strong>CSAT</strong> നാവ് ബട്ടൺ (Rota, Settings എന്നിവയ്ക്കിടയിൽ) ക്ലിക്ക് ചെയ്യുക. തിരഞ്ഞെടുക്കാവുന്ന വിൻഡോ: 7 / 30 / 90 / 365 ദിവസങ്ങൾ.',
            'card_kpi_title' => 'KPI ടൈലുകൾ',
            'card_kpi_body' => 'ശരാശരി റേറ്റിംഗ് (5-ൽ), പ്രതികരണ എണ്ണം, പ്രതികരണ നിരക്ക് (പ്രതികരിച്ചത് ÷ അയച്ചത്)',
            'card_dist_title' => 'സ്കോർ വിതരണം',
            'card_dist_body' => 'കൃത്യമായ എണ്ണങ്ങളും ശതമാനങ്ങളും കാണിക്കുന്ന 1–5 റേറ്റിംഗുകളുടെ ബാർ ചാർട്ട്',
            'card_leader_title' => 'അനലിസ്റ്റ്-തിരിച്ചുള്ള ലീഡർബോർഡ്',
            'card_leader_body' => 'ഓരോ അനലിസ്റ്റിന്റെയും ശരാശരി റേറ്റിംഗ് + പ്രതികരണ എണ്ണം, ശരാശരി അനുസരിച്ച് അവരോഹണ ക്രമത്തിൽ. ഡെവലപ്മെന്റ് സംഭാഷണങ്ങൾക്ക് ഉപയോഗിക്കുക',
            'card_recent_title' => 'സമീപകാല പ്രതികരണങ്ങൾ',
            'card_recent_body' => 'ഏറ്റവും പുതിയ 25 റേറ്റിംഗുകൾ, അവയുടെ ഫ്രീ-ടെക്സ്റ്റ് കമന്റുകൾ സഹിതം, സോഴ്സ് ടിക്കറ്റിലേക്ക് തിരികെ ലിങ്ക് ചെയ്തത്',
            'analytics_tip' => 'അനലിസ്റ്റ് ഐഡി അയക്കുന്ന സമയത്ത് സർവേ വരിയിലേക്ക് പിടിച്ചെടുക്കുന്നതിനാൽ, തത്സമയം നോക്കിയെടുക്കുന്നതല്ലാത്തതിനാൽ, ടിക്കറ്റ് പുനർനിയോഗിച്ചാലും അനലിസ്റ്റ്-തിരിച്ചുള്ള ആട്രിബ്യൂഷൻ നിലനിൽക്കും. അടയ്ക്കുന്നതിന് മുമ്പ് ഒരു ടിക്കറ്റ് പലരിലേക്കും കൈമാറ്റം ചെയ്യപ്പെട്ടാൽ, യഥാർത്ഥത്തിൽ അത് അടച്ച അനലിസ്റ്റിനാണ് റേറ്റിംഗിന്റെ ഉടമസ്ഥാവകാശം.',
            'one_heading' => '<strong>ഓരോ ടിക്കറ്റിനും ഒരു സർവേ</strong>',
            'one_body' => '<em>One survey per ticket</em> ഓണാണെങ്കിൽ (സ്ഥിരസ്ഥിതി), വീണ്ടും തുറന്ന് പിന്നെ അടച്ച ഒരു ടിക്കറ്റിന് ഒരു അനലിസ്റ്റ് സ്വമേധയാ ട്രിഗർ ചെയ്യുമ്പോൾ മാത്രമേ മറ്റൊരു സർവേ ലഭിക്കൂ &mdash; ആവർത്തിച്ച് സൈക്കിൾ ചെയ്യുന്ന ഒരു അസ്ഥിരമായ ടിക്കറ്റിനെ സർവേ-സ്പാം ചെയ്യുന്നത് ഇത് തടയുന്നു. ഓരോ അടയ്ക്കലും ഒരു പുതിയ സർവേ ട്രിഗർ ചെയ്യണമെങ്കിൽ ഇത് ഓഫ് ചെയ്യുക.',
        ],
        'users' => [
            'heading' => 'ഉപയോക്തൃ മാനേജ്മെന്റ്',
            'intro' => '<strong>Users</strong> നാവ് ബട്ടൺ <code>tickets/users.php</code> തുറക്കുന്നു &mdash; ഓരോ എൻഡ് യൂസറിന്റെയും (ടിക്കറ്റ് ഉയർത്തുന്ന ആളുകൾ, അനലിസ്റ്റുകളല്ല) ഒരു ഡയറക്ടറി, അവരവരുടെ ടിക്കറ്റ് ചരിത്രത്തോടൊപ്പം.',
            'p_intro' => 'നാല് പ്രതികരണാത്മക വഴികളിലൂടെയാണ് ഉപയോക്താക്കൾ സിസ്റ്റത്തിൽ എത്തുന്നത് &mdash; പോർട്ടൽ സ്വയം-രജിസ്ട്രേഷൻ, ഒരു പുതിയ അയച്ചയാളിൽ നിന്നുള്ള ഇൻബൗണ്ട് ഇമെയിൽ, മെയിൽബോക്സ് പോളർ, അല്ലെങ്കിൽ ട്രിഗർ ചെയ്ത ഒരു ടിക്കറ്റിൽ നിന്ന് വർക്ക്ഫ്ലോ എഞ്ചിൻ ഒരാളെ സൃഷ്ടിക്കൽ. ഇത് മിക്ക കേസുകളും ഉൾക്കൊള്ളുന്നു, പക്ഷേ Users പേജ് ഒരു ഉപയോക്താവിനെ <strong>മുൻകൂട്ടി സൃഷ്ടിക്കാനും</strong> (ഉദാ. ആക്സസ് വേണ്ടിവരാൻ പോകുന്ന ഒരു പുതിയ ജീവനക്കാരൻ) നിലവിലുള്ള വരികൾ <strong>എഡിറ്റ് ചെയ്യാനോ</strong> <strong>ഇല്ലാതാക്കാനോ</strong> നിങ്ങളെ അനുവദിക്കുന്നു.',
            'add_heading' => '<strong>ഉപയോക്താവിനെ ചേർക്കുക</strong>',
            'add_body' => 'ഉപയോക്തൃ-ലിസ്റ്റ് ഹെഡറിലെ <strong>Add</strong> ബട്ടൺ ഒരു മോഡൽ തുറക്കുന്നു:',
            'add_email' => '<strong>Email</strong> (ആവശ്യമാണ്) &mdash; അതുല്യമായിരിക്കണം, ഒരു അനലിസ്റ്റ് അക്കൗണ്ടുമായി പൊരുത്തപ്പെടാൻ പാടില്ല.',
            'add_names' => '<strong>Display name / preferred name</strong> &mdash; ഐച്ഛികം. ഇമെയിലുകളിൽ തന്നെ എങ്ങനെ അഭിവാദ്യം ചെയ്യുന്നു എന്ന് ഉപയോക്താവ് കാണുന്നത് preferred name ആണ് (ഉദാ. <em>"Ed Mozley"</em>-ക്ക് പകരം <em>"Ed"</em>).',
            'add_password' => '<strong>Password</strong> &mdash; ഐച്ഛികം. ശൂന്യമായി വിടുന്നത് ഒരു <em>പാസ്‌വേഡില്ലാത്ത</em> അക്കൗണ്ട് സൃഷ്ടിക്കുന്നു &mdash; ഇൻബൗണ്ട്-ടിക്കറ്റ് ഉപയോക്താക്കൾ തുടങ്ങുന്ന അതേ അവസ്ഥ തന്നെ. സ്വന്തം പാസ്‌വേഡ് സജ്ജമാക്കി സെൽഫ്-സർവീസ് പോർട്ടലിന്റെ register ഫ്ലോ വഴി ഉപയോക്താവിന് പിന്നീട് അക്കൗണ്ട് ക്ലെയിം ചെയ്യാം.',
            'add_details' => '<strong>Job title, department, office, phone, mobile, employee ID and manager</strong> &mdash; എല്ലാം ഐച്ഛികം, ലോഗിനല്ല <em>വ്യക്തിയെ</em> ആണ് എല്ലാം വിവരിക്കുന്നത്. നിറയ്ക്കുന്നത് വിലപ്പെട്ടതാണ്: ആരെയെങ്കിലും തിരയാൻ പോകുന്നതിന് മുമ്പ് ഏത് സൈറ്റിലാണ് അവരെന്ന് <strong>office</strong> നിങ്ങളോട് പറയുന്നു, <strong>manager</strong> റിപ്പോർട്ടിംഗ് ലൈൻ രേഖപ്പെടുത്തുന്നു, ഒരു ഇമെയിൽ വിലാസത്തെക്കുറിച്ച് ഒരിക്കലും കേട്ടിട്ടില്ലാത്ത ഒരു പേറോൾ സിസ്റ്റവുമായി പൊരുത്തപ്പെടുത്തുമ്പോൾ <strong>employee ID</strong> ജോയിൻ കീയാണ്. ഒരു ഡയറക്ടറിയിൽ നിന്ന് ഇംപോർട്ട് ചെയ്യുമ്പോൾ, ഇവയെല്ലാം നിറഞ്ഞാണ് വരുന്നത്. ഒരു CardDAV അഡ്രസ് ബുക്ക് employee ID, manager എന്നിവ ഒഴികെ എല്ലാം നിറയ്ക്കുന്നു, ഒരു കോൺടാക്റ്റ് കാർഡിന് അവ സൂക്ഷിക്കാൻ ഇടമില്ലാത്തതിനാൽ.',
            'managed_heading' => '<strong>മറ്റെവിടെയോ പരിപാലിക്കുന്ന ആളുകൾ</strong>',
            'source_body' => '<strong>ഒരു വ്യക്തി എവിടെ നിന്ന് വരുന്നു</strong> എന്നത് അവരുടെ വിശദാംശങ്ങളിൽ പേരിട്ടിരിക്കുന്നു (<em>Details from: Contoso AD - directory</em>), സെർച്ച് ബോക്സിന് കീഴിലുള്ള <strong>Source</strong> ഫിൽട്ടർ ഒരു ഡയറക്ടറിയിൽ നിന്നോ അഡ്രസ് ബുക്കിൽ നിന്നോ ഉള്ള ആളുകളെ മാത്രമോ, അല്ലെങ്കിൽ FreeITSM-ൽ ചേർത്തവരെ മാത്രമോ, ഓരോന്നിനും അരികിൽ ഒരു എണ്ണത്തോടെ ലിസ്റ്റ് ചെയ്യുന്നു. ആരെങ്കിലും ഒരു സോഴ്സുമായി ലിങ്ക് ചെയ്തുകഴിഞ്ഞാൽ ഇത് പ്രത്യക്ഷപ്പെടും.',
            'add_book_body' => '<strong>Add to address book.</strong> ഇമെയിൽ ചെയ്ത ഒരാൾ ഇവിടെ നിലവിലുണ്ട്, പക്ഷേ ഒരു അഡ്രസ് ബുക്കിലും ഇല്ല. ഒരു അഡ്മിനിസ്ട്രേറ്റർ <em>Let analysts add people to this address book</em> (System &rarr; Authentication, അഡ്രസ് ബുക്കിൽ) ഓണാക്കിയിട്ടുണ്ടെങ്കിൽ, ആ വ്യക്തിക്ക് Edit-ന് അരികിൽ ഒരു <strong>Add to address book</strong> ബട്ടൺ ലഭിക്കും. ഇത് ആദ്യം ചോദിക്കുന്നു, കാർഡിൽ എന്ത് പോകുമെന്ന് കാണിച്ചുകൊണ്ട്, എന്നിട്ട് അവരുടെ കോൺടാക്റ്റ് സൃഷ്ടിച്ച് ലിങ്ക് ചെയ്യുന്നു &mdash; അതേ വ്യക്തി, ഒരു പകർപ്പല്ല. ബുക്കിൽ ഇതിനകം ഇമെയിൽ വിലാസമുള്ള ആരെയും ഇത് ചേർക്കില്ല (പകരം ഇംപോർട്ട് പ്രവർത്തിപ്പിക്കുക), അടുത്ത ഇംപോർട്ട് പുതിയ കോൺടാക്റ്റിനെ എടുക്കുമെന്ന് ഇത് ഉറപ്പാക്കുന്നു, അല്ലെങ്കിൽ കാർഡ് തിരികെ എടുക്കുന്നു.',
            'managed_body' => 'LDAP അല്ലെങ്കിൽ Active Directory-യിൽ നിന്ന്, അല്ലെങ്കിൽ ഒരു CardDAV അഡ്രസ് ബുക്കിൽ നിന്ന് ഒരു വ്യക്തിയെ ഇംപോർട്ട് ചെയ്തിടത്ത് &mdash; ആ സോഴ്സ് സ്വന്തമാക്കുന്ന വിശദാംശങ്ങൾ <strong>റീഡ്-ഒൺലി</strong> ആണ്, മോഡൽ അവയെ ചാരനിറത്തിലാക്കുന്നു. അവ എവിടെ നിന്നാണോ വന്നത് അതാണ് സത്യത്തിന്റെ ഉറവിടം, അടുത്ത ഇംപോർട്ട് ഇവിടെ ടൈപ്പ് ചെയ്ത എന്തും ഓവർറൈറ്റ് ചെയ്യും, അതിനാൽ സേവ് സ്വീകരിച്ച് ഒരു മണിക്കൂർ കഴിഞ്ഞ് നിശബ്ദമായി തിരികെ മാറ്റുന്നതിന് പകരം അത് നേരിട്ട് നിരസിക്കപ്പെടുന്നു. <strong>ഏത്</strong> വിശദാംശങ്ങൾ എന്നത് സോഴ്സിനെ ആശ്രയിച്ചിരിക്കുന്നു: ഒരു ഡയറക്ടറി എല്ലാ ഏഴും സ്വന്തമാക്കുന്നു, ഒരു അഡ്രസ് ബുക്ക് അഞ്ചെണ്ണം സ്വന്തമാക്കുന്നു &mdash; ഒരു employee number-ഓ reporting line-ഓ സൂക്ഷിക്കാൻ അതിന് ഇടമില്ല, അതിനാൽ ആ രണ്ടെണ്ണം നിറയ്ക്കാൻ നിങ്ങൾക്ക് വിടുന്നു. അഡ്രസ് ബുക്കിന് <em>write changes back</em> ഓണാണെങ്കിൽ, അവയൊന്നും ലോക്ക് ചെയ്തിട്ടില്ല: നിങ്ങൾ ടൈപ്പ് ചെയ്യുന്നത് കോൺടാക്റ്റ് കാർഡിലേക്ക് അയയ്ക്കുന്നു, അതിനാൽ അടുത്ത ഇംപോർട്ടിന് തിരികെ മാറ്റാൻ ഒന്നുമില്ല. റെക്കോർഡിലെ മറ്റെല്ലാം, അവരുടെ കമ്പനിയും പാസ്‌വേഡും ഉൾപ്പെടെ, എപ്പോഴും എഡിറ്റ് ചെയ്യാവുന്നതാണ്.',
            'edit_heading' => '<strong>ഉപയോക്താവിനെ എഡിറ്റ് ചെയ്യുക</strong>',
            'edit_body' => 'ലിസ്റ്റിൽ നിന്ന് ഒരു ഉപയോക്താവിനെ തിരഞ്ഞെടുത്ത്, ഡീറ്റെയ്ൽ ഹെഡറിൽ <strong>Edit</strong> ക്ലിക്ക് ചെയ്യുക. അതേ മോഡൽ, മുൻകൂട്ടി നിറച്ചത്. പാസ്‌വേഡില്ലാതെ സേവ് ചെയ്യുന്നത് നിലവിലെ ഹാഷ് തൊടാതെ വിടുന്നു; ഒന്ന് നൽകുന്നത് അത് റീസെറ്റ് ചെയ്യുന്നു.',
            'delete_heading' => '<strong>ഉപയോക്താവിനെ ഇല്ലാതാക്കുക</strong>',
            'delete_body' => '<strong>Delete</strong> ബട്ടൺ <strong>FK-സേഫ്</strong> ആണ്: ഉപയോക്താവ് ഏതെങ്കിലും ടിക്കറ്റുകളിൽ അഭ്യർത്ഥിച്ചയാളാണെങ്കിലോ <code>users_assets</code>-ൽ എന്തെങ്കിലും വരികളുണ്ടെങ്കിലോ ഇത് നിരസിക്കുന്നു, വ്യക്തമായ <em>"Cannot delete: this user is the requester on N ticket(s). Reassign or close those tickets first."</em> സന്ദേശം നൽകിക്കൊണ്ട്. ഓഡിറ്റ് ചരിത്രത്തിന് ഒരിക്കലും നിശബ്ദമായി തകരാൻ കഴിയില്ല.',
            'tip' => 'എല്ലാ മോഡൽ ഫീൽഡുകൾക്കും ബ്രൗസർ ഓട്ടോഫിൽ പ്രവർത്തനരഹിതമാണ് (പാസ്‌വേഡ് ഫീൽഡിൽ <code>autocomplete="new-password"</code> ഉൾപ്പെടെ), അതിനാൽ <em>മറ്റൊരാളുടെ</em> റെക്കോർഡ് സൃഷ്ടിക്കുക എന്നതാണ് മുഴുവൻ ഉദ്ദേശ്യമുള്ള ഒരു ഫോമിലേക്ക് അനലിസ്റ്റിന്റെ സ്വന്തം സേവ് ചെയ്ത ക്രെഡൻഷ്യലുകൾ നിർദ്ദേശിക്കപ്പെടില്ല.',
            'groups_heading' => '<strong>ഗ്രൂപ്പുകൾ</strong>',
            'groups_body' => '<strong>People</strong>-ക്ക് അരികിലുള്ള <strong>Groups</strong> ടാബ് പേരുള്ള ആളുകളുടെ ഗ്രൂപ്പുകൾ സൂക്ഷിക്കുന്നു &mdash; അനലിസ്റ്റുകളും സെൽഫ്-സർവീസ് പോർട്ടൽ ഉപയോക്താക്കളും ഒരേ ഗ്രൂപ്പിൽ ഒരുമിച്ച്. ഒരു ഗ്രൂപ്പ് ഇവിടെ ഒരിക്കൽ ഉണ്ടാക്കി പിന്നീട് FreeITSM-ൽ ഉടനീളം ഉപയോഗിക്കുന്നു, അതിനാൽ ഒരേ ലിസ്റ്റ് രണ്ടുതവണ ഉണ്ടാക്കാതെ തന്നെ ഒരു നോളജ് ഫോൾഡറിലേക്ക് ആക്സസ് നൽകാനോ ഒരു ട്രെയിനിംഗ് കോഴ്സ് നൽകാനോ കഴിയും.',
            'groups_make' => 'Groups ടാബിലെ <strong>Add</strong> ഉപയോഗിച്ച് <strong>ഒന്ന് ഉണ്ടാക്കുക</strong>: ഒരു പേര്, നിറയ്ക്കാൻ വിലപ്പെട്ട ഒരു വിവരണം, കാരണം ഗ്രൂപ്പ് എന്തിനുള്ളതാണെന്ന് അടുത്ത വ്യക്തിക്ക് പറയാൻ കഴിയേണ്ടതുണ്ട്.',
            'groups_add' => 'അവരെ തിരഞ്ഞ് <strong>ആളുകളെ ചേർക്കുക</strong> &mdash; ഇത് അനലിസ്റ്റുകളെയും പോർട്ടൽ ഉപയോക്താക്കളെയും ഒരുമിച്ച് കണ്ടെത്തുന്നു, അതിനാൽ ആരെങ്കിലും ഏത് തരമാണെന്ന് നിങ്ങൾ അറിയേണ്ടതില്ല.',
            'groups_expiry' => 'ആക്സസ് താൽക്കാലികമായ ഇടത്ത് <strong>അംഗത്വത്തിന് ഒരു അവസാന തീയതി നൽകുക</strong>. രണ്ടാഴ്ചത്തേക്ക് സൈറ്റിലുള്ള മൂന്ന് എഞ്ചിനീയർമാർ ഒരു അവസാന ദിവസത്തോടെ ചേരുകയും അത് കഴിയുമ്പോൾ സ്വയം ഗ്രൂപ്പിൽ നിന്ന് പുറത്താകുകയും ചെയ്യുന്നു. കാലഹരണപ്പെട്ട ഒരു അംഗത്വം ലിസ്റ്റിൽ തുടരും, കാലഹരണപ്പെട്ടതായി അടയാളപ്പെടുത്തിയത്, അതിനാൽ ആർക്കൊക്കെ എപ്പോൾ വരെ ആക്സസ് ഉണ്ടായിരുന്നു എന്ന് നിങ്ങൾക്ക് ഇപ്പോഴും കാണാം.',
            'groups_uses' => '<strong>ഒരു ഗ്രൂപ്പ് എന്തിന് നല്ലതാണ്:</strong> ഒരു നോളജ് ഫോൾഡറിലേക്ക് ആക്സസ് നൽകൽ, ഒരു കൂട്ടം ആളുകൾക്ക് ഒരുമിച്ച് LMS ട്രെയിനിംഗ് നൽകൽ. അംഗത്വ മാറ്റങ്ങൾ ഉടനടി പ്രാബല്യത്തിൽ വരും &mdash; പിന്നീട് വീണ്ടും പ്രയോഗിക്കാൻ ഒന്നുമില്ല.',
            'groups_admin' => '<strong>ടിക്കറ്റുകൾ മൊഡ്യൂൾ ഉള്ള ആർക്കും ഗ്രൂപ്പുകൾ കാണാം; ഒരു അഡ്മിനിസ്ട്രേറ്റർക്ക് മാത്രമേ ഒന്ന് മാറ്റാൻ കഴിയൂ.</strong> ഒരു ഗ്രൂപ്പിലേക്ക് ആരെയെങ്കിലും ചേർക്കുന്നത് നിയന്ത്രിതമായ ഒരു നോളജ് ഫോൾഡറിലേക്കുള്ള ആക്സസും അവർക്ക് നൽകാം, അതിനാൽ ഇത് ഫയലിംഗിന്റെ ഒരു ഭാഗമല്ല, ആക്സസിന്റെ ഒരു ഗ്രാന്റാണ്.',
        ],
        'dash' => [
            'heading' => 'ഡാഷ്‌ബോർഡ്',
            'intro' => 'ടിക്കറ്റ് ഡാഷ്‌ബോർഡ് ഇഷ്ടാനുസൃതമാക്കാവുന്ന Chart.js വിജറ്റുകൾ ഉപയോഗിച്ച് ഒറ്റനോട്ടത്തിൽ അനലിറ്റിക്സ് നൽകുന്നു. ഓരോ അനലിസ്റ്റിനും അവരവരുടെ സ്വന്തം ഡാഷ്‌ബോർഡ് ലേഔട്ട് ഉണ്ട്, അതിനാൽ നിങ്ങളുടെ റോളിന് പ്രധാനപ്പെട്ട മെട്രിക്സിൽ നിങ്ങൾക്ക് ശ്രദ്ധ കേന്ദ്രീകരിക്കാം &mdash; അത് വ്യക്തിഗത വർക്ക്‌ലോഡോ, ടീം ത്രൂപുട്ടോ, SLA കംപ്ലയൻസോ ആകട്ടെ.',
            'step1' => '<strong>ലൈബ്രറി തുറക്കുക</strong> &mdash; എഡിറ്റിംഗ് മോഡിലേക്ക് പ്രവേശിക്കാൻ Edit Dashboard ക്ലിക്ക് ചെയ്യുക, എന്നിട്ട് വിജറ്റ് ലൈബ്രറി ബ്രൗസ് ചെയ്യുക. മുൻകൂട്ടി നിർമ്മിച്ച വിജറ്റുകളിൽ നിന്ന് തിരഞ്ഞെടുക്കുക അല്ലെങ്കിൽ ഒരു ചാർട്ട് തരവും അഗ്രിഗേറ്റ് ചെയ്യാനുള്ള ഡാറ്റ പ്രോപ്പർട്ടിയും തിരഞ്ഞെടുത്ത് സ്വന്തമായത് സൃഷ്ടിക്കുക.',
            'step2' => '<strong>വിജറ്റുകൾ ചേർക്കുക</strong> &mdash; ലൈബ്രറിയിലെ ഏതെങ്കിലും വിജറ്റിന്റെ + ബട്ടൺ ക്ലിക്ക് ചെയ്ത് നിങ്ങളുടെ ഡാഷ്‌ബോർഡിലേക്ക് ചേർക്കുക. ഇത് ഉടനടി പ്രത്യക്ഷപ്പെടുകയും നിങ്ങളുടെ ടിക്കറ്റ് ഡാറ്റാബേസിൽ നിന്ന് തത്സമയ ഡാറ്റ പ്രദർശിപ്പിക്കാൻ തുടങ്ങുകയും ചെയ്യുന്നു.',
            'step3' => '<strong>Configure</strong> &mdash; ഏതെങ്കിലും വിജറ്റിന്റെ കോഗ് ഐക്കൺ ക്ലിക്ക് ചെയ്ത് അതിന്റെ ടൈറ്റിൽ, ചാർട്ട് തരം (bar, pie, doughnut, line, stacked bar, multi-line), ഡേറ്റ് റേഞ്ച് ഫിൽട്ടർ, ഡിപ്പാർട്ട്മെന്റ് ഫിൽട്ടർ, ടൈം ഗ്രൂപ്പിംഗ് (ദൈനംദിനം, പ്രതിവാരം, പ്രതിമാസം) എന്നിവ ഇഷ്ടാനുസൃതമാക്കുക.',
            'step4' => '<strong>Arrange</strong> &mdash; വിജറ്റുകൾ വീണ്ടും ക്രമീകരിക്കാൻ ഡ്രാഗ് ചെയ്ത് ഡ്രോപ്പ് ചെയ്യുക. നിങ്ങളുടെ ലേഔട്ട് ഓരോ അനലിസ്റ്റിനും പ്രത്യേകം സേവ് ചെയ്യുന്നു, അതിനാൽ സെഷനുകളിലുടനീളം അത് നിലനിൽക്കും.',
            'examples' => 'സാധാരണ വിജറ്റ് ഉദാഹരണങ്ങളിൽ ഇവ ഉൾപ്പെടുന്നു: <strong>Tickets by Status</strong> (open vs resolved vs closed കാണിക്കുന്ന ഡോനട്ട് ചാർട്ട്), <strong>Tickets by Priority</strong> (തീവ്രത അനുസരിച്ചുള്ള വോള്യത്തിന്റെ ബാർ ചാർട്ട്), <strong>Weekly Volume</strong> (കാലക്രമേണ പുതിയ ടിക്കറ്റുകൾ ട്രാക്ക് ചെയ്യുന്ന ലൈൻ ചാർട്ട്), <strong>Analyst Workload</strong> (ഓരോ അനലിസ്റ്റിന്റെയും സജീവ ടിക്കറ്റുകൾ കാണിക്കുന്ന സ്റ്റാക്ക്ഡ് ബാർ).',
            'tip' => 'ഇപ്പോഴത്തെ പ്രകടനം മുൻകാല കാലയളവുകളുമായി താരതമ്യം ചെയ്യാൻ വ്യക്തിഗത വിജറ്റുകളിൽ ഡേറ്റ് റേഞ്ച് ഫിൽട്ടറുകൾ ഉപയോഗിക്കുക. ഉദാഹരണത്തിന്, ഒരു "This Month vs Last Month" വ്യൂ ടിക്കറ്റ് വോള്യത്തിലെ ട്രെൻഡുകൾ നേരത്തെ കണ്ടെത്താൻ നിങ്ങളെ സഹായിക്കുന്നു.',
        ],
        'cal_rota' => [
            'heading' => 'കലണ്ടർ &amp; റോട്ട',
            'intro' => 'രണ്ട് ഷെഡ്യൂളിംഗ് ടൂളുകൾ നിങ്ങളുടെ ടീമിനെ ചിട്ടയോടെ നിലനിർത്താൻ സഹായിക്കുന്നു: കാലക്രമേണയുള്ള ജോലിഭാരം ദൃശ്യവൽക്കരിക്കുന്ന ഒരു ടിക്കറ്റ് കലണ്ടർ, ഷിഫ്റ്റുകളും ഓൺ-കോൾ ലഭ്യതയും കൈകാര്യം ചെയ്യാനുള്ള ഒരു സ്റ്റാഫ് റോട്ട.',
            'cal_heading' => '<strong>കലണ്ടർ കാഴ്ച</strong>',
            'cal_body' => 'നിങ്ങൾ ഷെഡ്യൂൾ ചെയ്ത എല്ലാ ടിക്കറ്റുകളും കലണ്ടർ പ്ലോട്ട് ചെയ്യുന്നു &mdash; ടിക്കറ്റിൽ തന്നെയും ഇൻബോക്സ് റൈറ്റ്-ക്ലിക്ക് മെനുവിലും ഉള്ള <strong>ജോലി ഷെഡ്യൂൾ ചെയ്യുക</strong> വഴി &mdash; അതിന്റെ ഷെഡ്യൂൾ ചെയ്ത സമയത്ത് ഒരു നിറമുള്ള ബ്ലോക്കായി, ഒരു നിശ്ചിത മണിക്കൂറിനു പകരം അതിന്റെ <strong>യഥാർത്ഥ ദൈർഘ്യത്തിൽ</strong> വരയ്ക്കുന്നു. ചുവന്ന ബ്ലോക്കുകൾ <em>ഉയർന്ന</em> മുൻഗണനയാണ്, പച്ചയാണ് <em>കുറവ്</em>, ബാക്കിയെല്ലാം നീലയാണ്. നാവിഗേറ്റ് ചെയ്യാൻ <em>ഇന്ന്</em>, <em>&lt;</em> / <em>&gt;</em> ഷെവ്റോണുകൾ, <strong>മാസം / ആഴ്ച / ദിവസം</strong> ടോഗിൾ എന്നിവ ഉപയോഗിക്കുക.',
            'cal_scope' => '<strong>എന്റേത് അല്ലെങ്കിൽ എല്ലാവരും.</strong> കലണ്ടർ നിങ്ങളുടെ സ്വന്തം ഷെഡ്യൂൾ ചെയ്ത ജോലിയിലാണ് തുറക്കുന്നത്, കാഴ്ച ബട്ടണുകൾക്ക് അരികിൽ ഒരു <strong>എല്ലാവരും</strong> സ്വിച്ച് ഉണ്ട്; നിങ്ങളുടെ തിരഞ്ഞെടുപ്പ് ഓർമ്മിക്കപ്പെടും. എല്ലാവരും എന്ന കാഴ്ചയിൽ ഓരോ ടിക്കറ്റും അത് ആരുടേതാണോ അയാൾക്കുള്ള <strong>ഒരു നിറം</strong> വഹിക്കുന്നു, സ്ക്രീനിൽ യഥാർത്ഥത്തിൽ ഉള്ളവരുടെ പേരുകൾ നൽകുന്ന ഒരു ലെജൻഡോടെ, ഒരു ടിക്കറ്റിന് മുകളിൽ ഹോവർ ചെയ്യുന്നത് നോക്കിനിൽക്കാതെ അത് ആരുടേതെന്ന് പറയും. ആരിൽ നിന്നും ഒന്നും മറച്ചുവച്ചിട്ടില്ല &mdash; ഇവ ഇൻബോക്സ് ഇതിനകം ലിസ്റ്റ് ചെയ്യുന്ന അതേ ടിക്കറ്റുകളാണ്.',
            'cal_edit' => '<strong>ജോലി പുനഃക്രമീകരിക്കൽ.</strong> ഒരു <strong>ടിക്കറ്റ് വലിച്ചിടുക</strong> മറ്റൊരു ദിവസത്തിലേക്കോ സമയത്തിലേക്കോ: മാസം കാഴ്ചയിൽ അത് അതിന്റെ സമയം സൂക്ഷിക്കുന്നു, ആഴ്ച, ദിവസം കാഴ്ചകളിൽ നിങ്ങൾ ഇടുന്ന സമയം അത് സ്വീകരിക്കുന്നു, ഏറ്റവും അടുത്ത കാൽ മണിക്കൂറിലേക്ക് സ്നാപ്പ് ചെയ്യും. അതിന്റെ ദൈർഘ്യം ഒരിക്കലും മാറില്ല &mdash; വലിച്ചിടുന്നത് <em>അത് അപ്പോൾ തുടങ്ങുക</em> എന്നാണ് അർത്ഥമാക്കുന്നത്, <em>അത് കൂടുതൽ ദൈർഘ്യമുള്ളതാക്കുക</em> എന്നല്ല. അല്ലെങ്കിൽ <strong>ഒരു ടിക്കറ്റ് ക്ലിക്ക് ചെയ്യുക</strong> അത് തുറക്കാൻ, അവിടെ നിങ്ങൾക്ക് തീയതി, സമയം, ദൈർഘ്യം, മുഴുവൻ ദിവസത്തെ ക്രമീകരണം എന്നിവ മാറ്റാം, അല്ലെങ്കിൽ ഷെഡ്യൂൾ പൂർണ്ണമായും മായ്ക്കാം. കലണ്ടർ ഓരോ കുറച്ച് സെക്കൻഡിലും <strong>സ്വയം പുതുക്കുകയും</strong> ചെയ്യുന്നു, അതിനാൽ ഒരു സഹപ്രവർത്തകൻ എന്തെങ്കിലും ഷെഡ്യൂൾ ചെയ്താൽ നിങ്ങൾ റീലോഡ് ചെയ്യാതെ തന്നെ അത് പ്രത്യക്ഷപ്പെടും &mdash; നിങ്ങൾക്ക് ഒരു ടിക്കറ്റ് തുറന്നിരിക്കുമ്പോളോ വലിച്ചിടുന്നതിനിടയിലോ ഇത് നിർത്തിവയ്ക്കും.',
            'cal_month' => '<strong>മാസം കാഴ്ച</strong> &mdash; ആഴ്ചദിന ഹെഡർ സ്ട്രിപ്പുള്ള ക്ലാസിക് 6-വരി ഗ്രിഡ്; ഓരോ ദിവസത്തെ സെല്ലും അതിന്റെ ആരംഭ സമയത്തോടെ മൂന്ന് ടിക്കറ്റ് പിൽ വരെ കാണിക്കുന്നു, കൂടാതെ ആ തീയതിക്കുള്ള ദിവസം കാഴ്ചയിലേക്ക് നിങ്ങളെ കൊണ്ടുപോകുന്ന ഒരു <em>+N കൂടുതൽ</em> ലിങ്കും. ഇന്ന് ഹൈലൈറ്റ് ചെയ്തിരിക്കുന്നു.',
            'cal_week' => '<strong>ആഴ്ച കാഴ്ച</strong> &mdash; 24 മണിക്കൂർ വെർട്ടിക്കൽ ടൈംലൈനിന് മുകളിൽ തിങ്കൾ&ndash;ഞായർ. ടിക്കറ്റുകൾ അവയുടെ ഷെഡ്യൂൾ ചെയ്ത ദൈർഘ്യത്തിൽ ദൃശ്യമാകുന്നു, അതിനാൽ 15 മിനിറ്റ് ജോലിയും ഒരു ഉച്ചയ്ക്ക് ശേഷമുള്ള റീബിൽഡും വ്യത്യസ്തമായി കാണപ്പെടും. മുഴുവൻ ദിവസത്തെയും ടിക്കറ്റ് ആ ദിവസത്തിന്റെ കോളം മുഴുവൻ വിഴുങ്ങുന്നതിന് പകരം അതിന്റെ മുകളിൽ ഒരു നേർത്ത ബാർ ആയി ഇരിക്കുന്നു. ഇന്നത്തെ കോളം ഹൈലൈറ്റ് ചെയ്തിരിക്കുന്നു; മണിക്കൂർ ഗ്രിഡ് സ്ക്രോൾ ചെയ്യുമ്പോൾ ആഴ്ചദിന ഹെഡർ അതേ സ്ഥാനത്ത് നിൽക്കും.',
            'cal_day' => '<strong>ദിവസം കാഴ്ച</strong> &mdash; തിരഞ്ഞെടുത്ത ദിവസത്തിനായി അതേ 24 മണിക്കൂർ ടൈംലൈനുള്ള ഒരു ഒറ്റ ഉയരമുള്ള കോളം. ടിക്കറ്റുകൾ <code>ticket_number &mdash; subject</code>-ഉം ആരംഭ സമയവും കാണിക്കുന്ന വലിയ ബ്ലോക്കുകളായി ദൃശ്യമാകുന്നു; അതിന്റെ വിശദാംശങ്ങൾ തുറക്കാനോ അത് എപ്പോൾ സംഭവിക്കുന്നു എന്ന് മാറ്റാനോ ഒന്നിൽ ക്ലിക്ക് ചെയ്യുക.',
            'rota_heading' => '<strong>സ്റ്റാഫ് റോട്ട</strong>',
            'rota_body' => 'ടീം ലീഡുകൾക്കും മാനേജർമാർക്കും ആഴ്ചയിലുടനീളം അനലിസ്റ്റ് ഷിഫ്റ്റുകൾ ഷെഡ്യൂൾ ചെയ്യാൻ റോട്ട പേജ് അനുവദിക്കുന്നു. സ്റ്റാൻഡേർഡ് ജോലി സമയങ്ങൾ നിർവചിക്കുക, ഓൺ-കോൾ കാലയളവുകൾ അസൈൻ ചെയ്യുക, അവധികളോ അഭാവമോ അടയാളപ്പെടുത്തുക, അതിലൂടെ ആരൊക്കെ ലഭ്യമാണെന്ന് ടീമിന് എപ്പോഴും അറിയാം.',
            'rota_step1' => '<strong>റോട്ട ഗ്രിഡ് കാണുക</strong> &mdash; ഒരു അക്ഷത്തിൽ അനലിസ്റ്റുകളും മറ്റൊന്നിൽ ദിവസങ്ങളും റോട്ട കാണിക്കുന്നു, ഒറ്റനോട്ടത്തിൽ കവറേജ് കാണിക്കുന്ന ഷിഫ്റ്റ് ബ്ലോക്കുകളോടെ.',
            'rota_step2' => '<strong>ഷിഫ്റ്റുകൾ ചേർക്കുക അല്ലെങ്കിൽ എഡിറ്റ് ചെയ്യുക</strong> &mdash; ഒരു ഷിഫ്റ്റ് തരം (ഉദാ. Early, Late, Night, On-Call) അസൈൻ ചെയ്യാൻ ഒരു സെല്ലിൽ ക്ലിക്ക് ചെയ്യുക. മാറ്റങ്ങൾ ഉടനടി സേവ് ചെയ്യുന്നു.',
            'rota_step3' => '<strong>മുൻകൂട്ടി ആസൂത്രണം ചെയ്യുക</strong> &mdash; റോട്ട മുൻകൂട്ടി തയ്യാറാക്കാൻ ആഴ്ച തിരിച്ച് മുന്നോട്ട് നാവിഗേറ്റ് ചെയ്യുക. അറിയപ്പെടുന്ന തിരക്കുള്ള കാലയളവുകൾ, അവധികൾ, അല്ലെങ്കിൽ പരിശീലന ദിനങ്ങളിൽ ഇത് മതിയായ കവറേജ് ഉറപ്പാക്കുന്നു.',
            'rota_step4' => '<strong>ഒന്നിലധികം സെല്ലുകൾ ഒരുമിച്ച് പൂരിപ്പിക്കുക</strong> &mdash; ഒരു സെല്ലിൽ <strong>റൈറ്റ്-ക്ലിക്ക്</strong> ചെയ്ത് അതിലെ ഷിഫ്റ്റ് എടുക്കാൻ <em>പകർത്തുക</em> തിരഞ്ഞെടുക്കുക, പിന്നെ മറ്റൊന്നിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്ത് <em>പേസ്റ്റ് ചെയ്യുക</em>. ഒന്നിലധികം സെല്ലുകൾക്ക്, അവയിലൊരു ബ്ലോക്കിലൂടെ <strong>വലിച്ചിടുക</strong> (അല്ലെങ്കിൽ ഓരോ സെല്ലിലും ctrl-ക്ലിക്ക് ചെയ്യുക), എന്നിട്ട് അതിലേക്കെല്ലാം പേസ്റ്റ് ചെയ്യുക. ഒരു <strong>ദിവസത്തിന്റെ ഹെഡിംഗ്</strong> ഹോവർ ചെയ്യുന്നത് ആ ദിവസം മുഴുവൻ ഹൈലൈറ്റ് ചെയ്യും, ഒരു <strong>അനലിസ്റ്റിന്റെ പേര്</strong> ഹോവർ ചെയ്യുന്നത് അവരുടെ ആഴ്ച മുഴുവൻ ഹൈലൈറ്റ് ചെയ്യും &mdash; ഏതെങ്കിലും ഒന്നിൽ റൈറ്റ്-ക്ലിക്ക് ചെയ്ത് അതിലേക്കെല്ലാം പേസ്റ്റ് ചെയ്യുക. ചില സെല്ലുകളിൽ ഇതിനകം ഒരു ഷിഫ്റ്റ് ഉള്ളപ്പോൾ മെനു രണ്ട് വഴികളും വ്യക്തമായ വാക്കുകളിൽ വാഗ്ദാനം ചെയ്യുന്നു &mdash; <em>എല്ലാ 7-ലേക്കും പേസ്റ്റ് ചെയ്യുക</em>, <em>6 ശൂന്യ സെല്ലുകളിലേക്ക് പേസ്റ്റ് ചെയ്യുക</em> &mdash; അതിനാൽ ചെയ്തതിന് ശേഷമല്ല, മുമ്പ് നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നു. ഓവർറൈറ്റ് ചെയ്യുന്നത് സ്ഥിരീകരണം ചോദിക്കുകയും അത് എത്ര ഷിഫ്റ്റുകൾ മാറ്റിസ്ഥാപിക്കുന്നു എന്ന് പറയുകയും ചെയ്യുന്നു; ശൂന്യമായ ഇടങ്ങൾ പൂരിപ്പിക്കുന്നത് വെറുതെ സംഭവിക്കുന്നു, ഒന്നും നഷ്ടപ്പെടാത്തതിനാൽ. അതേ മെനുകൾ ഒരു ദിവസമോ ആഴ്ചയോ തിരഞ്ഞെടുപ്പോ <strong>മായ്ക്കുകയും</strong> ചെയ്യും, അത് എത്ര ഷിഫ്റ്റുകൾ നീക്കം ചെയ്യുന്നു എന്ന് വീണ്ടും പറഞ്ഞതിന് ശേഷം.',
            'rota_step5' => '<strong>ഒരാൾക്കായി ഒരു ദിവസം മുഴുവനോ ഒരു ആഴ്ച മുഴുവനോ പകർത്തുക</strong> &mdash; ആ ദിവസത്തിലെ എല്ലാ ഷിഫ്റ്റുകളും എടുക്കാൻ ഒരു <strong>ദിവസത്തിന്റെ ഹെഡിംഗിൽ</strong> റൈറ്റ്-ക്ലിക്ക് ചെയ്ത് <em>പകർത്തുക</em> തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ അവരുടെ ആഴ്ച മുഴുവൻ എടുക്കാൻ ഒരു <strong>അനലിസ്റ്റിന്റെ പേരിൽ</strong>. മറ്റൊരു ദിവസത്തിലേക്കോ മറ്റൊരു അനലിസ്റ്റിലേക്കോ പേസ്റ്റ് ചെയ്യുന്നത് അത് പൊരുത്തപ്പെടുത്തുന്നു: പകർത്തിയതിൽ ഇല്ലാത്ത ഷിഫ്റ്റുകൾ മായ്ക്കപ്പെടും, അതിനാൽ നിങ്ങൾക്ക് രണ്ടിന്റെയും മിശ്രിതത്തിനു പകരം പകർത്തിയ ദിവസം തന്നെ ലഭിക്കും. ഒരു ദിവസം മറ്റൊരു ദിവസത്തിലേക്ക് മാത്രമേ പേസ്റ്റ് ചെയ്യാനാകൂ, ഒരു അനലിസ്റ്റ് മറ്റൊരു അനലിസ്റ്റിലേക്ക് മാത്രമേ പേസ്റ്റ് ചെയ്യാനാകൂ &mdash; ഒരു ദിവസം <em>ഓരോ വ്യക്തിക്കും</em> ഒരു ഷിഫ്റ്റ് ആണ്, ഒരു ആഴ്ച <em>ഓരോ ദിവസത്തിനും</em> ഒരു ഷിഫ്റ്റ് ആണ്, അതിനാൽ ഒന്ന് മറ്റൊന്നിന് മുകളിൽ വയ്ക്കാൻ യുക്തിസഹമായ വഴിയില്ല. ശ്രമിച്ചാൽ മെനു അത് പറയും, പകരം അത് എവിടെ പോകാമെന്നും പറയും.',
            'rota_step6' => '<strong>ഒരു ആഴ്ച മുഴുവൻ പകർത്തുക</strong> &mdash; മുകളിൽ വലതുവശത്തുള്ള <strong>ആഴ്ച പകർത്തുക</strong>, <strong>ആഴ്ച പേസ്റ്റ് ചെയ്യുക</strong> എന്നിവ നിങ്ങൾ കാണുന്ന ആഴ്ചയിലെ എല്ലാ ഷിഫ്റ്റുകളും എടുത്ത് മറ്റൊന്നിലേക്ക് ഇടുന്നു, ആവർത്തിക്കുന്ന ഒരു റോട്ട നിർമ്മിക്കാനുള്ള ഏറ്റവും വേഗതയുള്ള വഴിയാണിത്. പേസ്റ്റ് ചെയ്യുന്നത് ലക്ഷ്യ ആഴ്ചയെ <em>മാറ്റിസ്ഥാപിക്കുന്നു</em>, അതിനാൽ എത്ര എൻട്രികൾ നീക്കം ചെയ്യാൻ പോകുന്നു എന്ന് സ്ഥിരീകരണം പറയും. ഗ്രിഡ് യഥാർത്ഥത്തിൽ കാണിക്കുന്ന ദിവസങ്ങളെയും ആളുകളെയും മാത്രമേ ഇത് സ്പർശിക്കൂ.',
            'tip' => 'ഫലപ്രദമായ ശേഷി ആസൂത്രണത്തിന് കലണ്ടറും റോട്ടയും ഒരുമിച്ച് ഉപയോഗിക്കുക. ഓരോ തിങ്കളാഴ്ച രാവിലെയും ടിക്കറ്റുകളിൽ ഒരു കുതിച്ചുചാട്ടം കലണ്ടർ കാണിക്കുന്നെങ്കിൽ, ആ സ്ലോട്ടിനായി റോട്ടയിൽ അധിക കവറേജ് ഷെഡ്യൂൾ ചെയ്തിട്ടുണ്ടെന്ന് ഉറപ്പാക്കുക.',
        ],
        'settings' => [
            'heading' => 'ക്രമീകരണങ്ങൾ',
            'intro' => 'നിങ്ങളുടെ ടിക്കറ്റിംഗ് സിസ്റ്റത്തിന്റെ അടിസ്ഥാന ഘടകങ്ങൾ ക്രമീകരിക്കുന്നിടമാണ് ക്രമീകരണങ്ങൾ പേജ്. എല്ലാ ലുക്കപ്പ് മൂല്യങ്ങളും, SLA ലക്ഷ്യങ്ങളും, ഇമെയിൽ ഇന്റഗ്രേഷനും, കസ്റ്റം ഫീൽഡുകളും ഇവിടെ മാനേജ് ചെയ്യുന്നു.',
            'sla_callout_title' => 'SLA മാനേജ്മെന്റ് &mdash; പൂർണ്ണ ഗൈഡ്',
            'sla_callout_body' => 'ക്രമീകരിക്കാവുന്ന ഓപ്ഷനുകൾ, ബിസിനസ് കലണ്ടറുകൾ, താൽക്കാലിക നിർത്തൽ നിലകൾ, ബ്രീച്ച് അറിയിപ്പുകൾ, ക്രോൺ ജോബ് സെറ്റപ്പ്, ഒറ്റ-ടൈംസോൺ, ക്രോസ്-ടൈംസോൺ ടീമുകൾക്കുള്ള വർക്ക് ചെയ്ത ഉദാഹരണങ്ങൾ. അതിന്റേതായ പേജ് അർഹിക്കുന്നത്ര ഗൗരവമുള്ളത്.',
            'card_dept_title' => 'വകുപ്പുകൾ',
            'card_dept_body' => 'IT, HR, Finance പോലുള്ള വകുപ്പുകൾ സൃഷ്ടിക്കുക. ഓരോ വകുപ്പും ഇൻബോക്സിൽ ഒരു ഫോൾഡറും ഡാഷ്ബോർഡിൽ ഒരു ഫിൽട്ടറും ആകുന്നു',
            'card_types_title' => 'ടിക്കറ്റ് തരങ്ങൾ',
            'card_types_body' => 'നിങ്ങളുടെ ഡെസ്ക് കൈകാര്യം ചെയ്യുന്ന അഭ്യർത്ഥന തരങ്ങൾ നിർവചിക്കുക: Incident, Service Request, Problem, Change. തരങ്ങൾ അനലിസ്റ്റുകൾക്ക് ജോലി വർഗ്ഗീകരിക്കാൻ സഹായിക്കുന്നു',
            'card_priorities_title' => 'മുൻഗണനകൾ',
            'card_priorities_body' => 'പേരുകളും നിറങ്ങളും സോർട്ട് ക്രമവുമുള്ള മുൻഗണനാ നിലവാരങ്ങൾ സെറ്റ് ചെയ്യുക. ഓരോ മുൻഗണനയും റെസ്പോൺസിനും റെസലൂഷനും ഒരു SLA ലക്ഷ്യവുമായി ലിങ്ക് ചെയ്യുന്നു',
            'card_statuses_title' => 'നിലകൾ',
            'card_statuses_body' => 'ടിക്കറ്റ് ലൈഫ്‌സൈക്കിൾ ഘട്ടങ്ങൾ ഇഷ്ടാനുസൃതമാക്കുക. New, Open, In Progress, Pending, Resolved, Closed എന്നിവ സ്ഥിരസ്ഥിതി നിലകളിൽ ഉൾപ്പെടുന്നു',
            'card_categories_title' => 'വിഭാഗങ്ങൾ',
            'card_categories_body' => 'സാങ്കേതിക മേഖല അനുസരിച്ച് ടിക്കറ്റുകൾ ഗ്രൂപ്പ് ചെയ്യുക: Hardware, Software, Network, Access. വിഭാഗങ്ങൾ റിപ്പോർട്ടിംഗ് ബ്രേക്ക്ഡൗണുകൾക്ക് ശക്തി നൽകുന്നു',
            'card_sla_title' => 'SLA ലക്ഷ്യങ്ങൾ',
            'card_sla_body' => 'ഓരോ മുൻഗണനയ്ക്കും റെസ്പോൺസ്, റെസലൂഷൻ സമയ ലക്ഷ്യങ്ങൾ നിർവചിക്കുക. SLA ടൈമറുകൾ ടിക്കറ്റുകളിൽ പ്രത്യക്ഷപ്പെടുകയും ബ്രീച്ച് മുന്നറിയിപ്പുകൾ നയിക്കുകയും ചെയ്യുന്നു',
            'card_email_title' => 'ഇമെയിൽ ഇറക്കുമതി',
            'card_email_body' => 'പുതിയ ടിക്കറ്റുകളായി ഇമെയിലുകൾ സ്വയമേവ ഇറക്കുമതി ചെയ്യാൻ ഒരു മെയിൽബോക്സ് (Exchange, Microsoft 365) ബന്ധിപ്പിക്കുക. മറുപടികൾ നിലവിലുള്ള ടിക്കറ്റുകളിലേക്ക് ത്രെഡ് ചെയ്യും',
            'card_custom_title' => 'കസ്റ്റം ഫീൽഡുകൾ',
            'card_custom_body' => 'സ്ഥിരസ്ഥിതി ഫീൽഡ് സെറ്റ് ഉൾക്കൊള്ളാത്ത, നിങ്ങളുടെ ഓർഗനൈസേഷന് ശേഖരിക്കേണ്ട ഡാറ്റയ്ക്കായി ടിക്കറ്റുകളിലേക്ക് നിങ്ങളുടെ സ്വന്തം ഫീൽഡുകൾ ചേർക്കുക',
            'card_templates_title' => 'ഇമെയിൽ ടെംപ്ലേറ്റുകൾ',
            'card_templates_body' => 'ടിക്കറ്റുകൾ സൃഷ്ടിക്കുമ്പോൾ, അപ്ഡേറ്റ് ചെയ്യുമ്പോൾ, പരിഹരിക്കുമ്പോൾ, അല്ലെങ്കിൽ CSAT സർവേയ്ക്കായി എൻഡ് യൂസർമാർക്ക് അയക്കുന്ന അറിയിപ്പ് ടെംപ്ലേറ്റുകൾ ക്രമീകരിക്കുക. [requester_name], [csat_link] പോലുള്ള മെർജ് കോഡുകൾ ഉൾപ്പെടുത്തുക',
            'card_checklists_title' => 'ചെക്ക്‌ലിസ്റ്റുകൾ',
            'card_checklists_body' => 'ഇപ്പോഴും നിർബന്ധിത ചെക്ക്‌ലിസ്റ്റ് ഘട്ടങ്ങൾ ബാക്കിയുള്ള ഒരു ടിക്കറ്റ് ആരെങ്കിലും അടയ്ക്കുമ്പോൾ എന്ത് സംഭവിക്കണം എന്ന് തീരുമാനിക്കുക: ഘട്ടങ്ങളും ആരാണ് അടച്ചതെന്നും പേരെടുത്ത് ഒരു ഇന്റേണൽ കുറിപ്പ് രേഖപ്പെടുത്തി <strong>മുന്നറിയിപ്പ്</strong> നൽകുക, അല്ലെങ്കിൽ അവ പൂർത്തിയാകുന്നതുവരെ അടയ്ക്കൽ <strong>തടയുക</strong>. ബൾക്ക് ആക്ഷനുകൾ, REST API, വർക്ക്ഫ്ലോ ഓട്ടോമേഷൻ ഉൾപ്പെടെ ടിക്കറ്റ് അടയ്ക്കാൻ കഴിയുന്ന എല്ലായിടത്തും നടപ്പിലാക്കുന്നു',
            'card_mandatory_title' => 'നിർബന്ധിത ഫീൽഡുകൾ',
            'card_mandatory_body' => 'ഒരു ടിക്കറ്റ് അടയ്ക്കുന്നതിന് മുമ്പ് പൂരിപ്പിക്കേണ്ട ഫീൽഡുകൾ ടിക് ചെയ്യുക - വിഭാഗം, റെസലൂഷൻ കോഡ്, ഉടമ എന്നിങ്ങനെ. പിന്നെ ഒരു ഫീൽഡ് ശൂന്യമായി ഒരാൾ ഒന്ന് അടയ്ക്കുമ്പോൾ എന്ത് സംഭവിക്കണം എന്ന് തിരഞ്ഞെടുക്കുക: <strong>മുന്നറിയിപ്പ്</strong>, ഒരു സർവീസ് ഡെലിവറി മാനേജർ പോലുള്ള ആരെയെങ്കിലും <strong>മുന്നറിയിപ്പും ഇമെയിലും</strong>, അല്ലെങ്കിൽ അടയ്ക്കൽ <strong>നിരസിക്കുക</strong>. ഒരു പ്രത്യേക സ്വിച്ച് ഇത് ടിക്കറ്റിൽ ഒരു ഇന്റേണൽ കുറിപ്പായി രേഖപ്പെടുത്തുന്നു. ഒരു കമ്പനിക്ക് ഓഫ് ചെയ്ത ഫീൽഡ് ഒരിക്കലും ആവശ്യമില്ല, ടിക്കറ്റുകൾ മെർജ് ചെയ്യുന്നത് ഇത് ഒരിക്കലും ട്രിഗർ ചെയ്യില്ല. ബൾക്ക് ആക്ഷനുകൾ, REST API, വർക്ക്ഫ്ലോ ഓട്ടോമേഷൻ ഉൾപ്പെടെ ടിക്കറ്റ് അടയ്ക്കാൻ കഴിയുന്ന എല്ലായിടത്തും നടപ്പിലാക്കുന്നു',
            'card_cleanup_title' => 'റിപ്ലൈ ക്ലീൻഅപ്പ് AI',
            'card_cleanup_body' => 'റിപ്ലൈ എഡിറ്ററിലെ ✨ Cleanup ബട്ടണിനുള്ള Anthropic കീ + മോഡൽ + ടോൺ. ഗ്രാനുലാർ ബില്ലിംഗിനായി മറ്റ് AI ഫീച്ചറുകളിൽ നിന്ന് വേറിട്ട കീ',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'അയക്കൽ മോഡ് (ഓഫ് / ഓട്ടോ / മാനുവൽ), ഡിലേ, ഒരു-ടിക്കറ്റിന്-ഒന്ന് ഗാർഡ്, സ്കെയിൽ (സ്റ്റാറുകൾ അല്ലെങ്കിൽ ഇമോജികൾ). പൂർണ്ണ ഫ്ലോയ്ക്ക് സെക്ഷൻ 6 കാണുക',
            'email_heading' => '<strong>ഇമെയിൽ ഇറക്കുമതി വിശദമായി</strong>',
            'email_body' => 'ഇമെയിൽ ഇറക്കുമതി ഫീച്ചർ നിങ്ങളുടെ പങ്കിട്ട മെയിൽബോക്സിലേക്ക് ബന്ധിപ്പിക്കുകയും പുതിയ സന്ദേശങ്ങൾ ടിക്കറ്റുകളായി വലിച്ചെടുക്കുകയും ചെയ്യുന്നു. ഒരു എൻഡ് യൂസർ നിങ്ങളുടെ സപ്പോർട്ട് അഡ്രസിലേക്ക് (ഉദാ. support@yourcompany.com) ഒരു ഇമെയിൽ അയച്ചാൽ, ഇമെയിൽ വിഷയം തലക്കെട്ടായും ഇമെയിൽ ബോഡി വിവരണമായും ഉള്ള ഒരു ടിക്കറ്റ് FreeITSM സൃഷ്ടിക്കുന്നു. അയച്ചയാൾ ഒരു അറിയിപ്പ് ഇമെയിലിന് മറുപടി നൽകിയാൽ, ഒരു ഡ്യൂപ്ലിക്കേറ്റ് സൃഷ്ടിക്കുന്നതിന് പകരം മറുപടി നിലവിലുള്ള ടിക്കറ്റിലേക്ക് ത്രെഡ് ചെയ്യുന്നു.',
            'email_step1' => '<strong>മെയിൽബോക്സ് ക്രമീകരിക്കുക</strong> &mdash; ക്രമീകരണങ്ങളിലേക്ക് പോയി നിങ്ങളുടെ Exchange അല്ലെങ്കിൽ Microsoft 365 ക്രെഡൻഷ്യലുകൾ നൽകുക. സുരക്ഷിതവും പാസ്‌വേഡ് ഇല്ലാത്തതുമായ കണക്ഷനുകൾക്കായി OAuth ഓതന്റിക്കേഷൻ പിന്തുണയ്ക്കുന്നു.',
            'email_step2' => '<strong>പോളിംഗ് ഇടവേള സെറ്റ് ചെയ്യുക</strong> &mdash; പുതിയ സന്ദേശങ്ങൾക്കായി FreeITSM മെയിൽബോക്സ് എത്ര തവണ പരിശോധിക്കും എന്ന് തിരഞ്ഞെടുക്കുക. ചെറിയ ഇടവേളകൾ എന്നാൽ വേഗത്തിലുള്ള ടിക്കറ്റ് സൃഷ്ടിക്കൽ.',
            'email_step3' => '<strong>സ്ഥിരസ്ഥിതികൾ മാപ്പ് ചെയ്യുക</strong> &mdash; ഇമെയിലിൽ നിന്ന് സൃഷ്ടിക്കുന്ന ടിക്കറ്റുകൾക്കുള്ള സ്ഥിരസ്ഥിതി വകുപ്പ്, തരം, മുൻഗണന എന്നിവ സെറ്റ് ചെയ്യുക. ഇറക്കുമതിക്ക് ശേഷം അനലിസ്റ്റുകൾക്ക് ഇവ ക്രമീകരിക്കാം.',
            'tip' => 'എല്ലാ എൻഡ് യൂസർ ആശയവിനിമയങ്ങളിലും ഒരു പ്രൊഫഷണലും സ്ഥിരതയുള്ളതുമായ ടോൺ നിലനിർത്താൻ ഇമെയിൽ ടെംപ്ലേറ്റുകൾ ഉപയോഗിക്കുക. ടിക്കറ്റ് റഫറൻസ്, അഭ്യർത്ഥിച്ചയാളുടെ പേര്, അനലിസ്റ്റിന്റെ പേര്, നില എന്നിവയ്ക്കായി ടെംപ്ലേറ്റുകൾ ഡൈനാമിക് പ്ലേസ്‌ഹോൾഡറുകളെ പിന്തുണയ്ക്കുന്നു.',
            'closemsg_heading' => '<strong>ടിക്കറ്റ് അടയ്ക്കുമ്പോൾ ഒരു ഒറ്റത്തവണ സന്ദേശം</strong>',
            'closemsg_body' => '<code>[ticket_closed_message]</code> സജീവമായ ഒരു <strong>ടിക്കറ്റ് അടച്ചു</strong> ടെംപ്ലേറ്റിൽ എവിടെയെങ്കിലും ഇടുക, അതിനുശേഷം ഒരു ടിക്കറ്റ് അടച്ച നിലയിലേക്ക് സെറ്റ് ചെയ്യുന്നത് അനലിസ്റ്റിനോട് ഒരു വാചകം ചോദിക്കും - <em>&ldquo;സ്പെയർ ചാർജർ നിങ്ങളുടെ മേശപ്പുറത്തുണ്ട്&rdquo;</em>, <em>&ldquo;ഫോണിൽ സമ്മതിച്ചതനുസരിച്ച് അടയ്ക്കുന്നു&rdquo;</em>. അവർ ടൈപ്പ് ചെയ്യുന്നത് നിങ്ങൾ പ്ലേസ്‌ഹോൾഡർ ഇട്ട അതേ സ്ഥലത്ത് കൃത്യമായി വരും, അതിനാൽ അതിന് ചുറ്റുമുള്ള വാക്കുകളുടെ നിയന്ത്രണം നിങ്ങൾക്കുതന്നെ തുടരും. ഇതൊരു ക്രമീകരണമല്ല, ഒന്നും ഇത് സ്റ്റോർ ചെയ്യുന്നില്ല: ഒരു കുറിപ്പ്, ഒരു ടിക്കറ്റ്, ഒരു ഇമെയിൽ. ഒന്നും ടൈപ്പ് ചെയ്യാതിരുന്നാൽ വരി അവിടെ ഉണ്ടാകില്ല - വിടവോ, അലഞ്ഞുതിരിയുന്ന വിരാമചിഹ്നമോ ഇല്ല.',
            'closemsg_note' => '<strong>പ്ലേസ്‌ഹോൾഡർ ടെംപ്ലേറ്റിൽ യഥാർത്ഥത്തിൽ ഉള്ളപ്പോൾ മാത്രമേ പ്രോംപ്റ്റ് പ്രത്യക്ഷപ്പെടൂ.</strong> ഇല്ലെങ്കിൽ, ഒരു അനലിസ്റ്റ് ടൈപ്പ് ചെയ്തത് എന്തും നിശബ്ദമായി ഒഴിവാക്കപ്പെടും, ഇത് വേണ്ടാത്ത ഓരോ ഡെസ്കിനും ഓരോ അടയ്ക്കലിലും ഒരു അധിക ക്ലിക്ക് വരും. അതിനാൽ നിങ്ങൾ ഇത് ക്രമീകരിക്കുമ്പോൾ അത് സ്വയം ഓണാകുകയും, ചെയ്യാത്തപ്പോൾ വഴിയിൽ നിന്ന് മാറി നിൽക്കുകയും ചെയ്യുന്നു.',
            'cat_heading' => '<strong>വിഭാഗങ്ങൾ, അവയ്ക്കൊപ്പമുള്ള രണ്ട് ഫീൽഡുകൾ</strong>',
            'cat_body' => 'ഒരു ടിക്കറ്റ് <em>തരം</em> ഇത് എന്ത് തരത്തിലുള്ള കാര്യമാണെന്ന് പറയുന്നു; ഒരു <em>വിഭാഗം</em> ഇത് എന്തിനെക്കുറിച്ചാണെന്ന് പറയുന്നു. <strong>ക്രമീകരണങ്ങൾ &rarr; വിഭാഗങ്ങൾ</strong>-ന് കീഴിൽ ലിസ്റ്റ് ഉണ്ടാക്കുക, ഏതെങ്കിലും ഇത് ടിക്കറ്റിൽ പ്രത്യക്ഷപ്പെടണോ എന്ന് തീരുമാനിക്കുന്ന സ്വിച്ചുകൾക്കൊപ്പം.',
            'cat_card_one_title' => 'വിഭാഗം',
            'cat_card_one_body' => 'ഇത് ഉയർത്തിയപ്പോൾ തിരഞ്ഞെടുത്ത, ടിക്കറ്റ് എന്താണ് റിപ്പോർട്ട് ചെയ്തതെന്ന്. ഒരു ടിക്കറ്റിന് കൃത്യമായി ഒന്ന് വീതമുണ്ട്, അതിനാൽ നിങ്ങളുടെ വിഭാഗങ്ങളുടെ ഒരു റിപ്പോർട്ട് എപ്പോഴും നിങ്ങൾക്ക് യഥാർത്ഥത്തിൽ ഉണ്ടായിരുന്ന ടിക്കറ്റുകളുടെ എണ്ണത്തിന് തുല്യമാകും.',
            'cat_card_close_title' => 'അടയ്ക്കുമ്പോളുള്ള വിഭാഗം',
            'cat_card_close_body' => 'ടിക്കറ്റ് പൂർത്തിയാകുമ്പോൾ വീണ്ടും ചോദിക്കുന്ന അതേ ലിസ്റ്റ്. സാധാരണയായി അനലിസ്റ്റ് അത് സ്ഥിരീകരിക്കുക മാത്രമേ ചെയ്യുന്നുള്ളൂ &mdash; ആദ്യ അനുമാനം തെറ്റായവയിൽ ഇത് അതിന്റെ സ്ഥാനം അർഹിക്കുന്നു, നിങ്ങളുടെ മുപ്പത്തിയേഴ് "പ്രിന്റർ പ്രശ്നങ്ങളിൽ" പന്ത്രണ്ടും യഥാർത്ഥത്തിൽ നെറ്റ്‌വർക്കായിരുന്നു എന്ന് കണ്ടെത്തുന്ന വിധം ഇതാണ്.',
            'cat_card_res_title' => 'റെസലൂഷൻ കോഡ്',
            'cat_card_res_body' => 'ടിക്കറ്റ് എന്തിനെക്കുറിച്ചാണെന്നല്ല, എങ്ങനെ അവസാനിച്ചു എന്ന് &mdash; "വിദൂരമായി പരിഹരിച്ചു", "പരിശീലനം നൽകി", "തകരാർ കണ്ടെത്തിയില്ല". തുടക്കം മുതൽ പത്ത് ഉപകാരപ്രദമായവ ഉണ്ട്, നിങ്ങൾക്ക് അവയെല്ലാം മാറ്റാം.',
            'cat_rule_off' => '<strong>മൂന്നും ആദ്യം ഓഫ് ചെയ്തിരിക്കും.</strong> ആദ്യം നിങ്ങളുടെ ലിസ്റ്റ് ഉണ്ടാക്കുക, പിന്നെ വേണ്ടവ ഓൺ ചെയ്യുക. ഓരോ കമ്പനിക്കും ഇത് വ്യത്യസ്തമായി സെറ്റ് ചെയ്യാം.',
            'cat_rule_levels' => 'വിഭാഗങ്ങൾക്ക് മൂന്ന് ലെവൽ വരെ ഉപ-വിഭാഗങ്ങൾ ഉണ്ടാകാം, ഒരു ലെവലും നിർബന്ധമല്ല.',
            'cat_rule_type' => 'ഒരു വിഭാഗത്തെ ഒരു ടിക്കറ്റ് തരവുമായി ബന്ധിപ്പിക്കാം, അതിനാൽ "User onboarding" ഒരു സർവീസ് അഭ്യർത്ഥനയിൽ മാത്രമേ വാഗ്ദാനം ചെയ്യൂ. ഈ ബന്ധം ടോപ്-ലെവൽ വിഭാഗത്തിന്റേതാണ്, അതിന്റെ ഉപ-വിഭാഗങ്ങൾ അത് പിന്തുടരും.',
            'cat_rule_typechange' => '<strong>ഒരു ടിക്കറ്റിന്റെ തരം മാറ്റുന്നത് പഴയ തരത്തിൽപ്പെട്ട ഒരു വിഭാഗം മായ്ക്കും</strong>, സ്ക്രീനിൽ അത് പറയുകയും ചെയ്യും. ഒരു തരവുമായും ബന്ധിപ്പിക്കാത്ത ഒരു വിഭാഗം മാറ്റത്തെ അതിജീവിക്കും.',
            'cat_rule_portal' => 'സെൽഫ്-സർവീസ് പോർട്ടലിൽ ഒരു വിഭാഗം വാഗ്ദാനം ചെയ്യാൻ <em>കസ്റ്റമേഴ്‌സിന് ഇത് തിരഞ്ഞെടുക്കാം</em> ടിക് ചെയ്യുക. അഭ്യർത്ഥിച്ചവർ ലളിതമായ ഇംഗ്ലീഷിൽ ഒരു ചെറിയ ലിസ്റ്റ് കാണുമ്പോൾ അനലിസ്റ്റുകൾ മുഴുവൻ ട്രീയും കാണും.',
            'cat_rule_retire' => 'ഒരു വിഭാഗം റിട്ടയർ ചെയ്യാൻ അത് ഓഫ് ചെയ്യുക &mdash; ഇത് ഇതിനകം ഉള്ള ടിക്കറ്റുകളിൽ തുടരും, പുതിയവയിൽ വാഗ്ദാനം ചെയ്യുന്നത് നിർത്തും. ഇത് മിക്കപ്പോഴും ഡിലീറ്റ് ചെയ്യുന്നതിനേക്കാൾ മികച്ചതാണ്, കാരണം എന്തെങ്കിലും ഇപ്പോഴും ഉപയോഗിക്കുന്നിടത്തോളം ഡിലീറ്റ് ചെയ്യാൻ അനുവദിക്കില്ല.',
            'cat_rule_report' => 'മൂന്നും ടിക്കറ്റ് ഡാഷ്ബോർഡിൽ ചാർട്ട് ചെയ്യാം. രണ്ട് വിഭാഗം ചാർട്ടുകളും ടോപ് ലെവലിലേക്ക് ചുരുട്ടിക്കൂട്ടും, ഒന്നും സെറ്റ് ചെയ്യാത്ത ടിക്കറ്റുകൾ മറയ്ക്കുന്നതിന് പകരം <em>വിഭാഗീകരിച്ചിട്ടില്ല</em> എന്ന് കണക്കാക്കും.',
            'cat_tip' => 'എവിടെ തുടങ്ങണമെന്ന് ഉറപ്പില്ലെങ്കിൽ, വിഭാഗങ്ങൾ ശൂന്യമായി വിട്ട് <strong>റെസലൂഷൻ കോഡ്</strong> മാത്രം ഓൺ ചെയ്യുക. നിങ്ങൾ ചെയ്യുന്നത് ഏറ്റവും വേഗത്തിൽ മാറ്റുന്ന ഫീൽഡ് ഇതാണ് &mdash; നിങ്ങളുടെ ടിക്കറ്റുകളിൽ അഞ്ചിലൊന്ന് "പരിശീലനം നൽകി" ആയി തിരികെ വരുന്നത് ഒരു ഡോക്യുമെന്റേഷൻ പ്രശ്നമാണ്, IT പ്രശ്നമല്ല.',
        ],
        'tips' => [
            'heading' => 'വേഗത്തിലുള്ള നുറുങ്ങുകൾ',
            'search_title' => 'എല്ലാം തിരയുക',
            'search_body' => 'സെർച്ച് മോഡൽ ടിക്കറ്റ് റഫറൻസുകൾ, വിഷയങ്ങൾ, അഭ്യർത്ഥിച്ചയാളുടെ പേരുകൾ, ഇമെയിൽ അഡ്രസുകൾ എന്നിവ പരിശോധിക്കുന്നു. നിലവിലുള്ള ഒരു പ്രശ്നത്തെക്കുറിച്ച് ഒരു ഉപയോക്താവ് വിളിക്കുമ്പോൾ ബന്ധപ്പെട്ട ടിക്കറ്റുകൾ വേഗത്തിൽ കണ്ടെത്താൻ ഇത് ഉപയോഗിക്കുക.',
            'sla_title' => 'നിങ്ങളുടെ SLA-കൾ നിരീക്ഷിക്കുക',
            'sla_body' => 'റീഡിംഗ് പെയിനിൽ ഓരോ ടിക്കറ്റിലും SLA ടൈമറുകൾ ദൃശ്യമാണ്. ഒരു ബ്രീച്ച് അടുക്കുമ്പോൾ വർണ്ണ-കോഡഡ് സൂചകങ്ങൾ ആമ്പറും, ലക്ഷ്യം നഷ്ടമായപ്പോൾ ചുവപ്പും ആകും, അതിനാൽ അതനുസരിച്ച് മുൻഗണന നൽകാം.',
            'reply_title' => 'ഇൻബോക്സിൽ നിന്ന് മറുപടി നൽകുക',
            'reply_body' => 'ഒരു എൻഡ് യൂസറിന് മറുപടി നൽകാൻ നിങ്ങളുടെ ഇമെയിൽ ക്ലയന്റ് തുറക്കേണ്ടതില്ല. നേരിട്ട് ഒരു സന്ദേശം അയക്കാൻ റീഡിംഗ് പെയിനിലെ റിപ്ലൈ ബട്ടൺ ഉപയോഗിക്കുക. ഇത് സ്വയമേവ ടിക്കറ്റിലേക്ക് ത്രെഡ് ചെയ്യും.',
            'trail_title' => 'ആക്റ്റിവിറ്റി ട്രെയിൽ ഉപയോഗിക്കുക',
            'trail_body' => 'ഒരു ടിക്കറ്റിൽ ജോലി ചെയ്യുന്നതിന് മുമ്പ്, അതിന്റെ ആക്റ്റിവിറ്റി ട്രെയിലിലൂടെ സ്ക്രോൾ ചെയ്യുക. മുൻ അനലിസ്റ്റ് കുറിപ്പുകൾ, ഇമെയിലുകൾ, ഫീൽഡ് മാറ്റങ്ങൾ എന്നിവ പൂർണ്ണ സന്ദർഭം നൽകുന്നു, അതിനാൽ വിവരം ആവർത്തിക്കാൻ ഉപയോക്താവിനോട് ചോദിക്കേണ്ടിവരില്ല.',
            'dash_title' => 'മാനേജർമാർക്കായി ഡാഷ്ബോർഡ്',
            'dash_body' => 'SLA കംപ്ലയൻസ് നിരക്കുകൾ, ശരാശരി റെസലൂഷൻ സമയം, വകുപ്പ് അനുസരിച്ചുള്ള ടിക്കറ്റുകൾ എന്നിവയ്ക്കുള്ള വിജറ്റുകളോടെ ഒരു ഡാഷ്ബോർഡ് നിർമ്മിക്കുക. തുടർച്ചയായ മെച്ചപ്പെടുത്തലിന് ടീം മീറ്റിംഗുകളിൽ ഇത് പങ്കിടുക.',
            'rota_title' => 'റോട്ട ഉപയോഗിച്ച് ആസൂത്രണം ചെയ്യുക',
            'rota_body' => 'കുറഞ്ഞത് രണ്ട് ആഴ്ച മുൻകൂട്ടി റോട്ട പൂരിപ്പിക്കുക. കലണ്ടർ കാഴ്ചയുമായി സംയോജിപ്പിക്കുമ്പോൾ, റെസ്പോൺസ് സമയങ്ങൾക്ക് ഒരു പ്രശ്നമാകുന്നതിന് മുമ്പ് കവറേജിലെ വിടവുകൾ കണ്ടെത്താൻ ഇത് സഹായിക്കുന്നു.',
            'drag_title' => 'ട്രയാജിനായി വലിച്ചിടുക',
            'drag_body' => 'തുറക്കാതെ അപ്ഡേറ്റ് ചെയ്യാൻ ലിസ്റ്റിൽ നിന്ന് ടിക്കറ്റുകൾ ഫോൾഡറുകളിലേക്ക് വലിച്ചിടുക. വകുപ്പ് + നില സബ്-ഫോൾഡറുകൾ രണ്ടും ഒരുമിച്ച് അപ്ഡേറ്റ് ചെയ്യും. സ്പ്രിംഗ്-ലോഡഡ് വികസനം വലിച്ചിടുന്നതിനിടയിൽ നെസ്റ്റഡ് നിലകൾ എത്തിച്ചേരാവുന്നതാക്കുന്നു.',
            'dbl_title' => 'മുഴുവൻ സ്ക്രീനിനായി ഡബിൾ-ക്ലിക്ക് ചെയ്യുക',
            'dbl_body' => 'സിംഗിൾ-ക്ലിക്ക് റീഡിംഗ് പെയിനിൽ ഒരു ടിക്കറ്റ് പ്രിവ്യൂ ചെയ്യുന്നു; ഡബിൾ-ക്ലിക്ക് ഫോക്കസ് ജോലിക്കായി അത് ഫുൾ-സ്ക്രീൻ മോഡിൽ തുറക്കുന്നു. തിരികെ മാറാൻ വിഷയത്തിന് അരികിലുള്ള മാക്സിമൈസ് ഐക്കൺ ക്ലിക്ക് ചെയ്യുക.',
            'rightclick_title' => 'വേഗത്തിലുള്ള ആക്ഷനുകൾക്കായി റൈറ്റ്-ക്ലിക്ക് ചെയ്യുക',
            'rightclick_body' => 'നിലയോ, മുൻഗണനയോ, അസൈനിയോ ഒറ്റ-ക്ലിക്കിൽ മാറ്റാൻ, കൂടാതെ ലിങ്ക്-CMDB, റെക്കോർഡ്-ടൈം എന്നിവയ്ക്കും, നിങ്ങൾ ഇപ്പോൾ വായിക്കുന്ന ടിക്കറ്റിൽ നിന്ന് മാറാതെ തന്നെ, ഏത് ടിക്കറ്റിലും റൈറ്റ്-ക്ലിക്ക് ചെയ്യുക.',
            'ai_title' => 'നിങ്ങളുടെ മറുപടി AI വൃത്തിയാക്കട്ടെ',
            'ai_body' => 'ഒരു ലളിതമായ ഡ്രാഫ്റ്റ് (അല്ലെങ്കിൽ വെറും ബുള്ളറ്റ് പോയിന്റുകൾ) ടൈപ്പ് ചെയ്ത് <strong>✨ Cleanup</strong> ക്ലിക്ക് ചെയ്യുക &mdash; Claude ഇത് അഭിവാദനം, വ്യാകരണ തിരുത്തലുകൾ, സൈൻ-ഓഫ് എന്നിവയോടെ ശരിയായ ഒരു ഇമെയിലായി മാറ്റിയെഴുതും. അൺഡു ലിങ്ക് 30 സെക്കൻഡ് ദൃശ്യമാകും.',
            'feedback_title' => 'ഫീഡ്ബാക്ക് ചോദിക്കുക',
            'feedback_body' => 'അഭ്യർത്ഥിച്ചവരുടെ ടിക്കറ്റുകൾ അടയ്ക്കുമ്പോൾ അവരെ ഓട്ടോ-സർവേ ചെയ്യാൻ <strong>ക്രമീകരണങ്ങൾ &rarr; CSAT</strong>-ൽ CSAT ഓൺ ചെയ്യുക. ഓരോ അനലിസ്റ്റിന്റെയും ട്രെൻഡുകൾ <code>tickets/csat/</code>-ൽ ലഭ്യമാണ് &mdash; ഡെവലപ്മെന്റ് സംഭാഷണങ്ങൾക്ക് സ്വർണ്ണം.',
            'precreate_title' => 'എൻഡ് യൂസർമാരെ മുൻകൂട്ടി സൃഷ്ടിക്കുക',
            'precreate_body' => 'ഒരു ഉപയോക്താവ് ടിക്കറ്റ് ലോഗ് ചെയ്യേണ്ടതിനു മുമ്പ് അവരെ ചേർക്കാൻ <strong>Users</strong> നാവ് ബട്ടൺ അനുവദിക്കുന്നു &mdash; പാസ്‌വേഡ് ശൂന്യമായി വിടുക, അവർക്ക് സെൽഫ്-സർവീസ് പോർട്ടൽ വഴി സ്വയം അക്കൗണ്ട് ക്ലെയിം ചെയ്യാം.',
        ],
        'companies' => [
            'heading' => 'കമ്പനികൾ &amp; ഇമെയിൽ റൂട്ടിംഗ്',
            'intro' => 'നിങ്ങളുടെ ഇൻസ്റ്റാൾ ഒന്നിലധികം കമ്പനികളെ സേവിക്കുമ്പോൾ (ഉദാഹരണത്തിന് ഒന്നിലധികം ക്ലയന്റുകളെ പിന്തുണയ്ക്കുന്ന ഒരു IT പ്രൊവൈഡർ), ഓരോ കമ്പനിയുടെയും ടിക്കറ്റുകൾ വേറിട്ട് സൂക്ഷിക്കുന്നു. ഇൻബൗണ്ട് ഇമെയിൽ ശരിയായ കമ്പനിയെ എങ്ങനെ കണ്ടെത്തുന്നു എന്ന് ഈ വിഭാഗം വിശദീകരിക്കുന്നു.',
            'switcher_body' => 'ഒരു <strong>കമ്പനി സ്വിച്ചർ</strong> ഹെഡറിൽ ദൃശ്യമാകുന്നു. നിങ്ങൾ ജോലി ചെയ്യുന്ന കമ്പനി ഇത് സെറ്റ് ചെയ്യുന്നു &mdash; ടിക്കറ്റ് ലിസ്റ്റ്, ഫോൾഡറുകൾ, കൗണ്ടുകൾ എല്ലാം ആ കമ്പനി മാത്രം കാണിക്കുന്നു, നിങ്ങൾ സൃഷ്ടിക്കുന്ന ഏത് ടിക്കറ്റും അതിലേക്ക് ഫയൽ ചെയ്യപ്പെടും. ഒന്നിലധികം കമ്പനികളിലേക്ക് ആക്സസ് ഉള്ള സ്റ്റാഫിന് അവയ്ക്കിടയിൽ മാറാം; നിങ്ങൾ തെറ്റായ സന്ദർഭത്തിൽ മറുപടി നൽകാതിരിക്കാൻ നിലവിലുള്ളത് എപ്പോഴും കാണിക്കും. <strong>സിസ്റ്റം &rarr; കമ്പനികൾ</strong>-ന് കീഴിൽ കമ്പനികളെ തന്നെ മാനേജ് ചെയ്യുക.',
            'mailboxes_heading' => 'ഓരോ മെയിൽബോക്സും രണ്ട് തരങ്ങളിൽ ഒന്നാണ് &mdash; റൂട്ടിംഗ് തീരുമാനിക്കുന്നത് ഇതാണ്:',
            'card_pinned_title' => 'പിൻ ചെയ്ത മെയിൽബോക്സ്',
            'card_pinned_body' => 'ഒരു കമ്പനിക്ക് മാത്രമായി സമർപ്പിച്ചത് (ഉദാ. ഒരു ക്ലയന്റിന്റെ സ്വന്തം <code>itsupport@</code>). അതിന്റെ <strong>എല്ലാ</strong> മെയിലും ആ കമ്പനിയിലേക്ക് ഫയൽ ചെയ്യുന്നു &mdash; അയച്ചയാളെ അവഗണിക്കുന്നു &mdash; മറുപടികൾ അതിൽ നിന്ന് തന്നെ പുറത്തേക്ക് പോകുന്നു, അതിനാൽ ക്ലയന്റ് തുടക്കം മുതൽ ഒടുക്കം വരെ അവരുടെ സ്വന്തം ഹെൽപ്പ് ഡെസ്ക് കാണുന്നു.',
            'card_shared_title' => 'പങ്കിട്ട ഇൻടേക്ക് മെയിൽബോക്സ്',
            'card_shared_body' => 'ഒരു അഡ്രസ് പല കമ്പനികളെയും സേവിക്കുന്നു (ഉദാ. ഒരു പ്രൊവൈഡറിന്റെ ഒറ്റ <code>support@theprovider.com</code>). അഡ്രസിൽ നിന്ന് മാത്രം കമ്പനി അറിയാൻ കഴിയില്ല, അതിനാൽ <strong>ആരാണ് ഇമെയിൽ അയച്ചത്</strong> എന്നതിൽ നിന്ന് ഇത് കണ്ടെത്തുന്നു. ഒന്നിലധികം ക്ലയന്റുകളുള്ള ഒരു പ്രൊവൈഡറിന് ശുപാർശ ചെയ്യുന്ന സെറ്റപ്പ്.',
            'routing_heading' => 'ഒരു പങ്കിട്ട ഇൻടേക്ക് മെയിൽബോക്സ് കമ്പനി എങ്ങനെ തിരഞ്ഞെടുക്കുന്നു',
            'routing_body' => 'ഓരോ വരുന്ന ഇമെയിലിനും ഇത് ഇവയെ ക്രമത്തിൽ ശ്രമിക്കുന്നു, ആദ്യം പൊരുത്തപ്പെടുന്നത് ജയിക്കും:',
            'flow_reply' => 'ഒരു ടിക്കറ്റിനുള്ള മറുപടി',
            'flow_sender' => 'അറിയപ്പെടുന്ന അയച്ചയാൾ',
            'flow_domain' => 'അറിയപ്പെടുന്ന ഡൊമെയ്ൻ',
            'flow_triage' => 'ട്രയാജ്',
            'rule_reply' => '<strong>1. നിലവിലുള്ള ഒരു ടിക്കറ്റിനുള്ള മറുപടി</strong> &mdash; അതിന്റെ റഫറൻസ് വഴി തിരിച്ചറിഞ്ഞ്, ഇമെയിൽ ആ ടിക്കറ്റിൽ ചേരുകയും അതിന്റെ കമ്പനി സൂക്ഷിക്കുകയും ചെയ്യുന്നു.',
            'rule_sender' => '<strong>2. ഒരു കമ്പനിയിലേക്ക് മാപ്പ് ചെയ്ത ഒരു പ്രത്യേക അയച്ചയാളുടെ അഡ്രസ്</strong> (ഉദാ. <code>jane@gmail.com</code> &rarr; Acme) &mdash; ആ കമ്പനി. ഡൊമെയ്നിന് മുമ്പ് പരിശോധിക്കുന്നു, അതിനാൽ പേഴ്സണൽ/വെബ്മെയിൽ അഡ്രസുകൾക്കും ഇത് പ്രവർത്തിക്കും.',
            'rule_domain' => '<strong>3. ഒരു കമ്പനിയിലേക്ക് മാപ്പ് ചെയ്ത അയച്ചയാളുടെ ഡൊമെയ്ൻ</strong> (ഉദാ. <code>@acme.com</code>-ൽ നിന്നുള്ള ആരും &rarr; Acme) &mdash; ആ കമ്പനി.',
            'rule_triage' => '<strong>4. പൊരുത്തമില്ല</strong> &mdash; ഇമെയിൽ നഷ്ടപ്പെടുന്നതിന് പകരം <strong>ട്രയാജ്</strong> ക്യൂവിലേക്ക് പോകുന്നു (താഴെ കാണുക).',
            'keys_heading' => 'ഡൊമെയ്‌നുകൾ &amp; പ്രത്യേക അയച്ചയാൾ (സിസ്റ്റം &rarr; കമ്പനികൾക്ക് കീഴിൽ ഓരോ കമ്പനിക്കും സെറ്റ് ചെയ്യുന്നത്)',
            'keys_body' => 'ഒരു പങ്കിട്ട ഇൻടേക്ക് മെയിൽബോക്സ് പൊരുത്തപ്പെടുത്തുന്ന കീകൾ ഇവയാണ്. ഓരോ കമ്പനിയും അത് സ്വന്തമാക്കിയ ഇമെയിൽ ഡൊമെയ്‌നുകളും, ഇഷ്ടാനുസരണം, വ്യക്തിഗത അയച്ചയാളുടെ അഡ്രസുകളും ലിസ്റ്റ് ചെയ്യുന്നു.',
            'card_domains_title' => 'ഇമെയിൽ ഡൊമെയ്‌നുകൾ',
            'card_domains_body' => 'ഒരു കമ്പനി സ്വന്തമാക്കിയ ഡൊമെയ്‌നുകൾ (acme.com, acme.co.uk). രജിസ്റ്റർ ചെയ്ത ഒരു ഡൊമെയ്നിലെ ഏത് അയച്ചയാളും ആ കമ്പനിയിലേക്ക് റൂട്ട് ചെയ്യും. ഒരു ഡൊമെയ്ൻ ഒരു കമ്പനിക്ക് മാത്രം ഉള്ളതാണ്.',
            'card_senders_title' => 'പ്രത്യേക അയച്ചയാൾ',
            'card_senders_body' => 'ഒരു കമ്പനിയിലേക്ക് മാപ്പ് ചെയ്ത വ്യക്തിഗത അഡ്രസുകൾ, ഡൊമെയ്നിന് മുമ്പ് പരിശോധിക്കുന്നു. ഒരു ഫ്രീലാൻസറോ, ഒരു പേഴ്സണൽ അഡ്രസിൽ നിന്ന് ഇമെയിൽ ചെയ്യുന്ന ചെറിയ ക്ലയന്റോ ആണെങ്കിൽ ഇത് ഉപയോഗിക്കുക.',
            'card_public_title' => 'പൊതു പ്രൊവൈഡറുകൾ',
            'card_public_body' => 'Gmail, Outlook, Yahoo പോലുള്ളവയെ ഒരു ഡൊമെയ്നായി മാപ്പ് ചെയ്യാൻ കഴിയില്ല (ബന്ധമില്ലാത്ത നിരവധി ആളുകൾ അവ പങ്കിടുന്നു) &mdash; പകരം കൃത്യമായ അഡ്രസ് ഒരു പ്രത്യേക അയച്ചയാളായി മാപ്പ് ചെയ്യുക.',
            'triage_heading' => 'ട്രയാജ് ക്യൂ &mdash; സുരക്ഷാ വല',
            'triage_body' => 'ഒരു പങ്കിട്ട ഇൻടേക്ക് ഇമെയിൽ ഒരു കമ്പനിയുമായും പൊരുത്തപ്പെടാതെ വരുമ്പോൾ അത് നഷ്ടപ്പെടുന്നതിന് പകരം <strong>ട്രയാജിൽ</strong> (കമ്പനി സ്വിച്ചറിൽ നിന്ന്, ലൈവ് കൗണ്ടോടെ എത്തിച്ചേരാം) വന്നു വീഴുന്നു. ഓരോ ഇനവും അയച്ചയാൾ, ഡൊമെയ്ൻ, വിഷയം, ഏത് മെയിൽബോക്സിലാണ് എത്തിയത് എന്നിവ കാണിക്കുന്നു. ഒരു ഘട്ടത്തിൽ ഒരു കമ്പനിയിലേക്ക് ഫയൽ ചെയ്യുക:',
            'triage_create' => 'നിലവിലുള്ള ഒരു കമ്പനി തിരഞ്ഞെടുക്കുക, അല്ലെങ്കിൽ അപ്പോൾ തന്നെ ഒരു പുതിയത് സൃഷ്ടിക്കുക.',
            'triage_assign' => 'ഒരു സാധാരണ ഡൊമെയ്നിന്, ഇഷ്ടാനുസരണം ആ ഡൊമെയ്ൻ കമ്പനിയിലേക്ക് <strong>റൂട്ട് ചെയ്യുക</strong>; ഒരു പൊതു/വെബ്മെയിൽ അഡ്രസിന്, ഇഷ്ടാനുസരണം ആ അയച്ചയാളെ എപ്പോഴും അവിടെ <strong>ഫയൽ ചെയ്യുക</strong>.',
            'triage_sweep' => 'ഏത് തിരഞ്ഞെടുപ്പും <em>സ്വീപ്</em> ചെയ്യുന്നു: അത് ആ ഡൊമെയ്നിൽ നിന്നോ അഡ്രസിൽ നിന്നോ ഉള്ള ക്യൂവിലെ മറ്റെല്ലാ ഇമെയിലും കൂടി നീക്കുന്നു, ഭാവി മെയിൽ സ്വയമേവ റൂട്ട് ചെയ്യുകയും ചെയ്യുന്നു &mdash; അതിനാൽ ഒരു അയച്ചയാളെ നിങ്ങൾ ഒരിക്കൽ മാത്രം സോർട്ട് ചെയ്യേണ്ടതുള്ളൂ.',
            'triage_tip' => 'ഒന്നും ഒരിക്കലും നഷ്ടപ്പെടില്ല. പൊരുത്തപ്പെടാത്ത മെയിൽ ആരെങ്കിലും ഫയൽ ചെയ്യുന്നതുവരെ ട്രയാജിൽ കാത്തിരിക്കും; അതിനിടയിൽ ഫയൽ ചെയ്യാത്ത ഒരു ടിക്കറ്റ് ഇപ്പോഴും സ്ഥിരസ്ഥിതി കമ്പനിക്ക് കീഴിൽ കാണിക്കും.',
            'test_heading' => 'ലൈവ് ആകുന്നതിന് മുമ്പ് നിങ്ങളുടെ റൂട്ടിംഗ് ടെസ്റ്റ് ചെയ്യുക',
            'test_body' => '<strong>സിസ്റ്റം &rarr; ഇമെയിൽ റൂട്ടിംഗ് ടെസ്റ്റ്</strong>-ന് കീഴിൽ ഒരു ഇമെയിൽ വന്നു എന്ന് നടിക്കാം &mdash; ഒരു മെയിൽബോക്സ് തിരഞ്ഞെടുക്കുക, ഒരു അയച്ചയാളുടെ അഡ്രസ് ടൈപ്പ് ചെയ്യുക &mdash; പുതിയ ടിക്കറ്റ് കൃത്യമായി ഏത് കമ്പനിയിൽ വീഴുമെന്ന് (അല്ലെങ്കിൽ അത് ട്രയാജിലേക്ക് പോകുമെന്ന്) ഏത് നിയമമാണ് അത് തീരുമാനിച്ചതെന്നും കാണുക. ഇത് ഒന്നും സൃഷ്ടിക്കില്ല; ഇത് നിങ്ങളുടെ ക്രമീകരണങ്ങൾ വായിക്കുക മാത്രമേ ചെയ്യൂ.',
            'settings_heading' => 'ക്രമീകരണങ്ങൾ: സ്ഥിരസ്ഥിതിയായി പങ്കിട്ടത്, പ്രധാനമുള്ളിടത്ത് അനുയോജ്യമാക്കിയത്',
            'settings_body' => 'ഈ ക്രമീകരണങ്ങളിൽ ചിലത് <strong>ഓരോ കമ്പനിക്കും അനുയോജ്യമാക്കാം</strong>; മറ്റുള്ളവ മനഃപൂർവ്വം പങ്കിട്ടതായി തുടരും. ഒരു ക്രമീകരണം ഓപ്ഷനുകളുടെ ഒരു ലളിതമായ ലിസ്റ്റ് ആണെങ്കിൽ &mdash; <strong>ടിക്കറ്റ് തരങ്ങൾ</strong>, <strong>ഒറിജിനുകൾ</strong> പോലുള്ളവ &mdash; ഒരു കമ്പനിയുടെ സന്ദർഭത്തിലേക്ക് മാറുക, പങ്കിട്ട സ്ഥിരസ്ഥിതികൾ (ഉപയോഗിക്കാത്തവ മറയ്ക്കാൻ ഓരോന്നിനും ഒരു കണ്ണ് ഐക്കണോടെ) കൂടാതെ അതിന് സ്വന്തമായി ചേർത്തതും നിങ്ങൾ കാണും. തുറന്ന ടിക്കറ്റുകൾ ഇപ്പോഴും ഒരു ഓപ്ഷൻ ഉപയോഗിക്കുമ്പോൾ അത് മറയ്ക്കാനോ ഡിലീറ്റ് ചെയ്യാനോ കഴിയില്ല, പങ്കിട്ട സ്ഥിരസ്ഥിതികൾ തന്നെ MSP / സ്ഥിരസ്ഥിതി കമ്പനിയിൽ നിന്ന് എഡിറ്റ് ചെയ്യുന്നു.',
            'settings_custom_title' => 'ഓരോ കമ്പനിക്കും അനുയോജ്യമാക്കിയത്',
            'settings_custom_body' => 'ടിക്കറ്റ് തരങ്ങൾ &amp; ഒറിജിനുകൾ (ഇപ്പോൾ), വിഭാഗങ്ങൾ, SLA-കൾ &amp; ബിസിനസ് സമയങ്ങൾ (വരാനിരിക്കുന്നത്) &mdash; ഒരു ക്ലയന്റിൽ നിന്ന് അടുത്തതിലേക്ക് യഥാർത്ഥത്തിൽ വ്യത്യാസമുള്ള കാര്യങ്ങൾ.',
            'settings_global_title' => 'എല്ലാ കമ്പനിക്കും പങ്കിട്ടത്',
            'settings_global_body' => 'നിലകളും മുൻഗണനകളും എല്ലായിടത്തും ഒരുപോലെ തുടരും, അതിനാൽ ക്രോസ്-കമ്പനി റിപ്പോർട്ടിംഗും SLA-കളും സ്ഥിരതയുള്ളതായി തുടരും; നിങ്ങളുടെ ടീമുകൾ, റോട്ട, മെയിൽബോക്സുകൾ എന്നിവയും അങ്ങനെ തന്നെ &mdash; ഒരു ക്ലയന്റിന്റേതല്ല, നിങ്ങളുടെ സ്വന്തം പ്രവർത്തനമാണ്.',
            'allview_heading' => '<strong>എല്ലാ കമ്പനിക്കും ഒരു ബോർഡ്</strong>',
            'allview_body' => 'ഹെഡറിലെ കമ്പനി സ്വിച്ചറിന് <strong>എല്ലാ കമ്പനികളും</strong> എന്ന ഓപ്ഷൻ ഉണ്ട്. നിങ്ങൾക്ക് കാണാൻ അനുവാദമുള്ള എല്ലാ ടിക്കറ്റും ഒരു ലിസ്റ്റിൽ പ്രത്യക്ഷപ്പെടുന്നു, ഓരോ വരിയും അത് ഉൾപ്പെടുന്ന കമ്പനി ധരിച്ചിരിക്കുന്നു &mdash; നിങ്ങൾ ഒന്നിലധികം എന്റിറ്റികളെ പിന്തുണയ്ക്കുകയും ആരുടേത് ഏതെന്ന് കൈവിടാതെ ദിവസത്തിന്റെ ഒറ്റ കാഴ്ച വേണമെന്നും ഇരിക്കുമ്പോൾ ഉപകാരപ്രദമാണ്.',
            'allview_card_scope_title' => 'ഇത് പുതിയതായി ഒന്നും അനുവദിക്കുന്നില്ല',
            'allview_card_scope_body' => '"All" എന്നാൽ നിങ്ങൾക്ക് ഇതിനകം ഒന്നൊന്നായി എത്താൻ കഴിയുന്ന എല്ലാ കമ്പനിയും എന്നാണ്. നിങ്ങളുടെ മൂന്ന് എന്റിറ്റികളിൽ രണ്ടിനെ പിന്തുണയ്ക്കുന്ന ഒരു അനലിസ്റ്റ് കൃത്യമായി ആ രണ്ടും കാണുന്നു, ഒരു കമ്പനി മാത്രമുള്ള ഒരു അനലിസ്റ്റ് ആ ഒരു കമ്പനിയുടെ കാഴ്ച കാണുന്നു.',
            'allview_card_props_title' => 'ഓരോ എന്റിറ്റിയും വേറിട്ട് നിൽക്കുന്നു',
            'allview_card_props_body' => 'ഒരു ടിക്കറ്റ് തുറന്നാൽ അതിന്റെ തരം, ഒറിജിൻ, വിഭാഗം, റെസലൂഷൻ ലിസ്റ്റ് എന്നിവ <em>ആ</em> കമ്പനിക്ക് ഉള്ളവയാണ് &mdash; അതിനാൽ ഒരു എന്റിറ്റിക്ക് ഉള്ളതും മറ്റൊന്നിന് ഇല്ലാത്തതുമായ ഒരു വിഭാഗം ഒരിക്കലും തെറ്റായ ടിക്കറ്റിൽ പ്രയോഗിക്കാൻ കഴിയില്ല.',
            'allview_card_new_title' => 'പുതിയ ടിക്കറ്റുകൾ ഏത് കമ്പനി എന്ന് ചോദിക്കും',
            'allview_card_new_body' => 'അനുമാനിക്കാൻ ഒരു ഒറ്റ സജീവ കമ്പനി ഇല്ല, തിരഞ്ഞെടുപ്പ് ടിക്കറ്റ് നമ്പർ, മറുപടികൾ വരുന്ന മെയിൽബോക്സ്, ബാധകമാകുന്ന SLA എന്നിവ തീരുമാനിക്കുന്നു. നിങ്ങൾ തിരഞ്ഞെടുത്തുകഴിഞ്ഞാൽ തരം ലിസ്റ്റ് പൂരിപ്പിക്കും.',
            'allview_rule_chip' => 'ഇമെയിൽ വഴിയോ പോർട്ടൽ വഴിയോ വന്ന, ഇതുവരെ റൂട്ട് ചെയ്യാത്ത ഒരു ടിക്കറ്റ്, സ്ഥിരസ്ഥിതിക്ക് കീഴിൽ കാണിക്കുന്നതിന് പകരം <strong>റൂട്ട് ചെയ്യാത്തത്</strong> എന്ന് അടയാളപ്പെടുത്തും, അതിനാൽ ഇത് ട്രയാജിനായി വേറിട്ട് നിൽക്കും.',
            'allview_rule_reply' => 'മറുപടികൾ ഇപ്പോഴും ടിക്കറ്റ് എത്തിയ മെയിൽബോക്സിൽ നിന്നാണ് പോകുന്നത് &mdash; അത് ടിക്കറ്റിനെ പിന്തുടരുന്നു, കാഴ്ചയെ അല്ല, അതിനാൽ ഒരു സംയോജിത ബോർഡിന് തെറ്റായ അഡ്രസിൽ നിന്ന് അയക്കാൻ കഴിയില്ല.',
            'allview_rule_knowledge' => '<strong>Ask AI</strong> സംയോജിത കാഴ്ച ഓണായിരിക്കുമ്പോൾ ഒന്നിന് പകരം നിങ്ങൾക്ക് കാണാൻ കഴിയുന്ന എല്ലാ കമ്പനിയിലും തിരയുന്നു. എല്ലാ കമ്പനികളുമായി പങ്കിട്ട ആർട്ടിക്കിളുകൾ ഏത് വിധത്തിലും ഉൾപ്പെടും.',
            'allview_rule_trash' => '<strong>ട്രാഷ് ശൂന്യമാക്കുന്നത് ഒരിക്കലും കമ്പനികളിലുടനീളം വ്യാപിക്കില്ല.</strong> ഇത് എപ്പോഴും നിങ്ങൾ അവസാനം തിരഞ്ഞെടുത്ത ഒറ്റ കമ്പനിക്ക് മാത്രമേ ബാധകമാകൂ, കാരണം ഒന്നിലധികം എന്റിറ്റികളിലുടനീളം ഒരേസമയം "ബിന്നിലെ എല്ലാം ഡിലീറ്റ് ചെയ്യുക" എന്നത് ആരും അതുകൊണ്ട് ഉദ്ദേശിക്കുന്നതല്ല.',
            'allview_rule_other' => 'ടിക്കറ്റ് ലിസ്റ്റ് മാത്രമേ വിശാലമാകുന്നുള്ളൂ. ആസ്തികൾ, മാറ്റങ്ങൾ, ടാസ്കുകൾ, CMDB എന്നിവ ഇപ്പോഴും ഒരു സമയത്ത് ഒരു കമ്പനി മാത്രം കാണിക്കും &mdash; അവയിൽ ജോലി ചെയ്യാൻ ആ കമ്പനിയിലേക്ക് മാറുക.',
            'privacy_heading' => 'ഓരോ കമ്പനിയുടെയും ടിക്കറ്റുകൾ സ്വകാര്യമായി തുടരും',
            'privacy_body' => 'ഒരു കമ്പനിയുടെ സന്ദർഭത്തിൽ ജോലി ചെയ്യുമ്പോൾ നിങ്ങൾ <strong>ആ</strong> കമ്പനിയുടെ ടിക്കറ്റുകൾ മാത്രമേ എപ്പോഴും കാണൂ &mdash; ലിസ്റ്റിലും, തിരയലിലും, ഡാഷ്ബോർഡുകളിലും, നിങ്ങൾ തുറക്കുന്ന ഓരോ ടിക്കറ്റിലും (അതിന്റെ ഇമെയിലുകൾ, അറ്റാച്ച്മെന്റുകൾ, കുറിപ്പുകൾ, ചരിത്രം ഉൾപ്പെടെ). ഒരു സ്റ്റാഫ് അംഗത്തിന് അതിന്റെ കമ്പനിയിലേക്ക് ആക്സസ് നൽകിയിട്ടുണ്ടെങ്കിൽ മാത്രമേ ഒരു ടിക്കറ്റിലേക്ക് എത്താൻ കഴിയൂ (സിസ്റ്റം &rarr; അനലിസ്റ്റുകൾക്ക് കീഴിൽ ഓരോ അനലിസ്റ്റിന്റെയും കമ്പനികൾ നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നു, അല്ലെങ്കിൽ സിസ്റ്റം &rarr; ടീമുകളിൽ ഒരു മുഴുവൻ ടീമിനും അനുവദിക്കുന്നു), അതിനാൽ മറ്റൊരു ക്ലയന്റിന്റെ ഡാറ്റയിലേക്ക് വഴിതെറ്റാൻ ഒരു വഴിയുമില്ല. ഈ വേർതിരിവ് കാഴ്ചയിൽ നിന്ന് മറയ്ക്കുക മാത്രമല്ല, പിന്നണിയിൽ എല്ലായിടത്തും നടപ്പിലാക്കുന്നു. ഒരു ഒറ്റ-കമ്പനി ഇൻസ്റ്റാളിൽ ഇത് സ്വയമേവയും അദൃശ്യവുമാണ് &mdash; ഒരു കമ്പനി മാത്രമേയുള്ളൂ, അതിനാൽ എല്ലാം അതിന്റേതായി തുടരും.',
            'tip' => 'ഒരു ഒറ്റ-കമ്പനി ഇൻസ്റ്റാളിൽ ഇതൊന്നും ദൃശ്യമാകില്ല &mdash; ഒരു കമ്പനിയേ ഉള്ളൂ, ഓരോ ടിക്കറ്റും അതിന്റേതാണ്, സ്വിച്ചറോ ട്രയാജോ ഇല്ല. രണ്ടാമത്തെ കമ്പനി നിലവിൽ വരുമ്പോൾ മാത്രമേ ഈ ഫീച്ചറുകൾ ഓണാകൂ.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'സർവീസ് ഡെസ്ക് - SLA മാനേജ്മെന്റ്',
