        'sidebar_title' => 'SLA ഗൈഡ്',
        'hero_title' => 'SLA മാനേജ്മെന്റ്',
        'hero_sub' => 'ബിസിനസ് സമയം കണക്കിലെടുക്കുന്ന റെസ്പോൺസ്, റെസലൂഷൻ ടാർഗെറ്റുകൾ, ഓരോ വകുപ്പിനും പ്രത്യേകം ബ്രീച്ച് അറിയിപ്പുകളോടെ',
        'nav' => [
            'overview' => 'അവലോകനം',
            'building_blocks' => 'നിർമ്മാണ ഘടകങ്ങൾ',
            'behaviour_settings' => 'പെരുമാറ്റ ക്രമീകരണങ്ങൾ',
            'breach_notifications' => 'ബ്രീച്ച് അറിയിപ്പുകൾ',
            'cron_setup' => 'ക്രോൺ ജോലി സജ്ജീകരണം',
            'worked_examples' => 'പ്രവർത്തിപ്പിച്ച ഉദാഹരണങ്ങൾ',
            'troubleshooting' => 'ട്രബിൾഷൂട്ടിംഗ്',
        ],
        'overview' => [
            'heading' => 'അവലോകനം',
            'sub' => 'SLA-കൾ എന്താണ്, അവ പ്രധാനമായിരിക്കുന്നത് എന്തുകൊണ്ട്, FreeITSM എൻജിൻ പൊതുവേ എങ്ങനെ പ്രവർത്തിക്കുന്നു എന്നത്.',
            'p1' => 'ഒരു ടിക്കറ്റിന് നിങ്ങളുടെ ടീം എത്ര വേഗത്തിൽ പ്രതികരിക്കുകയും അത് പരിഹരിക്കുകയും ചെയ്യും എന്നതിനെക്കുറിച്ചുള്ള ഒരു വാഗ്ദാനമാണ് സർവീസ് ലെവൽ എഗ്രിമെന്റ് (SLA). FreeITSM ഓരോ ടിക്കറ്റിനും രണ്ട് ക്ലോക്കുകൾ ട്രാക്ക് ചെയ്യുന്നു: <strong>റെസ്പോൺസ്</strong> (ടിക്കറ്റ് സൃഷ്ടിച്ചത് മുതൽ ആദ്യത്തെ അനലിസ്റ്റ് നടപടി വരെയുള്ള സമയം), <strong>റെസലൂഷൻ</strong> (ടിക്കറ്റ് സൃഷ്ടിച്ചത് മുതൽ ടിക്കറ്റ് അടയ്ക്കുന്നത് വരെയുള്ള സമയം). രണ്ട് ടാർഗെറ്റുകളും ഓരോ മുൻഗണനയ്ക്കും അനുസരിച്ച് സജ്ജമാക്കും &mdash; അതിനാൽ ഒരു P1-ന് റെസ്പോൺസിന് 30 മിനിറ്റും റെസലൂഷന് 4 മണിക്കൂറും ഉണ്ടാകാം, ഒരു P4-ന് 8 പ്രവൃത്തി മണിക്കൂറും 5 പ്രവൃത്തി ദിവസങ്ങളും ഉണ്ടാകാം.',
            'p2' => 'FreeITSM-ന്റെ SLA എൻജിനിൽ മനസ്സിലാക്കേണ്ട നാല് ഡിസൈൻ തീരുമാനങ്ങളുണ്ട്:',
            'choice_business' => '<strong>ബിസിനസ് സമയം, വാൾ ക്ലോക്ക് അല്ല.</strong> 4:30pm-ന് ഉയർത്തിയ, 1 മണിക്കൂർ റെസ്പോൺസ് ടാർഗെറ്റുള്ള ഒരു P2, ഓഫീസ് 5pm-ന് അടയ്ക്കുകയാണെങ്കിൽ 5:30pm-ന് ബ്രീച്ച് ആകില്ല. അടുത്ത പ്രവൃത്തി ദിവസം രാവിലെ 9am-ന് ക്ലോക്ക് വീണ്ടും തുടങ്ങും. ഇതാണ് വ്യവസായ നിലവാരം, അനലിസ്റ്റുകൾ രാത്രി വീട്ടിലേക്ക് പോകുമ്പോൾ നീതിയുള്ള ഒരേയൊരു മാതൃകയും ഇതാണ്.',
            'choice_pause' => '<strong>നിർത്തിവയ്ക്കാവുന്നത്.</strong> ഒരു ടിക്കറ്റ് "Pause SLA" എന്ന് ഫ്ലാഗ് ചെയ്ത ഒരു നിലയിലാകുമ്പോൾ (<em>Awaiting Response</em> അല്ലെങ്കിൽ <em>On Hold</em> പോലെ), ക്ലോക്ക് നിലയ്ക്കും. ടിക്കറ്റ് ഒരു പ്രവർത്തന നിലയിലേക്ക് തിരികെ പോകുമ്പോൾ അത് വീണ്ടും തുടങ്ങും.',
            'choice_compute' => '<strong>വായിക്കുമ്പോൾ കണക്കാക്കുന്നത്, സൂക്ഷിച്ചതല്ല.</strong> നിങ്ങൾ ഓരോ തവണ നോക്കുമ്പോഴും ടിക്കറ്റ് ഓഡിറ്റ് ലോഗിൽ നിന്ന് എൻജിൻ SLA അവസ്ഥ വീണ്ടും കണക്കാക്കുന്നു. സമന്വയം തെറ്റാവുന്ന സൂക്ഷിച്ച കൗണ്ടറുകളൊന്നും ഇല്ല. നിങ്ങൾ പിന്നീട് ഒരു ബിസിനസ് കലണ്ടറിന്റെ സമയം മാറ്റിയാൽ, അടുത്ത തവണ കാണുമ്പോൾ എല്ലാ പഴയ ടിക്കറ്റുകളുടെയും SLA പുതിയ സമയത്തിനെതിരെ വീണ്ടും കണക്കാക്കും.',
            'choice_cutoff' => '<strong>എൻഫോഴ്സ്മെന്റ് കട്ട്ഓഫ്.</strong> അഡ്മിൻ നിയന്ത്രിക്കുന്ന "Enforce SLAs from" തീയതി അർത്ഥമാക്കുന്നത്, നിങ്ങൾ SLA-കൾ ഓണാക്കുമ്പോൾ നിങ്ങളുടെ സിസ്റ്റത്തിലെ നിലവിലുള്ള ടിക്കറ്റുകൾ പെട്ടെന്ന് മുൻകാല പ്രാബല്യത്തോടെ ബ്രീച്ച് ആകില്ല എന്നാണ്. കട്ട്ഓഫിന് ശേഷമോ അന്നോ സൃഷ്ടിച്ച ടിക്കറ്റുകൾ മാത്രമേ ട്രാക്ക് ചെയ്യൂ.',
            'tip' => 'നിങ്ങൾ ITIL-ന് പുതിയതാണെങ്കിൽ: റെസ്പോൺസ് സമയം അക്നോളജ്മെന്റിനെക്കുറിച്ചാണ് (ആരെങ്കിലും അത് ഏറ്റെടുത്തു); റെസലൂഷൻ സമയം പൂർത്തീകരണത്തെക്കുറിച്ചാണ് (ഉപയോക്താവിന്റെ പ്രശ്നം പരിഹരിച്ചു). രണ്ട് ക്ലോക്കുകളും സ്വതന്ത്രമായി പ്രവർത്തിക്കുന്നു, വ്യത്യസ്ത ടാർഗെറ്റുകളുമുണ്ട്.',
        ],
        'blocks' => [
            'heading' => 'നാല് നിർമ്മാണ ഘടകങ്ങൾ',
            'sub' => 'ഈ നാല് കാര്യങ്ങൾ ക്രമീകരിച്ചാൽ SLA ട്രാക്കിംഗ് പ്രവർത്തനക്ഷമമാകും. ബാക്കിയെല്ലാം ഓപ്ഷണൽ മെച്ചപ്പെടുത്തലുകളാണ്.',
            'cal_heading' => '1. ബിസിനസ് കലണ്ടറുകൾ',
            'cal_intro' => 'നിങ്ങളുടെ സർവീസ് ഡെസ്ക് എപ്പോൾ തുറന്നിരിക്കുമെന്ന് ഒരു കലണ്ടർ നിർവചിക്കുന്നു. ഓരോ കലണ്ടറിനും ഇവയുണ്ട്:',
            'cal_tz' => '<strong>ടൈംസോൺ</strong> &mdash; ഒരു IANA ടൈംസോൺ ഐഡന്റിഫയർ (ഉദാ. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). DST മാറ്റങ്ങൾ സ്വയമേവ കൈകാര്യം ചെയ്യും.',
            'cal_hours' => '<strong>പ്രതിവാര പ്രവൃത്തി സമയം</strong> &mdash; ഓരോ ആഴ്ചദിവസത്തിനും ഒരു Open ചെക്ക്ബോക്സും ആരംഭ / അവസാന സമയങ്ങളുമുള്ള ഒരു വരി. പുതിയ കലണ്ടറുകൾ സ്ഥിരസ്ഥിതിയായി തിങ്കൾ-വെള്ളി 09:00-17:00, ശനി/ഞായർ അടച്ചിരിക്കും. Open ഫ്ലാഗ് ചെയ്യാത്ത ഒരു വരി അർത്ഥമാക്കുന്നത് ആ ദിവസം ഡെസ്ക് അടച്ചിരിക്കും എന്നാണ്.',
            'cal_holidays' => '<strong>അവധി ദിവസങ്ങൾ</strong> &mdash; തീയതി + ഓപ്ഷണൽ പേര്. അവധി ദിവസങ്ങൾ പ്രതിവാര പാറ്റേണിനെ അസാധുവാക്കും (തിങ്കളാഴ്ചയാണെങ്കിൽ പോലും ഡെസ്ക് അടച്ചിരിക്കും).',
            'cal_default' => '<strong>സ്ഥിരസ്ഥിതി ഫ്ലാഗ്</strong> &mdash; കൃത്യം ഒരു കലണ്ടർ മാത്രമേ സ്ഥിരസ്ഥിതി ആയിരിക്കൂ. നിങ്ങൾ വേറെ വ്യക്തമാക്കിയില്ലെങ്കിൽ പുതിയ മുൻഗണനകൾ ഇത് പാരമ്പര്യമായി സ്വീകരിക്കും.',
            'cal_outro' => 'നിങ്ങൾക്ക് വേണ്ടത്ര കലണ്ടറുകൾ സൃഷ്ടിക്കാം &mdash; ഒന്ന് ഓരോ ഓഫീസിനും, ഒന്ന് ഓരോ ടീമിനും, നീട്ടിയ സമയമുള്ള VIP കസ്റ്റമേഴ്സിന് ഒന്ന്. SLA ടാർഗെറ്റുകളും ബ്രീച്ച്-ചെക്ക് എൻജിനും അവ പങ്കിടുന്നു.',
            'prio_heading' => '2. SLA ടാർഗെറ്റുകളുള്ള മുൻഗണനകൾ',
            'prio_intro' => 'മുൻഗണനകൾ ടാബിൽ (അല്ലെങ്കിൽ SLA ടാബിലെ SLA ടാർഗെറ്റുകൾ പട്ടിക വഴി), ഓരോ മുൻഗണനയ്ക്കും ഇവ ഉണ്ടാകാം:',
            'prio_response' => '<strong>റെസ്പോൺസ് ടാർഗെറ്റ് (മിനിറ്റുകൾ)</strong> &mdash; ആദ്യത്തെ അനലിസ്റ്റ് നടപടി വരെ എത്ര സമയം.',
            'prio_resolution' => '<strong>റെസലൂഷൻ ടാർഗെറ്റ് (മിനിറ്റുകൾ)</strong> &mdash; ടിക്കറ്റ് അടയ്ക്കുന്നത് വരെ എത്ര സമയം.',
            'prio_calendar' => '<strong>കലണ്ടർ</strong> &mdash; ഈ മുൻഗണനയുടെ ക്ലോക്ക് ഏത് ബിസിനസ് കലണ്ടറിനെതിരെ പ്രവർത്തിക്കും. സ്ഥിരസ്ഥിതി കലണ്ടർ ഉപയോഗിക്കാൻ ശൂന്യമായി വിടുക.',
            'prio_outro' => 'രണ്ട് ടാർഗെറ്റ് ഫീൽഡുകളും ശൂന്യമായി വിട്ടാൽ ആ മുൻഗണനയ്ക്ക് SLA ട്രാക്കിംഗ് പൂർണ്ണമായും പ്രവർത്തനരഹിതമാകും &mdash; സമയ സമ്മർദ്ദമില്ലാത്ത "Informational" അല്ലെങ്കിൽ "Backlog" മുൻഗണനയ്ക്ക് ഉപകാരപ്രദം.',
            'pause_heading' => '3. Pause SLA നിലകൾ',
            'pause_intro' => 'നിലകൾ ടാബിൽ ഒരു പ്രത്യേക "Pause SLA" കോളം ഉണ്ട്. ടീമിന്റെ നിയന്ത്രണത്തിന് പുറത്തുള്ള എന്തിനെയെങ്കിലും കാരണം ടിക്കറ്റ് തടസ്സപ്പെട്ടിരിക്കുന്നു എന്ന് സൂചിപ്പിക്കുന്ന ഏത് നിലയും ഫ്ലാഗ് ചെയ്യുക. സാധാരണ സ്ഥാനാർത്ഥികൾ:',
            'pause_awaiting' => '<strong>Awaiting Response</strong> &mdash; കസ്റ്റമർ നമുക്ക് വിവരം തരാനുണ്ട്. ഏതാണ്ട് സാർവത്രികമായി ന്യായമായ ഒരു പോസ് ആയി അംഗീകരിക്കപ്പെടുന്നു.',
            'pause_vendor' => '<strong>On Hold (Vendor)</strong> &mdash; Microsoft / മൂന്നാം കക്ഷി പിന്തുണയ്ക്കായി കാത്തിരിക്കുന്നു.',
            'pause_change' => '<strong>On Hold (Change Window)</strong> &mdash; ഭാവിയിലെ ഒരു മെയിന്റനൻസ് വിൻഡോയ്ക്കായി ഷെഡ്യൂൾ ചെയ്തിരിക്കുന്നു.',
            'pause_parts' => '<strong>On Hold (Parts)</strong> &mdash; ഹാർഡ്‌വെയർ ഡെലിവറിക്കായി കാത്തിരിക്കുന്നു.',
            'pause_warn' => 'ഒരു ടിക്കറ്റ് ബുദ്ധിമുട്ടുള്ളതാകുമ്പോഴോ അനലിസ്റ്റ് തിരക്കിലാകുമ്പോഴോ ഒരു പൊതുവായ "On Hold" നില SLA-യിൽ നിന്ന് രക്ഷപ്പെടാനുള്ള വാൽവായി ദുരുപയോഗം ചെയ്യപ്പെടാം. നിങ്ങളുടെ ടീമിന് അച്ചടക്കമുണ്ടെങ്കിൽ ഇത് കുഴപ്പമില്ല. ഇല്ലെങ്കിൽ, മുകളിൽ പറഞ്ഞ കൂടുതൽ നിർദ്ദിഷ്ടമായ വകഭേദങ്ങൾ ഉപയോഗിക്കുന്നത് പരിഗണിക്കുക, അല്ലെങ്കിൽ 24 മണിക്കൂറിലധികം പോസ് ചെയ്ത ടിക്കറ്റുകൾ ഒരു ആംബർ അലേർട്ടായി ഫ്ലാഗ് ചെയ്യുന്ന <strong>Watchtower</strong> ഡാഷ്‌ബോർഡിനെ ആശ്രയിക്കുക.',
            'cutoff_heading' => '4. എൻഫോഴ്സ്മെന്റ് കട്ട്ഓഫ് (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'ഏറ്റവും പ്രധാനപ്പെട്ട ആഗോള ക്രമീകരണം. ഇവിടെ ഒരു തീയതി/സമയം സജ്ജമാക്കുന്നത് വരെ SLA ട്രാക്കിംഗ് പൂർണ്ണമായും പ്രവർത്തനരഹിതമാണ് &mdash; ക്ലോക്കുകളൊന്നും പ്രവർത്തിക്കില്ല, ഇൻബോക്സിൽ പില്ലുകളൊന്നും കാണിക്കില്ല, ബ്രീച്ച് ഇമെയിലുകളൊന്നും അയക്കില്ല. ഇത് ഒരു മുൻകാല തീയതി/സമയത്തിലേക്ക് സജ്ജമാക്കിയാൽ അന്ന് മുതൽ മുൻകാല പ്രാബല്യത്തോടെ SLA-കൾ ഓണാകും. ഭാവിയിലെ ഒരു തീയതി/സമയത്തിലേക്ക് സജ്ജമാക്കിയാൽ ഒരു സ്വിച്ച്-ഓൺ ഷെഡ്യൂൾ ചെയ്യും.',
            'cutoff_p2' => 'മിക്ക ടീമുകളും SLA-കൾ ആദ്യമായി പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ ഇത് "ഇപ്പോൾ" ആയി സജ്ജമാക്കുന്നു &mdash; നിലവിലുള്ള ടിക്കറ്റുകൾ അവയുടെ SLA-ക്ക് മുമ്പുള്ള അവസ്ഥ നിലനിർത്തും, ആ നിമിഷം മുതൽ പുതിയ ടിക്കറ്റുകൾ ട്രാക്ക് ചെയ്യും.',
        ],
        'behaviour' => [
            'heading' => 'പെരുമാറ്റ ക്രമീകരണങ്ങൾ',
            'sub' => 'എൻജിൻ എഡ്ജ് കേസുകളോട് എങ്ങനെ പ്രതികരിക്കുന്നു എന്ന് ഇവ നിയന്ത്രിക്കുന്നു. സ്ഥിരസ്ഥിതികൾ യുക്തിസഹമാണ് &mdash; നിങ്ങൾക്ക് ഒരു പ്രത്യേക മുൻഗണനയുണ്ടെങ്കിൽ മാത്രമേ ഇവ വീണ്ടും പരിശോധിക്കേണ്ടതുള്ളൂ.',
            'prio_heading' => 'മുൻഗണന ഇടയ്ക്ക് മാറുമ്പോൾ',
            'prio_intro' => 'ഒരു P3 ടിക്കറ്റ് പകുതി വഴിയിൽ P1 ആയി അപ്ഗ്രേഡ് ചെയ്താൽ (പ്രശ്നം കരുതിയതിലും വലുതാണെന്ന് കണ്ടെത്തിയതിനാൽ), മൂന്ന് ന്യായമായ പെരുമാറ്റങ്ങളുണ്ട്:',
            'prio_forward' => '<strong>Forward (സ്ഥിരസ്ഥിതി)</strong> &mdash; സഞ്ചയിച്ച ബിസിനസ് മിനിറ്റുകൾ സൂക്ഷിച്ച് വെറും റീ-ടാർഗെറ്റ് ചെയ്യുക. ടിക്കറ്റ് അതിന്റെ 8മണിക്കൂർ P3 ടാർഗെറ്റിന്റെ 2 മണിക്കൂർ ഉപയോഗിച്ചിരുന്നെങ്കിൽ, ഇപ്പോൾ അതിന്റെ 1 മണിക്കൂർ P1 ടാർഗെറ്റിനെതിരെ 2 മണിക്കൂർ ഉപയോഗിച്ചതായി കണക്കാക്കും &mdash; അതായത് ഇത് ഇതിനകം ബ്രീച്ച് ആയി. ഇത് ശരിയാണെന്ന് വാദിക്കാം: പ്രശ്നം എല്ലായ്പ്പോഴും ഒരു P1 ആയിരുന്നു, ടീം അത് തിരിച്ചറിഞ്ഞില്ല എന്ന് മാത്രം.',
            'prio_recompute' => '<strong>Recompute</strong> &mdash; ക്ലോക്ക് റീസെറ്റ് ചെയ്ത് ടിക്കറ്റ് സൃഷ്ടിച്ചത് മുതൽ മുൻകാല പ്രാബല്യത്തോടെ പുതിയ ടാർഗെറ്റ് ബാധകമാക്കുക. ഒരു വൃത്തിയുള്ള പുനഃകണക്കാക്കൽ.',
            'prio_reset' => '<strong>Reset</strong> &mdash; മുൻഗണന മാറിയ നിമിഷം മുതൽ പുതിയ ക്ലോക്ക് പുതുതായി തുടങ്ങുക. ടീമിന് ഏറ്റവും ദയാപൂർവ്വം, പക്ഷേ ഒരു ഉയർന്ന മുൻഗണനയുള്ള ടിക്കറ്റിന് പെട്ടെന്ന് ഒരു പുതിയ നീണ്ട ക്ലോക്ക് കിട്ടിയാൽ കസ്റ്റമേഴ്സിന് വഞ്ചിക്കപ്പെട്ടതായി തോന്നാം.',
            'reopen_heading' => 'അടച്ച ഒരു ടിക്കറ്റ് വീണ്ടും തുറക്കുമ്പോൾ',
            'reopen_intro' => 'ഒരു ടിക്കറ്റ് വീണ്ടും തുറന്നാൽ (അടച്ചതിന് ശേഷം ഉപയോക്താവ് മറുപടി നൽകിയാൽ):',
            'reopen_reset' => '<strong>Reset (സ്ഥിരസ്ഥിതി)</strong> &mdash; വീണ്ടും തുറന്ന നിമിഷം മുതൽ പുതിയ റെസ്പോൺസ്, റെസലൂഷൻ ക്ലോക്കുകൾ തുടങ്ങുക. വീണ്ടും തുറക്കുന്നതിനെ ഫലത്തിൽ ഒരു പുതിയ ടിക്കറ്റായി കണക്കാക്കുക.',
            'reopen_continue' => '<strong>Continue</strong> &mdash; അടച്ച സമയത്തെ കഴിഞ്ഞ സമയത്തിൽ നിന്ന് തുടരുക. യഥാർത്ഥ SLA ടാർഗെറ്റുകൾ തുടർന്നും ബാധകമാകും.',
            'first_heading' => 'ആദ്യ റെസ്പോൺസിന്റെ നിർവചനം',
            'first_intro' => '"ആദ്യ റെസ്പോൺസ്" ആയി കണക്കാക്കുന്നത് എന്താണ് &mdash; റെസ്പോൺസ് ക്ലോക്ക് നിർത്തുന്ന നിമിഷം?',
            'first_either' => '<strong>Either (സ്ഥിരസ്ഥിതി)</strong> &mdash; ഏത് തരത്തിലുമുള്ള ആദ്യത്തെ അനലിസ്റ്റ് നടപടി: ഒരു ഔട്ട്ബൗണ്ട് ഇമെയിൽ, ഒരു നില മാറ്റം, ഒരു അസൈൻമെന്റ്.',
            'first_status' => '<strong>Status change</strong> &mdash; സ്ഥിരസ്ഥിതിയിൽ നിന്ന് മാറുന്ന ഒരു നില മാറ്റം മാത്രമേ കണക്കാക്കൂ. കൂടുതൽ കർശനം &mdash; അനലിസ്റ്റ് ടിക്കറ്റിൽ യഥാർത്ഥത്തിൽ പ്രവർത്തിച്ചിരിക്കണം, വെറും ക്ലിക്ക് ചെയ്താൽ പോരാ.',
            'first_email' => '<strong>Outbound email</strong> &mdash; അഭ്യർത്ഥിച്ചയാൾക്ക് ഒരു ഇമെയിൽ മറുപടി മാത്രമേ കണക്കാക്കൂ. ഏറ്റവും കർശനം &mdash; കസ്റ്റമർ നമ്മളിൽ നിന്ന് കേട്ടിരിക്കണം.',
            'warn_heading' => 'മുന്നറിയിപ്പ് ത്രെഷോൾഡ് ശതമാനം',
            'warn_body' => 'ഇൻഡിക്കേറ്റർ പച്ചയിൽ നിന്ന് ആംബറിലേക്ക് മാറുന്നതിന് മുമ്പ് SLA ടാർഗെറ്റിൽ എത്രത്തോളം എത്തിയിരിക്കണം. സ്ഥിരസ്ഥിതി 80% ആണ് &mdash; അതിനാൽ 60 മിനിറ്റ് റെസ്പോൺസ് ടാർഗെറ്റ്, 48 മിനിറ്റ് കഴിയുമ്പോൾ ആംബർ കാണിക്കും. മുന്നറിയിപ്പ്-ട്രിഗർ ബ്രീച്ച് അറിയിപ്പുകളും ഇത് നിയന്ത്രിക്കുന്നു.',
        ],
        'breach' => [
            'heading' => 'ബ്രീച്ച് അറിയിപ്പുകൾ',
            'sub' => 'SLA-കൾ ബ്രീച്ച് ആകാൻ അടുക്കുമ്പോൾ (മുന്നറിയിപ്പ്) അല്ലെങ്കിൽ യഥാർത്ഥത്തിൽ ബ്രീച്ച് ആകുമ്പോൾ പ്രവർത്തിക്കുന്ന, ഓരോ വകുപ്പിനും ക്രമീകരിക്കാവുന്ന ഇമെയിൽ നിയമങ്ങൾ.',
            'intro' => 'ഓരോ നിയമത്തിനും നാല് മാനങ്ങളുണ്ട്, എല്ലാം സ്വതന്ത്രം:',
            'scope_heading' => '1. സ്കോപ്പ്',
            'scope_body' => 'ഒന്നുകിൽ <strong>Default</strong> (എല്ലാ വകുപ്പിലെയും ടിക്കറ്റുകൾക്ക് നിയമം ബാധകമാണ്) അല്ലെങ്കിൽ ഒരു <strong>നിർദ്ദിഷ്ട വകുപ്പ്</strong>. തീരുമാനം: ആ വകുപ്പിലെ ടിക്കറ്റുകൾക്ക് ഒരു വകുപ്പ്-നിർദ്ദിഷ്ട നിയമം സ്ഥിരസ്ഥിതിയെക്കാൾ മുൻഗണന നേടും. ഒരു സ്ഥിരസ്ഥിതി നിയമമില്ലെങ്കിൽ, നിർദ്ദിഷ്ട നിയമമില്ലാത്ത വകുപ്പുകൾക്ക് അറിയിപ്പുകളൊന്നും ലഭിക്കില്ല.',
            'trigger_heading' => '2. ട്രിഗ്ഗർ',
            'trigger_body' => 'ഒന്നുകിൽ <strong>Warning</strong> (ടിക്കറ്റ് മുന്നറിയിപ്പ് ത്രെഷോൾഡ് കടന്നിരിക്കുന്നു &mdash; സാധ്യമായ ബ്രീച്ച്) അല്ലെങ്കിൽ <strong>Breach</strong> (ടിക്കറ്റ് അതിന്റെ ടാർഗെറ്റ് കടന്നിരിക്കുന്നു &mdash; യഥാർത്ഥ ബ്രീച്ച്). ഓരോന്നും അതിന്റേതായ നിയമമാണ്, അതിനാൽ ഓരോന്നിനും വ്യത്യസ്ത ആളുകളെ അറിയിക്കാം.',
            'target_heading' => '3. ടാർഗെറ്റ്',
            'target_body' => 'ഏത് ക്ലോക്ക് നിരീക്ഷിക്കണം &mdash; <strong>Response</strong>, <strong>Resolution</strong>, അല്ലെങ്കിൽ <strong>Both</strong>.',
            'recip_heading' => '4. സ്വീകർത്താക്കൾ',
            'recip_intro' => 'ഇവയുടെ ഏത് സംയോജനവും:',
            'recip_assignee' => '<strong>ടിക്കറ്റിന്റെ അസൈനി</strong> &mdash; നിലവിൽ ടിക്കറ്റ് ഏറ്റെടുത്തിരിക്കുന്ന അനലിസ്റ്റ്. നിയോഗിച്ചിട്ടില്ലെങ്കിൽ ഒഴിവാക്കും.',
            'recip_teams' => '<strong>ടിക്കറ്റിന്റെ വകുപ്പ് ടീമുകളിലെ അംഗങ്ങൾ</strong> &mdash; ടിക്കറ്റിന്റെ വകുപ്പുമായി ബന്ധിപ്പിച്ച ഏത് ടീമിലേയും ഓരോ അനലിസ്റ്റും. ഒരു ഡിസ്ട്രിബ്യൂഷൻ ലിസ്റ്റ് സൂക്ഷിക്കാതെ തന്നെ മുഴുവൻ ക്യൂവും ഉൾക്കൊള്ളുന്നു.',
            'recip_specific' => '<strong>ഒരു നിർദ്ദിഷ്ട അനലിസ്റ്റ്</strong> &mdash; "SLA ചാമ്പ്യൻ" / "സർവീസ് മാനേജർ" മാതൃക, ഇവിടെ അത് ഒരു റോൾ അല്ല, പേരുള്ള ഒരു വ്യക്തിയാണ്.',
            'recip_custom' => '<strong>കസ്റ്റം ഇമെയിൽ വിലാസങ്ങൾ</strong> &mdash; കോമയിട്ട് വേർതിരിച്ച ഫ്രീ-ടെക്സ്റ്റ്. പങ്കിട്ട ഇൻബോക്സുകൾക്ക് (<code>sla-alerts@company.com</code>), Slack/Teams ഇമെയിൽ ബ്രിഡ്ജുകൾക്ക്, അല്ലെങ്കിൽ ഡിസ്ട്രിബ്യൂഷൻ ലിസ്റ്റുകൾക്ക് ഉപകാരപ്രദം.',
            'tip' => 'ഓരോ ടിക്കറ്റും (ടാർഗെറ്റ്, ട്രിഗ്ഗർ) ഓരോന്നിനും കൂടിയാൽ ഒരു ഇമെയിൽ മാത്രമേ അയക്കൂ &mdash; അയച്ചത് എന്താണെന്ന് ക്രോൺ വർക്കർ <code>sla_notifications_sent</code> പട്ടികയിൽ ട്രാക്ക് ചെയ്യുന്നു. അതിനാൽ ഒരു മുന്നറിയിപ്പ് ഒരു തവണ, ഒരു ബ്രീച്ച് ഒരു തവണ, അത്രമാത്രം &mdash; സ്പാം ലൂപ്പുകളില്ല.',
            'warn' => '<strong>നിയമങ്ങളില്ല = ഇമെയിലുകളില്ല.</strong> സിസ്റ്റത്തിലെ എല്ലാ ടിക്കറ്റും ബ്രീച്ച് ആയാൽ പോലും, നിങ്ങൾ കുറഞ്ഞത് ഒരു നിയമമെങ്കിലും ചേർക്കുന്നത് വരെ ഒന്നും പ്രവർത്തിക്കില്ല. എല്ലാത്തിനും കവറേജ് ലഭിക്കാൻ ഒരു Default-സ്കോപ്പ് Warning + Breach ജോഡിയിൽ തുടങ്ങുക.',
        ],
        'cron' => [
            'heading' => 'ക്രോൺ ജോലി സജ്ജീകരിക്കൽ',
            'sub' => 'ബ്രീച്ച്-ചെക്ക് സ്ക്രിപ്റ്റ് ഒരു ഷെഡ്യൂളിൽ പ്രവർത്തിക്കേണ്ടതുണ്ട്. ഓരോ 5 മിനിറ്റിലും ഒരിക്കൽ ആണ് ഏറ്റവും അനുയോജ്യം.',
            'p1' => 'UI-യിൽ കാണുന്ന SLA ഇൻഡിക്കേറ്ററുകൾ (ഇൻബോക്സിലെ പില്ലുകൾ, റീഡിംഗ് പെയ്നിലെ പാനലുകൾ) ഒരു പേജ് ലോഡാകുമ്പോൾ തത്സമയം കണക്കാക്കുന്നു. പക്ഷേ ആരും നോക്കുന്നില്ലെങ്കിൽ പോലും <em>എന്തോ ഒന്ന്</em> മുൻകൈയെടുത്ത് ടിക്കറ്റുകൾ പരിശോധിച്ചാൽ മാത്രമേ ബ്രീച്ച് ഇമെയിലുകൾ അയക്കാൻ കഴിയൂ. അതാണ് ഒരു ഷെഡ്യൂൾ ചെയ്ത ടാസ്ക് &mdash; Windows-ൽ Task Scheduler; Linux-ൽ cron.',
            'p2' => 'സ്ക്രിപ്റ്റ് FreeITSM ഇൻസ്റ്റാൾ ഡയറക്ടറിയിലെ <code>cron/sla_breach_check.php</code> ആണ്. ഇത് രണ്ട് വിധത്തിൽ പ്രവർത്തിപ്പിക്കാം:',
            'cli_heading' => 'A. CLI (നിങ്ങൾ നിയന്ത്രിക്കുന്ന ഒരു സെർവറിൽ ശുപാർശ ചെയ്യുന്നത്)',
            'cli_note' => 'ഓതന്റിക്കേഷൻ ആവശ്യമില്ല &mdash; ഇത് ആർക്ക് പ്രവർത്തിപ്പിക്കാം എന്നത് ഫയൽസിസ്റ്റം അനുമതികൾ ഇതിനകം നിയന്ത്രിക്കുന്നു.',
            'http_heading' => 'B. HTTP (പങ്കിട്ട ഹോസ്റ്റിംഗിനോ റിമോട്ട് ഷെഡ്യൂളറുകൾക്കോ)',
            'http_note' => 'ആദ്യ ഇൻസ്റ്റാളിൽ ടോക്കൺ സ്വയമേവ സൃഷ്ടിക്കപ്പെടും, <code>sla_cron_token</code> എന്ന കീയ്ക്ക് കീഴിൽ <code>system_settings</code>-ൽ സൂക്ഷിക്കും (32 ഹെക്സ് അക്ഷരങ്ങൾ, ~128 ബിറ്റ് എൻട്രോപ്പി). ഇത് എൻക്രിപ്റ്റ് ചെയ്താണ് സൂക്ഷിക്കുന്നത്, അതിനാൽ വരി നേരിട്ട് വായിച്ചാൽ ടോക്കണിന് പകരം <code>ENC:…</code> ലഭിക്കും. നിങ്ങളുടേത് ഇങ്ങനെ കണ്ടെത്തുക:',
            'win_heading' => 'Windows Task Scheduler',
            'win_intro' => 'Task Scheduler (<code>taskschd.msc</code>) തുറന്ന് ഈ ക്രമീകരണങ്ങളോടെ ഒരു പുതിയ ടാസ്ക് സൃഷ്ടിക്കുക:',
            'tbl_field' => 'ഫീൽഡ്',
