            'win_r1_k' => 'പേര്',
            'win_r1_v' => 'FreeITSM &mdash; SLA Breach Check',
            'win_r2_k' => 'ഉപയോക്താവ് ലോഗിൻ ചെയ്തിട്ടുണ്ടോ ഇല്ലയോ എന്നത് പരിഗണിക്കാതെ പ്രവർത്തിപ്പിക്കുക',
            'win_r2_v' => 'ഇത് ടിക് ചെയ്യുക',
            'win_r3_k' => 'ട്രിഗ്ഗർ',
            'win_r3_v' => 'ദിവസേന, ഓരോ 1 ദിവസത്തിലും ആവർത്തിക്കുക, 1 ദിവസത്തേക്ക് ഓരോ 5 മിനിറ്റിലും ആവർത്തിക്കുക',
            'win_r4_k' => 'പ്രവർത്തനം',
