            'win_r5_k' => 'പ്രോഗ്രാം/സ്ക്രിപ്റ്റ്',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'ആർഗ്യുമെന്റുകൾ ചേർക്കുക',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'ഇവിടെ തുടങ്ങുക',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Linux cron',
            'linux_intro' => 'നിങ്ങളുടെ crontab-ൽ (<code>crontab -e</code>) ഒരു വരി ചേർക്കുക:',
            'sec_heading' => 'സുരക്ഷ &mdash; HTTP എൻഡ്പോയിന്റിനെ എന്താണ് സംരക്ഷിക്കുന്നത്',
            'sec_intro' => 'മൂന്ന് പാളികൾ, എല്ലാം സ്വയമേവ നടപ്പിലാക്കുന്നു:',
            'sec_token' => '<strong>1. Shared-secret token</strong> &mdash; ഓരോ ഇൻസ്റ്റാളിനും 128-ബിറ്റ് റാൻഡം, ടൈമിംഗ് ആക്രമണങ്ങൾ തടയാൻ കോൺസ്റ്റന്റ്-ടൈം മാച്ചിംഗ് ഉപയോഗിച്ച് താരതമ്യം ചെയ്യും.',
            'sec_lockout' => '<strong>2. Per-IP failed-auth lockout</strong> &mdash; കഴിഞ്ഞ ഒരു മണിക്കൂറിനുള്ളിൽ ഒരേ IP-യിൽ നിന്ന് 10-ൽ കൂടുതൽ തെറ്റായ-ടോക്കൺ ശ്രമങ്ങൾ 1-മണിക്കൂർ 429 ലോക്ക്ഔട്ട് ട്രിഗർ ചെയ്യും. fail2ban ആവശ്യമില്ലാതെ ബ്രൂട്ട്-ഫോഴ്സ് പരീക്ഷണത്തെ പരാജയപ്പെടുത്തുന്നു.',
            'sec_interval' => '<strong>3. Minimum interval between successful runs</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (സ്ഥിരസ്ഥിതി 30സെ). അവസാന വിജയകരമായ റണ്ണിന് ശേഷം ഇതിലും നേരത്തെ എത്തിയാൽ, സാധുവായ ടോക്കൺ ഉള്ള അഭ്യർത്ഥനയ്ക്ക് പോലും 429 ലഭിക്കും. ആകസ്മികമായ ഇരട്ട-ഷെഡ്യൂളിംഗിനെയും നിയന്ത്രണംവിട്ട ലൂപ്പുകളെയും ഇത് പരാജയപ്പെടുത്തുന്നു.',
            'log_heading' => 'ആക്റ്റിവിറ്റി ലോഗ്',
            'log_body' => 'ഓരോ വിളിയും (സ്വീകരിച്ചതോ നിരസിച്ചതോ) സമയം, ഫലം, എണ്ണങ്ങൾ, ക്ലയന്റ് IP എന്നിവയോടെ <code>sla_cron_runs</code> പട്ടികയിൽ ലോഗ് ചെയ്യും. SLA ക്രമീകരണ ടാബിന്റെ താഴെയുള്ള <strong>Cron Activity</strong> പാനലിൽ അവസാനത്തെ 20 റണ്ണുകൾ കാണുക &mdash; ഷെഡ്യൂൾ പ്രവർത്തിക്കുന്നുവെന്ന് പരിശോധിക്കാനും ഏതെങ്കിലും തെറ്റായ-ഓതന്റിക്കേഷൻ ശ്രമങ്ങൾ ഓഡിറ്റ് ചെയ്യാനും ഉപകാരപ്രദം. <code>sla_cron_log_retention_days</code>-ന് ശേഷം (സ്ഥിരസ്ഥിതി 30) വരികൾ സ്വയമേവ നീക്കം ചെയ്യും, അതിനാൽ പട്ടിക ചെറുതായി തുടരും.',
        ],
        'examples' => [
