            'ex1_heading' => 'ഉദാഹരണം 1: UK-ൽ ഉയർത്തിയ ടിക്കറ്റ്, സർവീസ് ഡെസ്ക് UK-ൽ',
            'ex1_title' => 'ലളിതമായ കേസ്',
            'ex1_tag' => 'ഒറ്റ ടൈംസോൺ',
            'ex1_setup' => '<strong>സജ്ജീകരണം:</strong> <code>Europe/London</code> ടൈംസോണുള്ള, തിങ്കൾ-വെള്ളി 09:00-17:00, അവധി ദിവസങ്ങളില്ലാത്ത <em>UK Office</em> എന്ന ഒരു ബിസിനസ് കലണ്ടർ. P2 മുൻഗണനയ്ക്ക് 1-മണിക്കൂർ റെസ്പോൺസ് ടാർഗെറ്റും 4-മണിക്കൂർ റെസലൂഷൻ ടാർഗെറ്റുമുണ്ട്, രണ്ടും <em>UK Office</em> കലണ്ടറിനെതിരെ പ്രവർത്തിക്കുന്നു.',
            'ex1_scenario' => '<strong>സാഹചര്യം:</strong> ഉപയോക്താവ് <strong>ബുധനാഴ്ച 16:30 UK</strong>-ന് ഒരു P2 ടിക്കറ്റ് ഉയർത്തുന്നു.',
            'ex1_timeline' => 'ബുധൻ 16:30 UK &mdash; <strong>ടിക്കറ്റ് സൃഷ്ടിച്ചു</strong>, റെസ്പോൺസ് ക്ലോക്ക് തുടങ്ങുന്നു.
ബുധൻ 17:00 UK &mdash; ഓഫീസ് അടയ്ക്കുന്നു, ക്ലോക്ക് നിർത്തുന്നു (60 മിനിറ്റ് ടാർഗെറ്റിൽ 30 മിനിറ്റ് ഉപയോഗിച്ചു).
വ്യാഴം 09:00 UK &mdash; ഓഫീസ് തുറക്കുന്നു, ക്ലോക്ക് വീണ്ടും തുടങ്ങുന്നു.
വ്യാഴം 09:30 UK &mdash; അനലിസ്റ്റ് മറുപടി നൽകുന്നു. റെസ്പോൺസ് SLA കൃത്യം അതിർത്തിയിൽ പാലിച്ചു (60 മിനിറ്റ് ഉപയോഗിച്ചു, 60 മിനിറ്റ് ടാർഗെറ്റ്).',
            'ex1_outro' => 'അനലിസ്റ്റ് <strong>വ്യാഴം 10:00 UK</strong> വരെ മറുപടി നൽകിയിരുന്നില്ലെങ്കിൽ, റെസ്പോൺസ് <strong>30 മിനിറ്റ് ബ്രീച്ച്</strong> ആയേനെ (60 മിനിറ്റ് ടാർഗെറ്റിനെതിരെ 90 മിനിറ്റ് ഉപയോഗിച്ചു &mdash; ബുധൻ വൈകുന്നേരത്തിൽ നിന്ന് 30, വ്യാഴം രാവിലെയിൽ നിന്ന് 60). 1-മണിക്കൂർ ക്ലോക്ക് ബിസിനസ് സമയത്ത് മാത്രമേ ടിക് ചെയ്യൂ, പക്ഷേ ഒരു ദിവസാവസാന ടിക്കറ്റ് ഓഫീസ് വീണ്ടും തുറക്കുമ്പോൾ രാത്രിയിൽ തന്നെ അതിന്റെ ബഡ്ജറ്റിന്റെ ഭൂരിഭാഗവും തിന്നും &mdash; 09:00-ന് എത്തുന്ന ഒരു അനലിസ്റ്റിന് പൂർണ്ണ മണിക്കൂർ ലഭിച്ചെന്ന് കരുതുന്നത് എളുപ്പമാണ്, യഥാർത്ഥത്തിൽ 30 മിനിറ്റ് മാത്രമേ ബാക്കിയുള്ളൂ എങ്കിലും.',
            'ex2_heading' => 'ഉദാഹരണം 2: UK-ൽ ഉയർത്തിയ ടിക്കറ്റ്, സർവീസ് ഡെസ്ക് എസ്റ്റോണിയയിൽ',
            'ex2_title' => 'ക്രോസ്-ടൈംസോൺ കേസ്',
            'ex2_tag' => '"ന്യായം" നിർവചിക്കാൻ 3 വഴികൾ',
            'ex2_setup' => '<strong>സജ്ജീകരണം:</strong> UK കസ്റ്റമേഴ്സ് (<code>Europe/London</code>, GMT/BST), എസ്റ്റോണിയ സർവീസ് ഡെസ്ക് (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>UK-യേക്കാൾ 2 മണിക്കൂർ മുന്നിൽ</strong>). രണ്ട് ഡെസ്കുകളും നാമമാത്രമായി പ്രാദേശിക സമയം 09:00-17:00 പ്രവർത്തിക്കുന്നു.',
            'ex2_scenario' => '<strong>സാഹചര്യം:</strong> UK കസ്റ്റമർ <strong>വെള്ളിയാഴ്ച 16:30 UK</strong>-ന് ഒരു P2 ടിക്കറ്റ് ഉയർത്തുന്നു (= 18:30 എസ്റ്റോണിയ, എസ്റ്റോണിയ അടച്ചതിന് ശേഷം). ഒരു എസ്റ്റോണിയ അനലിസ്റ്റിന് ഇത് പ്രവർത്തിക്കാനുള്ള അടുത്ത അവസരം തിങ്കൾ 09:00 എസ്റ്റോണിയ (= 07:00 UK) ആണ്. റെസ്പോൺസ് ടാർഗെറ്റ് 1 മണിക്കൂറാണ്.',
            'ex2_question' => 'SLA എന്താണ് പറയേണ്ടത്? ന്യായീകരിക്കാവുന്ന മൂന്ന് ഉത്തരങ്ങളുണ്ട്, ഓരോന്നും വ്യത്യസ്ത അർത്ഥത്തിൽ ന്യായമാണ്. നിങ്ങളുടെ സർവീസ് കരാർ എന്ത് വാഗ്ദാനം ചെയ്യുന്നു എന്നതിനെ അടിസ്ഥാനമാക്കി മുൻഗണനയ്ക്ക് ഏത് കലണ്ടർ നൽകണമെന്ന് നിങ്ങൾ തിരഞ്ഞെടുക്കുക.',
            'optA_label' => 'ഓപ്ഷൻ A &mdash; കസ്റ്റമർ-കേന്ദ്രീകൃതം',
            'optA_p1' => '<strong>അനലിസ്റ്റ് എവിടെയായിരുന്നാലും <em>UK</em> സമയമുള്ള ഒരു കലണ്ടർ ഉപയോഗിക്കാൻ മുൻഗണന സജ്ജമാക്കുക.</strong> ക്ലോക്ക് UK 09:00-17:00-നെതിരെ ടിക് ചെയ്യുന്നു.',
            'optA_p2' => 'മുകളിലെ സാഹചര്യത്തിൽ, വെള്ളി 16:30 UK-ന് ടിക്കറ്റ് ഉയർത്തി: ക്ലോക്ക് വെള്ളി 16:30&ndash;17:00 UK പ്രവർത്തിക്കുന്നു (30 മിനിറ്റ് ഉപയോഗിച്ചു), രാത്രി + വാരാന്ത്യം നിർത്തുന്നു, തിങ്കൾ 09:00 UK-ന് വീണ്ടും തുടങ്ങുന്നു. ഒരു എസ്റ്റോണിയ അനലിസ്റ്റ് തിങ്കൾ 10:00 എസ്റ്റോണിയ (= 08:00 UK)-ന് മറുപടി നൽകിയാൽ, UK കലണ്ടർ ഇപ്പോഴും നിർത്തിയിരിക്കുന്നു (UK ഓഫീസ് 09:00 UK-ന് തുറക്കുന്നു), അതിനാൽ കൂടുതൽ മിനിറ്റുകളൊന്നും ടിക് ചെയ്യില്ല &mdash; ഉപയോഗം 30 മിനിറ്റിൽ തന്നെ നിൽക്കുന്നു. <strong>30 മിനിറ്റ് മാർജിനോടെ SLA പാലിച്ചു</strong>. 09:30 UK (= 11:30 എസ്റ്റോണിയ)-ന് ശേഷമുള്ള ഏത് മറുപടിയും ബ്രീച്ച് ആകും.',
            'optA_p3' => '<em>ന്യായം ഇവർക്ക്:</em> കസ്റ്റമർക്ക്. അവരുടെ അനുഭവം അവരുടെ പ്രവൃത്തി ദിവസവുമായി പൊരുത്തപ്പെടുന്നു.<br><em>ട്രേഡ്-ഓഫ്:</em> എസ്റ്റോണിയ അനലിസ്റ്റുകൾ UK സമയം 09:00-17:00 (= എസ്റ്റോണിയ 11:00-19:00) ലഭ്യമായിരിക്കുമെന്ന് പ്രതീക്ഷിക്കുന്നു, ഇത് അവരുടെ പ്രവൃത്തി ദിവസം 2 മണിക്കൂർ നീട്ടുന്നു.',
            'optB_label' => 'ഓപ്ഷൻ B &mdash; അനലിസ്റ്റ്-കേന്ദ്രീകൃതം',
            'optB_p1' => '<strong><em>എസ്റ്റോണിയ</em> സമയമുള്ള ഒരു കലണ്ടർ ഉപയോഗിക്കാൻ മുൻഗണന സജ്ജമാക്കുക.</strong> ക്ലോക്ക് എസ്റ്റോണിയ 09:00-17:00-നെതിരെ ടിക് ചെയ്യുന്നു.',
            'optB_p2' => 'അതേ സാഹചര്യം: വെള്ളി 18:30 എസ്റ്റോണിയ (അടച്ചതിന് ശേഷം) ടിക്കറ്റ് ഉയർത്തി, ക്ലോക്ക് വാരാന്ത്യം മുഴുവൻ നിർത്തിയിരുന്നു, തിങ്കൾ 09:00 എസ്റ്റോണിയ (= 07:00 UK)-ന് ടിക് ചെയ്യാൻ തുടങ്ങുന്നു. അനലിസ്റ്റ് തിങ്കൾ 09:30 എസ്റ്റോണിയ (= 07:30 UK)-ന് പ്രതികരിച്ചാൽ, റെസ്പോൺസ് SLA 60 മിനിറ്റ് ടാർഗെറ്റിൽ 30 മിനിറ്റ് ഉപയോഗിച്ചു &mdash; <strong>30 മിനിറ്റ് മാർജിനോടെ പാലിച്ചു</strong>. UK കസ്റ്റമർ വെള്ളി 16:30 UK-ന് ഉയർത്തി, തിങ്കൾ 07:30 UK-ന് മറുപടി ലഭിച്ചു &mdash; അവരുടെ വാൾ-ക്ലോക്ക് കാത്തിരിപ്പ് SLA സൂചിപ്പിക്കുന്നതിനേക്കാൾ വളരെ കൂടുതലായിരുന്നു.',
            'optB_p3' => '<em>ന്യായം ഇവർക്ക്:</em> അനലിസ്റ്റുകൾക്ക്. അവർ സാധാരണ സമയത്ത് ജോലി ചെയ്യുന്നു.<br><em>ട്രേഡ്-ഓഫ്:</em> ഒരു വെള്ളിയാഴ്ച ഉച്ചയ്ക്ക് ശേഷമുള്ള ടിക്കറ്റ് തിങ്കളാഴ്ച രാവിലെ എസ്റ്റോണിയ സമയം വരെ അംഗീകരിച്ചില്ലെങ്കിലും റിപ്പോർട്ട് റെസ്പോൺസ് SLA 1 മണിക്കൂർ ആയിരുന്നു എന്ന് പറഞ്ഞാൽ, UK-യിലെ കസ്റ്റമേഴ്സിന് SLA "കള്ളം പറയുന്നു" എന്ന് തോന്നാം. SLA സപ്പോർട്ട്-ഡെസ്ക് സമയത്തിനെതിരെയാണ് പ്രവർത്തിക്കുന്നത് എന്ന് നിങ്ങളുടെ സർവീസ് കരാറിൽ വ്യക്തമാക്കിയിട്ടുണ്ടെന്ന് ഉറപ്പാക്കുക.',
            'optC_label' => 'ഓപ്ഷൻ C &mdash; ഓവർലാപ്പ് വിൻഡോ (ഏറ്റവും കർശനം)',
            'optC_p1' => '<strong>രണ്ട് ഡെസ്കുകളും തുറന്നിരിക്കുന്ന സമയം മാത്രം ഉൾക്കൊള്ളുന്ന ഒരു കലണ്ടർ ഉപയോഗിക്കാൻ മുൻഗണന സജ്ജമാക്കുക.</strong> UK 09:00-17:00, എസ്റ്റോണിയ 09:00-17:00 (= UK 07:00-15:00)-മായി <strong>UK 09:00-15:00 വിൻഡോയിൽ</strong> ഓവർലാപ്പ് ചെയ്യുന്നു &mdash; ഓരോ പ്രവൃത്തി ദിവസവും 6 മണിക്കൂർ.',
            'optC_p2' => 'അതേ സാഹചര്യം: വെള്ളി 16:30 UK-ന് ടിക്കറ്റ് ഉയർത്തി (ഓവർലാപ്പിന് പുറത്ത്, കാരണം ഓവർലാപ്പ് 15:00 UK-ന് അടയുന്നു), ക്ലോക്ക് വാരാന്ത്യം നിർത്തിയിരുന്നു, തിങ്കൾ 09:00 UK (= 11:00 എസ്റ്റോണിയ, ഓവർലാപ്പ് വീണ്ടും തുറക്കുന്ന നിമിഷം)-ന് വീണ്ടും തുടങ്ങുന്നു. എസ്റ്റോണിയ അനലിസ്റ്റ് 11:30 എസ്റ്റോണിയ (= 09:30 UK)-ന് മറുപടി നൽകിയാൽ, റെസ്പോൺസ് SLA 60 മിനിറ്റ് ടാർഗെറ്റിൽ 30 മിനിറ്റ് ഉപയോഗിച്ചു &mdash; <strong>30 മിനിറ്റ് മാർജിനോടെ പാലിച്ചു</strong>. മറുപടി ഓവർലാപ്പ് വിൻഡോയിൽ സംഭവിച്ചതിനാൽ അത് ഉടൻ തന്നെ കണക്കാക്കും.',
            'optC_p3' => '<em>ന്യായം ഇവർക്ക്:</em> ഇരുപക്ഷത്തിനും &mdash; ഡെസ്കിന് യഥാർത്ഥത്തിൽ ടിക്കറ്റ് മുന്നോട്ട് കൊണ്ടുപോകാൻ കഴിയുന്ന, കസ്റ്റമർ ഒരു മറുപടി ലഭിക്കാൻ ഡെസ്കിലുള്ള സമയത്ത് മാത്രമേ SLA ടിക് ചെയ്യൂ.<br><em>ട്രേഡ്-ഓഫ്:</em> ചെറിയ ദൈനംദിന വിൻഡോ എന്നാൽ ആക്രമണാത്മക ടാർഗെറ്റുകൾ പാലിക്കാൻ കൂടുതൽ വാൾ-ക്ലോക്ക് സമയം വേണം എന്നാണ്. ഒരു സാധാരണ 8-മണിക്കൂർ കലണ്ടറിൽ ഒരു ദിവസത്തിനുള്ളിൽ തീരുമായിരുന്ന 4-മണിക്കൂർ റെസലൂഷൻ ടാർഗെറ്റ്, ഓവർലാപ്പിന്റെ 1.5 ദിവസത്തോളം നീളും.',
            'choose_tip' => '<strong>എങ്ങനെ തിരഞ്ഞെടുക്കാം:</strong> നിങ്ങളുടെ സർവീസ് കരാർ നോക്കുക. "receipt-ന്റെ 1 മണിക്കൂറിനുള്ളിൽ റെസ്പോൺസ്" എന്നാണെങ്കിൽ &mdash; അതാണ് ഓപ്ഷൻ A (കസ്റ്റമറുടെ ക്ലോക്ക്). "1 പ്രവൃത്തി മണിക്കൂറിനുള്ളിൽ റെസ്പോൺസ്" എന്നാണെങ്കിൽ &mdash; സാധാരണയായി അതാണ് ഓപ്ഷൻ B (ഏത് ഡെസ്ക് പ്രവർത്തിക്കുന്നോ അത്). "പരസ്പര ലഭ്യതയുടെ 1 മണിക്കൂറിനുള്ളിൽ" എന്നാണെങ്കിൽ &mdash; അതാണ് ഓപ്ഷൻ C. കരാർ ഒന്നുമില്ലെങ്കിൽ, ടീമിനോട് ചോദിക്കുക: എസ്റ്റോണിയ സമയത്തിന് പുറത്ത് സമ്മർദ്ദം തോന്നണോ (ഓപ്ഷൻ A), അതോ UK കസ്റ്റമേഴ്സിന് ഇടയ്ക്കിടെ അവഗണിക്കപ്പെട്ടതായി തോന്നണോ (ഓപ്ഷൻ B)?',
            'ex3_heading' => 'ഉദാഹരണം 3: വെണ്ടർ കാത്തിരിപ്പിനിടെ ക്ലോക്ക് നിർത്തൽ',
            'ex3_title' => 'പോസ് നിലകൾ പ്രായോഗികമായി എങ്ങനെ പ്രവർത്തിക്കുന്നു',
            'ex3_tag' => 'ക്ലോക്ക്-നിർത്തൽ',
            'ex3_setup' => '<strong>സജ്ജീകരണം:</strong> 8 ബിസിനസ്-മണിക്കൂർ റെസലൂഷൻ ടാർഗെറ്റുള്ള P3 മുൻഗണന, UK കലണ്ടർ, "Awaiting Vendor" നില <em>Pause SLA</em> ആയി ഫ്ലാഗ് ചെയ്തിരിക്കുന്നു.',
            'ex3_scenario' => '<strong>സാഹചര്യം:</strong> തിങ്കൾ 09:00 UK-ന് ടിക്കറ്റ് ഉയർത്തി. അനലിസ്റ്റ് തിങ്കൾ 11:00 UK-ന് Microsoft-ലേക്ക് എസ്കലേറ്റ് ചെയ്ത് ടിക്കറ്റ് "Awaiting Vendor" ആക്കുന്നു. Microsoft ബുധൻ 14:00 UK-ന് മറുപടി നൽകുന്നു. അനലിസ്റ്റ് പരിഹാരം നടപ്പിലാക്കി വ്യാഴം 10:00 UK-ന് അടയ്ക്കുന്നു.',
            'ex3_timeline' => 'തിങ്കൾ 09:00 &mdash; ടിക്കറ്റ് സൃഷ്ടിച്ചു, റെസലൂഷൻ ക്ലോക്ക് പ്രവർത്തിക്കുന്നു.
തിങ്കൾ 11:00 &mdash; "Awaiting Vendor" ആയി മാറ്റി, <strong>ക്ലോക്ക് നിർത്തി</strong> (2മണിക്കൂർ ഉപയോഗിച്ചു).
ബുധൻ 14:00 &mdash; "In Progress" ആയി തിരികെ മാറ്റി, <strong>ക്ലോക്ക് വീണ്ടും തുടങ്ങുന്നു</strong>.
ബുധൻ 17:00 &mdash; ഓഫീസ് അടയ്ക്കുന്നു (ആകെ 5മണിക്കൂർ ഉപയോഗിച്ചു).
വ്യാഴം 09:00 &mdash; ഓഫീസ് തുറക്കുന്നു.
വ്യാഴം 10:00 &mdash; ടിക്കറ്റ് അടച്ചു (ആകെ 6മണിക്കൂർ ഉപയോഗിച്ചു). 8മണിക്കൂർ ടാർഗെറ്റിനെതിരെ <strong>SLA പാലിച്ചു</strong>.',
            'ex3_outro' => 'വാൾ-ക്ലോക്ക് കടന്നുപോയത്: ~3 ദിവസം. SLA കടന്നുപോയത്: 6 പ്രവൃത്തി മണിക്കൂർ. പോസ്-നില ഫ്ലാഗ് ഇല്ലായിരുന്നെങ്കിൽ, SLA വെണ്ടർ കാത്തിരിപ്പിന്റെ 2 ദിവസം മുഴുവനും + ബിസിനസ് സമയവും കണക്കാക്കുമായിരുന്നു, ആകെ ~18 പ്രവൃത്തി മണിക്കൂർ &mdash; ബ്രീച്ചിന് വളരെ മുകളിൽ.',
        ],
