            'r1_s' => 'ഇൻബോക്സിൽ SLA പില്ലുകളൊന്നും കാണിക്കുന്നില്ല',
            'r1_c' => '<code>Enforce SLAs from</code> ശൂന്യമാണ്, മുൻഗണനയ്ക്ക് ടാർഗെറ്റുകളൊന്നും സജ്ജമല്ല, അല്ലെങ്കിൽ ടിക്കറ്റ് കട്ട്ഓഫിന് മുമ്പുള്ളതാണ്.',
            'r2_s' => 'SLA ബ്രീച്ച് ആയി കാണിക്കുന്നു, പക്ഷേ അനലിസ്റ്റ് ടാർഗെറ്റിനുള്ളിൽ മറുപടി നൽകി',
            'r2_c' => 'മുൻഗണന മാറ്റ ചരിത്രം പരിശോധിക്കുക &mdash; മുൻഗണന ഇടയ്ക്ക് അപ്ഗ്രേഡ് ചെയ്തതും പെരുമാറ്റം "Forward" (സ്ഥിരസ്ഥിതി) ആയി സജ്ജമാക്കിയതും ആണെങ്കിൽ, സഞ്ചയിച്ച സമയം തുടരും.',
            'r3_s' => 'ബ്രീച്ച് അറിയിപ്പുകൾ അയക്കുന്നില്ല',
            'r3_c' => '(1) നിയമങ്ങളൊന്നും ക്രമീകരിച്ചിട്ടില്ല. (2) ക്രോൺ ജോലി ഷെഡ്യൂൾ ചെയ്തിട്ടില്ല. (3) നിയമങ്ങൾ ക്രമീകരിച്ചിട്ടുണ്ട്, പക്ഷേ സ്വീകർത്താക്കളെ കണ്ടെത്താനാവില്ല (അസൈനി ഇല്ല, വകുപ്പ് ടീമുകൾക്ക് ഇമെയിലുള്ള അംഗങ്ങളില്ല). ഓരോ റണ്ണിന്റെയും സംഗ്രഹത്തിന് Cron Activity പാനൽ പരിശോധിക്കുക.',
            'r4_s' => 'ക്രോൺ പ്രവർത്തിക്കുന്നു, പക്ഷേ "no matching rule" എന്ന് റിപ്പോർട്ട് ചെയ്യുന്നു',
            'r4_c' => 'എല്ലാ വകുപ്പും ഉൾപ്പെടാൻ കുറഞ്ഞത് ഒരു Default-സ്കോപ്പ് നിയമമെങ്കിലും ചേർക്കുക.',
            'r5_s' => 'Watchtower "N tickets paused over 24h" എന്ന് കാണിക്കുന്നു',
            'r5_c' => 'ടിക്കറ്റുകൾ ഒരു പോസ്-SLA നിലയിൽ ഇരിക്കുകയാണ്. ആരെങ്കിലും അവ മനഃപൂർവ്വം പാർക്ക് ചെയ്ത് മറന്നതാകാം, അല്ലെങ്കിൽ ആരെങ്കിലും On Hold SLA-യിൽ നിന്ന് രക്ഷപ്പെടാനുള്ള വാൽവായി ഉപയോഗിക്കുന്നതാകാം. ഓരോന്നിലും ക്ലിക്ക് ചെയ്ത് ഒന്നുകിൽ മുന്നോട്ട് കൊണ്ടുപോകുക അല്ലെങ്കിൽ പോസ് നില ഒഴിവാക്കുക.',
            'r6_s' => 'HTTP ക്രോൺ 403 തിരികെ നൽകുന്നു',
            'r6_c' => 'URL-ലെ ടോക്കൺ പൊരുത്തപ്പെടുന്നില്ല. <code>SELECT setting_value FROM system_settings WHERE setting_key = \'sla_cron_token\'</code> വഴി കണ്ടെത്തുക.',
            'r7_s' => 'HTTP ക്രോൺ 429 "Rate limited" തിരികെ നൽകുന്നു',
            'r7_c' => '<code>sla_cron_min_interval_seconds</code>-ൽ (സ്ഥിരസ്ഥിതി 30സെ) കുറഞ്ഞ സമയം മുമ്പ് ഒരു വിജയകരമായ റൺ പൂർത്തിയായി. കാത്തിരിക്കുക അല്ലെങ്കിൽ ക്രമീകരണം കുറയ്ക്കുക.',
            'r8_s' => 'HTTP ക്രോൺ 429 "Too many failed attempts" തിരികെ നൽകുന്നു',
            'r8_c' => 'ഈ IP കഴിഞ്ഞ ഒരു മണിക്കൂറിനുള്ളിൽ 10-ൽ കൂടുതൽ തെറ്റായ-ടോക്കൺ ശ്രമങ്ങൾ നടത്തിയിട്ടുണ്ട്. 1 മണിക്കൂർ കാത്തിരിക്കുക അല്ലെങ്കിൽ പരാജയങ്ങൾ മായ്ക്കുക: <code>DELETE FROM sla_cron_runs WHERE client_ip = \'...\' AND outcome = \'auth_failed\'</code>.',
            'tip' => 'ക്രോൺ സജ്ജീകരണത്തിന്റെ, Linux ഉദാഹരണങ്ങളും റിമോട്ട്-ഷെഡ്യൂളർ സംയോജനവും ഉൾപ്പെടെയുള്ള, ആഴത്തിലുള്ള സാങ്കേതിക വിശദീകരണത്തിന്, FreeITSM ഇൻസ്റ്റാൾ ഡയറക്ടറിയിലെ <code>docs/sla-cron-setup.md</code> കാണുക.',
